L6_1 = "SI_SKIN_DESC_NKM_UNIT_SHARKS_C_CLAW_MAID"
L7_1 = "Dịch vụ giúp việc của cô gái liều lĩnh đã bắt đầu.\nĐã là một sự may mắn khi cô tránh được mọi tai nạn, nhưng đáng ngạc nhiên là, cô ấy lại là trung tâm chú ý của khách hàng.\nHy vọng rằng sẽ không có bất kỳ cuộc ẩu đả lớn nào trong cửa hàng.\nXét cho cùng thì đây cũng không phải là quán rượu.\n\n<color=#ffd34c>Ha ha ha. Ngài muốn chơi cùng tôi? Được thôi ạ. Nhưng tôi sẽ không chịu trách nhiệm nếu ngài quá phấn khích và gãy xương đâu nhé.</color>"
L5_1[1] = L6_1
L5_1[2] = L7_1
L6_1 = {}
L7_1 = "SI_SKIN_DESC_NKM_UNIT_HARMONY_C_TRUMPET_MAID"
L8_1 = "Ôi, trời! Nghe tiếng ầm to đùng ấy giống như cô ấy lại bị tai nạn.\nCô ấy có lẽ hơi vụng về và háu ăn như hà mã luôn ăn đồ ăn vặt của chủ nhân, nhưng cô ấy vẫn là người giúp việc nhà mà không thể không giữ bên mình.\nNhưng, nếu quá khoan dung thì sẽ chẳng giúp ích gì, nên thỉnh thoảng sẽ cần phải la mắng một chút.\n\n<color=#ffd34c>Người giúp việc tốt nhất có đãi ngộ như vậy là rất bình thường mà!</color>"
