L3_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_SHARKS_C_KNIFE"
L4_1 = "Sonya là thành viên mới nhất của Cá Mập Vịnh Trước, nhưng cô ấy có nhiều trách nhiệm nhất. Cô kiểm tra con tàu trước khi ra khơi, quản lý tài chính của họ bằng sổ sách kế toán, nấu ăn và làm trung gian cho thủy thủ đoàn và thuyền trưởng bất cứ khi nào họ cư xử thất thường.\n\nMặc dù có ý thức chung hơn những tên Hải Tặc khác, cô vẫn là một kẻ sống ngoài vòng pháp luật. Nếu cô ấy bắt bạn làm tù nhân trên biển, đừng mong cô ấy thể hiện bất kỳ dấu hiệu tử tế nào. Tuy nhiên, nếu bạn thích hải sản, đặc biệt là vì bạn nhận ra giá trị của cá, bạn có thể hòa hợp với cô ấy dễ dàng hơn."
L2_1[1] = L3_1
L2_1[2] = L4_1
L3_1 = {}
L4_1 = "SI_PF_DEFENCE_BANNER_01_DESC_1"
L5_1 = "Có thể bạn đã biết, biển ở Vịnh Trước không bao giờ lặng yên vì bọn Hải Tặc liên tục đánh nhau. Những người đi biển được định sẵn là sẽ ra khơi, bất chấp tất cả.\n\nThuyền trưởng, đã đến lúc nhổ neo và ra khơi thôi! Vì trận Lũ Đen, V.T.A.M. năm nay sẽ là một món lợi lớn! Bất cứ điều gì cản đường chúng ta, dù là sóng hay con người, hãy lưu lại tên mình trên mặt nước! Chúng ta có thể bỏ lại bọt biển phía sau, nhưng chúng ta sẽ không bao giờ để lại bất kỳ sự tiếc nuối nào!"
