L3_1 = {}
L4_1 = "SI_PF_RECALL_POPUP_SUBTITLE"
L5_1 = "Sau khi triệu hồi nhân viên hoặc tàu đã chọn, sẽ truy xuất các tài nguyên tăng trưởng ngay lập tức. Trang bị của nhân viên sẽ được đưa trở lại Kho lưu trữ.\nNó sẽ được thay thế bằng một nhân viên <color=#ffcf3b>Cấp độ 1</color>, người sẽ kế thừa cấp độ Cập Nhật Chiến Thuật của nhân viên đã chọn."
L3_1[1] = L4_1
L3_1[2] = L5_1
L4_1 = {}
L5_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EP10_ACT1_PROLOGUE"
L6_1 = "Nếu một người có thể quan sát, họ cũng có thể can thiệp. Tất nhiên là khi người đó sẵn sàng làm gián đoạn chu kỳ may-rủi đầy mong manh."
L4_1[1] = L5_1
L4_1[2] = L6_1
L5_1 = {}
L6_1 = "SI_EPISODE_EPISODE_DESC_NKM_MAIN_BATTLE_EP10_4_3"
L7_1 = "Từ thế hệ này sang thế hệ khác, thế kỷ này sang thế kỷ khác, nền văn minh không ngừng trải qua sự thăng trầm, sự thật tạo nên thế giới này cũng vậy."
L5_1[1] = L6_1
L5_1[2] = L7_1
L6_1 = {}
L7_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EP10_ACT4_INTERLUDE_1"
L8_1 = "Kẻ Thì Thầm. Một kẻ luôn ngờ vực, chê bôi và cười nhạo. Kẻ gây ra sự hỗn loạn, máu và đau khổ."
L6_1[1] = L7_1
L6_1[2] = L8_1
L7_1 = {}
L8_1 = "SI_UNIT_SKILL_DESC_FALLEN_CA_ROSARIA_ATTACK_LV1"
L9_1 = "Ném ngọn lửa của Chúa Quỷ gây sát thương AoE cho nhiều mục tiêu và các mục tiêu ở gần, và gây ra thêm sát thương đảm bảo CRIT khi chỉ một mục tiêu trúng đòn. Nhắm vào các đơn vị Trên Không trong phạm vi đầu tiên. Không áp dụng cho các mục tiêu vượt quá lượt Đánh Trúng Hợp Lệ."
L7_1[1] = L8_1
L7_1[2] = L9_1
L8_1 = {}
L9_1 = "SI_UNIT_SKILL_DESC_KNIGHT_CA_SAVIOR_HYPER_LV1"
L10_1 = "Giải phóng sức mạnh của mình và gây sát thương AoE cho kẻ thù ở gần. Trở nên miễn nhiễm với CC và Hitstun từ KN Tối Thượng trở xuống, trong khi SPD giảm 60% và đòn tấn công cơ bản thay đổi thành đòn tấn công gây ra Đẩy Lùi mạnh mẽ trong 12 giây. (Hitstun của đòn tấn công này được coi là Hitstun Kỹ Năng Tối Thượng). Trở nên vô địch trong khi di chuyển. \n *Miễn nhiễm với CC◇: Choáng◇, Ngủ, Sợ hãi, Hỗn Loạn, Đóng Băng và Trói Buộc◇"
L8_1[1] = L9_1
L8_1[2] = L10_1
L9_1 = {}
L10_1 = "SI_EPISODE_EPISODE_DESC_NKM_MAIN_BATTLE_EP10_3_4"
L11_1 = "Gió thổi đến đâu, nước chảy đến đó. Người đặt ra mục tiêu luôn kiên định với mục tiêu đó cho đến cuối cùng."
L9_1[1] = L10_1
L9_1[2] = L11_1
L10_1 = {}
L11_1 = "SI_EPISODE_EPISODE_DESC_NKM_MAIN_BATTLE_EP10_1_3"
L12_1 = "Tới cuối cùng, chẳng có gì là vĩnh viễn. Ngay cả hào quang của ngai vàng hay lời thề nguyện mà chúng ta đã lập ra cùng nhau."
L10_1[1] = L11_1
L10_1[2] = L12_1
L11_1 = {}
L12_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EP10_ACT1_INTERLUDE_3"
L13_1 = "Chúa Quỷ là kẻ thống trị mọi tội ác. Tuy nhiên, chúng cũng là một trong những trụ cột góp phần duy trì thế giới này."
L11_1[1] = L12_1
L11_1[2] = L13_1
