L19_1 = "SI_UNIT_SKILL_DESC_JAPAN_CA_SENHIME_SKILL_LV1"
L20_1 = "Chifuyu lao qua phòng tuyến của kẻ thù, sử dụng thanh kiếm của Thần Âm Ty và Kiếm Narcissus. Khiến cho kẻ địch bị sát thương -50% EVA và HIT trong 7 giây. Sau đó trở lại vị trí ban đầu, gây sát thương AoE lên khu vực xung quanh một lần nữa."
L18_1[1] = L19_1
L18_1[2] = L20_1
L19_1 = {}
L20_1 = "SI_UNIT_SKILL_DESC_JAPAN_CA_SENHIME_HYPER_LV1"
L21_1 = "Chifuyu giải phóng sức mạnh thực sự của Thanh Kiếm Của Thần Âm Ty và chém nát linh hồn của kẻ thù của cô ấy. Ra đòn AoE gây Hitstun, Đẩy Lùi và Văng Lên Trời bằng 3 đòn tấn công. Hủy bỏ Rào Chắn của kẻ thù bị trúng đòn từ đòn tấn công đầu tiên, tiêu diệt ngay lập tức kẻ thù có 50% HP trở xuống sau đòn tấn công cuối cùng. (Trừ Boss)"
L19_1[1] = L20_1
L19_1[2] = L21_1
L20_1 = {}
L21_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_NANAHARA2_1_INTERLUDE2"
L22_1 = "Bảo vệ lãnh địa không phải là một nhiệm vụ dễ dàng. Mục tiêu quan trọng nhất là giữ bí mật được ẩn giấu trong lãnh địa của chúng ta với thực tại bên ngoài."
L20_1[1] = L21_1
L20_1[2] = L22_1
L21_1 = {}
L22_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_NANAHARA2_1_INTERLUDE3"
L23_1 = "Sư đoàn Gordias là tổ chức cần thiết để tổ tiên của chúng ta có thể ổn định trong thực tại. Để lấy lại thế giới mà họ từng chung sống hưng thịnh giữa các vị thần, Sư Đoàn Gordias đã chiến đấu cùng Cục Quản Lý và ngăn chặn ngày tận thế."
L21_1[1] = L22_1
L21_1[2] = L23_1
