L23_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_NANAHARA2_3_4"
L24_1 = "Kẻ chờ đợi thần linh thức tỉnh từ vô minh sẽ chỉ càng lầm đường lạc lối."
L22_1[1] = L23_1
L22_1[2] = L24_1
