L24_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_NANAHARA2_1_PROLOGUE1"
L25_1 = "Ngay cả sau khi mất đi thần tính, nữ tư tế vẫn mơ về cùng một khoảnh khắc hàng đêm.\nKhoảnh khắc cô ấy nhìn vào mắt của chiếc mặt nạ."
