L26_1 = "Sử dụng {0} Mảnh Vỡ Linh Hồn của Quỷ Bệnh Dịch"
L24_1[1] = L25_1
L24_1[2] = L26_1
L25_1 = {}
L26_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_JAPAN_CA_SENHIME"
L27_1 = "Orochinagi Nanahara Chifuyu là Lính Tấn Công làm suy yếu kẻ thù và càng trở nên mạnh hơn khi nhận sát thương.\n\nTrường Phái Nanahara bắt nguồn từ kiếm thuật của Thần Âm Ty, một bậc thầy kiếm thuật. Tổ tiên của Liên Minh Gia Tộc đã nỗ lực trong một thời gian rất dài để hoàn thiện trường phái này, tuy nhiên, họ vẫn không thành công. Dường như, để một con người bình thường trở thành huyền thoại là điều không thể xảy ra, vì họ không chỉ cần nhanh và mạnh, mà cần cả không sợ hãi cái chết. Hậu duệ Nanahara tin rằng hoàn thiện Thần Khí có tên là \"Orochinagi\" sẽ là câu trả lời. \n\nTrải qua mọi thử thách gian truân, cuối cùng cô cũng giành được Orochinagi, để có thể xuyên thủng cái gọi là khải huyền định mệnh và tiếp tục tiến lên phía trước."
L25_1[1] = L26_1
L25_1[2] = L27_1
L26_1 = {}
L27_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_NANAHARA2_2_INTERLUDE1"
L28_1 = "Hỡi thần của Thế Giới Bên Kia. Hỡi những tổ tiên đã chiến đấu chống lại nghiệp chướng muôn đời. Hỡi giọng nói của gió... Hậu duệ của ngài cầu xin được chỉ dẫn."
L26_1[1] = L27_1
L26_1[2] = L28_1
L27_1 = {}
L28_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_NANAHARA2_1_INTERLUDE4"
L29_1 = "Thế Giới Bên Kia là cây thập tự giá mà chúng ta phải gánh vác, để chúng ta sống trong thực tại. Đừng chối bỏ nó. Cho dù có bao nhiêu thời gian trôi qua đi chăng nữa...hãy luôn nhớ tới cái chết."
L27_1[1] = L28_1
