L33_1 = "Trở thành Bất tử trong 5 giây khi HP giảm xuống dưới 1% (hiệu ứng không thể hủy bỏ)"
L31_1[1] = L32_1
L31_1[2] = L33_1
L32_1 = {}
L33_1 = "BC_NANAHARA2_3_NAME"
L34_1 = "Hợp Thể Với Thần"
L32_1[1] = L33_1
L32_1[2] = L34_1
L33_1 = {}
L34_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_JAPAN_SETSUNA_RA"
L35_1 = "Một vị thần mất đi thế giới của riêng mình sẽ dần trở nên méo mó. Nhân loại lạc lối cũng giống như vậy. Nhưng đôi khi, một thứ nhỏ bé như một bông hoa anh đào có thể nảy mầm sự sống mới. Nanahara Chinatsu nở rộ và chữa lành vết thương nhờ sức mạnh của huyết thống thiêng liêng được kế thừa. Cô ấy hồi sinh những sinh vật sắp chết và thay đổi vòng quay định mệnh. \nVì thế giới nhỏ bé mà mình muốn bảo vệ, cô ấy sẽ không bao giờ từ bỏ khám phá tiềm năng của bản thân."
L33_1[1] = L34_1
