L27_1 = "SI_PF_TUTORIAL_TEXUTRE_SHIP_INFO_1_DESC"
L28_1 = "Mỗi tiểu đội có thể vận hành một chiếc tàu.\nNếu <COLOR=#FFBC00>tàu của bạn bị phá hủy</COLOR>, bạn sẽ <COLOR=#FFBC00>thua</COLOR> trận chiến."
L26_1[1] = L27_1
L26_1[2] = L28_1
L27_1 = {}
L28_1 = "SI_SKIN_DESC_NKM_UNIT_C_STREGA_EVELYN_CAFFE"
L29_1 = "Chỉ cần một thay đổi nhỏ thôi cũng có thể khiến cùng một không gian như vậy trở nên đặc biệt. \nVí dụ như chủ quán cà phê mà bạn đến hàng ngày đã thay đồng phục của mình. \nKhách thậm chí quan tâm đến trang phục của cô ấy hơn là món tráng miệng. \nCó thêm loại tình dược nào vào đồ uống không vậy? \n\n<color=#ffd34c>Tôi không bao giờ cho gì vào đồ uống đâu♪ Bạn cứ băn khoăn sao mình cứ nhìn chằm chằm vào tôi sao? Hehehe, tôi chỉ là vừa thay quần áo thôi, ha ha ha♪</color>"
