L12_1[2] = L14_1
L13_1 = {}
L14_1 = "SI_UNIT_SKILL_DESC_HARMONY_C_TRUMPET_HYPER_LV1"
L15_1 = "Luna đắm chìm trong âm nhạc của mình và bắt đầu biểu diễn trong trạng thái xuất thần. Cấp 1 buff DMG RDC +20% cho tất cả đồng minh bao gồm cả bản thân khi chơi nhạc. Kẻ thù trong phạm vi nhận 4 lần sát thương Hitstun trước khi bị hất tung lên không trung, bị đẩy lùi và nhận sát thương."
L13_1[1] = L14_1
L13_1[2] = L15_1
