L15_1 = "SI_UNIT_SKILL_DESC_ESPR_S_DOCTOR_PASSIVE2_LV5"
L16_1 = "Thêm buff +10% HP cho các đơn vị Binh Lính/V.T.A.M đồng minh trên 80% HP trong 15 giây khi sử dụng Tấn công Cường hóa. (Tối đa 2 stack, loại trừ Triệu hồi)"
L14_1[1] = L15_1
L14_1[2] = L16_1
