L16_1 = "SI_UNIT_SKILL_DESC_ESPR_S_DOCTOR_PASSIVE2_LV1"
L17_1 = "Bắn một đòn tấn công cường hóa sau mỗi 2 Đòn Tấn Công Cơ Bản, tiêu tốn 10% HP Tối Đa để gây sát thương cho kẻ thù và hồi 10% HP cho tất cả các đơn vị đồng minh trong phạm vi tấn công cơ bản."
