L2_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_CARNIVAL_4_INTERLUDE_2"
L3_1 = "Cục Trưởng Tình báo nói thêm trong cuộc phỏng vấn. 「Nếu tôi phải chọn giữa lựa chọn tốt thứ hai và lựa chọn tệ thứ hai, tôi sẽ chọn lựa chọn tệ thứ hai. Chọn thứ gì đó tốt hơn thứ tệ nhất sẽ tốt hơn cho việc giảm thiểu rủi ro hơn là chọn thứ gì đó kém lý tưởng hơn.」"
L1_1[1] = L2_1
L1_1[2] = L3_1
L2_1 = {}
L3_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_CARNIVAL_5_1"
L4_1 = "Tanaberin, đắm mình trong Hiệu Ứng Ăn Mòn, không trải qua hoàng hôn cũng như bình minh. Bầu trời bị tẩy trắng cả ngày lẫn đêm có thể giống như một hiện tượng thiên nhiên bất thường đối với những người từ các vùng khác."
L2_1[1] = L3_1
L2_1[2] = L4_1
L3_1 = {}
L4_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_CARNIVAL_4_INTERLUDE_3"
L5_1 = "Một hiện tượng do các Tia Ăn Mòn gây ra được gọi là Hiệu Ứng Ăn Mòn. Nhưng đây là từ quan điểm của thế giới hiện tại. Nhìn từ phía Counterside, đây là một điều vốn có và tự nhiên đối với thế giới."
L3_1[1] = L4_1
L3_1[2] = L5_1
L4_1 = {}
L5_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_CARNIVAL_6_INTERLUDE_2"
L6_1 = "Revenant. Leah Schneider.\nVà."
L4_1[1] = L5_1
L4_1[2] = L6_1
L5_1 = {}
L6_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_CARNIVAL_4_2"
L7_1 = "Theo một cuộc khảo sát gần đây được thực hiện bởi ngành công nghiệp TASKFORCE với câu hỏi: 「Điều tai hại nhất gây ra từ Sự cố Người thay thế là gì?」, Nhiều người đã trả lời bằng cách nói 「Hybrider」. Việc tiến bộ là cần thiết, nhưng liệu ngành công nghiệp của chúng ta có thể trung thực nếu chúng ta nhắm mắt làm ngơ trước việc sử dụng nó một cách bừa bãi?"
L5_1[1] = L6_1
L5_1[2] = L7_1
L6_1 = {}
L7_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_CARNIVAL_1_INTERLUDE_1"
L8_1 = "Cục An Ninh Quốc Gia Gronia là một cơ quan tình báo xử lý việc thu thập thông tin tình báo quốc gia và quốc tế và có thẩm quyền điều tra để làm việc đó. Cục đã từng tự xác lập là cơ quan có thẩm quyền lớn nhất đất nước bằng cách sử dụng sức mạnh to lớn của mình.\nCác hoạt động của nó đã phải dừng lại khi đất nước phải cải tổ chính phủ khi chiến tranh lạnh nổ ra, nhưng tai tiếng của nó vẫn còn nguyên trong tâm trí người dân Gronia."
