L30_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_CARNIVAL_5_INTERLUDE_4"
L31_1 = "Ngay cả một kẻ mù quáng cũng có thể tìm thấy con đường của cô ấy đến với đức tin đúng đắn. Làm thế nào mà hội có thể bày tỏ lòng thương xót đối với những kẻ phỉ báng? Sự thương xót duy nhất mà họ sẽ được ban cho là sự kết thúc nhanh chóng bởi những lưỡi dao của đao phủ."
L29_1[1] = L30_1
L29_1[2] = L31_1
L30_1 = {}
L31_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_CARNIVAL_1_2"
L32_1 = "Ai cũng biết rằng phiến quân ở Gronian ban đầu là các nhóm chống chính phủ bạo lực. Họ đã gây ra bạo lực trong hệ quả hỗn loạn của Sai Sót Quản Trị, và củng cố quyền lực khi hệ thống lãnh đạo của chính phủ bị xáo trộn trong thảm họa ăn mòn."
