L41_1 = "Một cảnh quan chung khắp Gronia. \nCó thể được sử dụng làm nền Tiền sảnh."
L39_1[1] = L40_1
L39_1[2] = L41_1
L40_1 = {}
L41_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_CARNIVAL_2_INTERLUDE_3"
L42_1 = "Ở Gronia, những người duy nhất chào đón chuyến thăm từ Cục An Ninh Quốc Gia là những người cung cấp thông tin."
L40_1[1] = L41_1
L40_1[2] = L42_1
L41_1 = {}
L42_1 = "SI_DESC_UNIT_GET_21045"
L43_1 = "Sự phục hồi chân thực của một con tàu mà được thiết kế bởi thế giới của Elysium Philharmonic. Nó tạo ra môi trường tối ưu cho buổi biểu diễn bằng cách sử dụng công nghệ điều khiển sóng độc đáo."
L41_1[1] = L42_1
L41_1[2] = L43_1
L42_1 = {}
L43_1 = "SI_UNIT_SKILL_DESC_HARMONY_C_BASS_ATTACK_LV1"
L44_1 = "Carmen chơi nhạc cụ của mình để gây sát thương cho một mục tiêu ở phía trước."
L42_1[1] = L43_1
L42_1[2] = L44_1
