L29_1 = {}
L30_1 = "SI_DESC_UNIT_LIMITBREAK_117823"
L31_1 = "Tôi rất mạnh. Chủ tịch hội học sinh này không biết gì cả."
L29_1[1] = L30_1
L29_1[2] = L31_1
L30_1 = {}
L31_1 = "SI_DESC_UNIT_LIMITBREAK_111723"
L32_1 = "Này, điều này thật tuyệt. Tôi cảm thấy mình đang trở nên mạnh hơn. Nếu thế, tôi sẽ nhanh chóng trở thành số một!"
L30_1[1] = L31_1
L30_1[2] = L32_1
L31_1 = {}
L32_1 = "SI_DESC_UNIT_LIMITBREAK_111223"
L33_1 = "Ngay cả những cơn gió thay đổi nhỏ nhất cũng có thể làm thay đổi mọi thứ. Vì thế, tôi sẽ không dựa vào những cơn gió vô thường như thế, tôi phải dựa vào khả năng của chính mình."
L31_1[1] = L32_1
L31_1[2] = L33_1
L32_1 = {}
L33_1 = "SI_DESC_UNIT_LIMITBREAK_107123"
L34_1 = "Đối xử tốt như vậy lại làm tôi nghĩ ngợi. Nhiều đến mức không thể ngủ nổi đấy."
L32_1[1] = L33_1
L32_1[2] = L34_1
L33_1 = {}
L34_1 = "SI_DESC_UNIT_GET_117823"
L35_1 = "Ngài đang nghi ngại điều gì? Ơ? Trang phục của tôi làm sao cơ? Tôi là chủ tịch hội học sinh của học viện. Chủ tịch hội học sinh mặc đồ như thế này là bình thường mà."
L33_1[1] = L34_1
L33_1[2] = L35_1
