L36_1 = "SI_DESC_UNIT_GET_111223"
L37_1 = "Không nghe thấy tiếng gió sẽ không có nghĩa là ngài sẽ bị lạc lối. Hôm nay, những lời thì thầm của người hầu đã dẫn tôi đến với ngài yêu dấu của tôi."
L35_1[1] = L36_1
L35_1[2] = L37_1
L36_1 = {}
L37_1 = "SI_DESC_UNIT_GET_107123"
L38_1 = "Cuối cùng cũng được gặp ngài như thế này. Thật là vinh dự, Quản Trị Viên. Tôi cảm giác giác như mình là nhân vật phản diện ở đây vậy, nhưng chà. Tôi hy vọng được làm việc với ngài."
L36_1[1] = L37_1
L36_1[2] = L38_1
L37_1 = {}
L38_1 = "SI_DESC_NEGO_SUCCESS_117823"
L39_1 = "Thế này là chưa đủ để làm tôi hài lòng, nhưng tôi đoán tôi sẽ chấp nhận nó như một dấu hiệu của sự tôn trọng."
