L7_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_HORIZON_M_LOAN"
L8_1 = "Horizon là một lính phòng vệ không biết sợ hãi bảo vệ bản thân bằng các hiệu ứng rào chắn và miễn nhiễm dai dẳng trong khi đánh bật kẻ thù của mình một cách không thương tiếc.\n\nCô ấy là người thu nợ của Horizon Finance khét tiếng tàn ác. Tuy nhiên, bất chấp lãi suất cao và tai tiếng, công ty của cô luôn gặp khó khăn đen đủi. Phần lớn lợi nhuận cuối cùng sẽ được trả cho những thiệt hại về tài sản thế chấp gây ra trong quá trình thu tiền. Điều đó càng trở nên trầm trọng hơn bởi thực tế là nhiều con nợ của cô ấy từ chối trả tiền cho đến khi cô gái nhỏ mà họ chế giễu có hành động trực tiếp hơn.\n\nMọi người xung quanh có thể nói Horizon không phù hợp với công việc, nhưng cô ấy có vẻ không cảm thấy cần phải cải thiện bất kỳ điều gì. Nếu có bất cứ điều gì, cô ấy dường như càng quan tâm hơn đến việc quan sát những người cô ấy gặp trong quá trình thu nợ của mình, hơn là việc thu nợ.\n\nCác nạn nhân của cô ấy khẳng định Horizon chỉ thích thể hiện sức mạnh của mình và xem phản ứng của người khác, nhưng vẫn phải xem liệu cô ấy có động cơ gì thầm kín hay không."
L6_1[1] = L7_1
L6_1[2] = L8_1
L7_1 = {}
L8_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_HORIZON_1_INTERLUDE_2"
L9_1 = "Dựa trên điều tra của tôi, có vẻ như cô ấy chủ yếu tham gia vào việc phô trương lực lượng bằng các hệ thống bọc thép cho đến khi cô ấy thuê thêm nhân viên. Có rất nhiều quân trang bị bỏ rơi để nhặt sau cuộc chiến ở thế giới thứ ba nơi cô ấy đã hoạt động. Cô ấy đã tạo ra rất nhiều kẻ thù đang cố gắng đòi nợ từ các lãnh chúa nắm quyền kiểm soát khu vực."
L7_1[1] = L8_1
L7_1[2] = L9_1
L8_1 = {}
L9_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_HORIZON_2_4"
L10_1 = "Những con nợ phải giao dịch với Horizon trước khi cô thuê thêm nhân viên dường như đang chịu chứng PTSD cực kỳ nguy hiểm. Một cá nhân mà tự nhận là quan chức cho một lãnh chúa nào đó, đã làm chứng là anh ta đã phải nhập viện gần một năm sau khi Horizon thu nợ. Ông ta ấy tin rằng Horizon vẫn còn theo dõi."
L8_1[1] = L9_1
L8_1[2] = L10_1
L9_1 = {}
L10_1 = "SI_SKIN_DESC_NKM_UNIT_HORIZON_C_SCYTHE_BUNNY"
L11_1 = "Một bé thỏ nhảy nhót trong sòng bạc, nơi mà mọi cảm xúc thế tục cùng tồn tại trong một mớ bòng bong. Tai cô liên tục vẫy vẫy khi nghe khách hàng gọi tên mình.\nCô ấy phụ trách nhận đơn đồ uống, đổi chip và an ủi những vị khách đang khóc.\n\n<color=#ffd34c>Nhảy nhảy! ...Xin lỗi cho tôi hỏi? Đó không phải là kiểu thỏ bông khóc ư? Không sao. Miễn là tôi làm cho khách hàng của tôi mỉm cười là được!</color>"
L9_1[1] = L10_1
L9_1[2] = L11_1
L10_1 = {}
L11_1 = "SI_SKIN_DESC_NKM_UNIT_HORIZON_C_STAND_BUNNY"
L12_1 = "Một sòng bạc mở giữa đêm. \nCô ngồi một mình ở bàn trong góc quán bar để trốn thoát khỏi tiếng nhạc chát chúa. Cô ấy cứ loay hoay với quần áo và kéo đôi tai thỏ của mình xuống như để giấu chúng đi. \nMình đã mặc cái này cho cô ấy .. \n\n<color=#ffd34c>Nếu muốn xem, hãy mua đồ uống cho tôi trước. Thật khó để xóa bỏ những ánh mắt như thế trong tâm trí tôi.</color>"
L10_1[1] = L11_1
L10_1[2] = L12_1
L11_1 = {}
L12_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_HORIZON_1_INTERLUDE_1"
L13_1 = "Đó không phải là kẻ cho vay nặng lãi thực sự. Tôi không bị lừa đâu. Không ai đủ ngu ngốc để cho vay với lãi suất thấp như vậy mà mong kiếm sống được. Tôi chắc rằng họ đang âm mưu điều gì đó khác đằng sau."
L11_1[1] = L12_1
L11_1[2] = L13_1
L12_1 = {}
L13_1 = "SI_UNIT_SKILL_DESC_C_JAPAN_CHIHIRO_PASSIVE_LV5"
L14_1 = "DMG RES Giáp Lá Cà +30%"
L12_1[1] = L13_1
L12_1[2] = L14_1
