L14_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_HORIZON_2_INTERLUDE_2"
L15_1 = "Trên nền màu xám tro của những con đường bê tông bẩn thỉu, cô gái mang đến những màu sắc mới. Sự bùng nổ màu sắc này đã truyền cảm hứng cho cộng đồng, mặc dù ban đầu chỉ là một chút. Nhưng đó là cách thế giới có thể thay đổi. Từng bước một."
L13_1[1] = L14_1
L13_1[2] = L15_1
L14_1 = {}
L15_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_HORIZON_3_INTERLUDE_2"
L16_1 = "Không có thông tin nào cho biết tôi tìm được con nợ khi nào hay ở đâu cả. Tôi không thể trì hoãn một giây phút nào nữa. Sửa chữa là thứ xa xỉ mà tôi không thể trả nổi ngay bây giờ."
L14_1[1] = L15_1
L14_1[2] = L16_1
L15_1 = {}
L16_1 = "SI_SKIN_DESC_NKM_UNIT_HORIZON_M_LOAN_BUNNY"
L17_1 = "Sự căng thẳng dâng cao trong sòng bạc. \nMột cô gái thỏ liên tục khiến khách hàng chi tiền của họ một cách thoải mái.\nSự mưu mẹo và những lời chế nhạo lạnh lùng của cô ấy thậm chí còn thu hút những người ngoài cuộc và khiến họ bị lôi kéo cho đến khi hoàn toàn bị cháy túi. \nKhách hàng đến gần bàn của cô như thể bị nụ cười đầy kiêu hãnh của cô mê hoặc vậy. \n\n<color=#ffd34c>Tốt hơn hết là nếu không muốn trở thành vật dự phòng, hãy cố gắng hết sức vào, con người.</color>"
L15_1[1] = L16_1
L15_1[2] = L17_1
