L18_1 = "DMG Giáp Lá Cà"
L16_1[1] = L17_1
L16_1[2] = L18_1
L17_1 = {}
L18_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_HORIZON_2_3"
L19_1 = "Cô hỏi tại sao mọi người đều lặng thinh ư?\nNghe này, thưa quý cô. Đối với những kẻ như chúng tôi, súng quan trọng hơn luật pháp và trật tự. Chúng tôi đủ hạnh phúc miễn là có thể sống thêm một ngày nữa. Nhưng khi điều đó đến với chúng tôi… Hãy cứ nói rằng tôi ước gì mình đã chết.\nNày, đừng nói với ai rằng tôi đã nói với cô điều này."
L17_1[1] = L18_1
L17_1[2] = L19_1
