L37_1 = "SI_UNIT_SKILL_DESC_KNIGHT_C_FLAG_ATTACK_LV1"
L38_1 = "Cô vung thanh kiếm Nhà Tù Sapphire của gia tộc, gây sát thương cho kẻ thù."
