L38_1[2] = L40_1
L39_1 = {}
L40_1 = "SI_SKIN_DESC_NKM_UNIT_CA_ADMIN_LEE_SUYEON_RECITAL"
L41_1 = "Giống như những con át chủ bài xoa dịu sự bất hòa trên chiến trường, chúng tôi hát về trật tự và niềm đam mê trong thế giới đầy hỗn loạn này. Chúng tôi muốn dành tặng bài hát này cho ngài. Ngài đã sẵn sàng chưa ạ?\n\n<color=#ffd34c>Xin hãy ngồi xuống. Chúng tôi xin dành tặng ngài buổi diễn hay nhất từng có.</color>"
L39_1[1] = L40_1
L39_1[2] = L41_1
L40_1 = {}
L41_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_DELTA_C_QUEEN"
L42_1 = "Jaina Kropel là một lính bắn tỉa ngoan cường có năng lực tự chữa thương; cô chỉ có thể sạc chỉ số kỹ năng của mình thông qua các đòn tấn công cơ bản.\n\nJaina từng bị giam trong một nhà tù tối cao, sự tồn tại của cô ấy được xếp vào loại tối mật.\n\nVì đã mất tất cả ký ức, Quân Hậu Nhân Bản - bản thể trước đây của cô ấy - chỉ là một người xa lạ với cô. Bất cứ khi nào ký ức cũ xuất hiện từ những kích thích bên ngoài, cô ấy sẽ hoảng loạn và cố gắng khước từ chúng. Nhưng vẫn còn phải xem liệu thế giới có hiểu được tình trạng hiện tại của cô ấy hay không.\n\nMột vài người thực sự coi những ký ức bị ẩn giấu đó như một vũ khí tiềm ẩn nhiều nguy cơ nhưng lại hữu dụng."
L40_1[1] = L41_1
L40_1[2] = L42_1
L41_1 = {}
L42_1 = "SI_EPISODE_DUNGEON_NAME_NKM_DUNGEON_EVENT_INTERLUDE"
L43_1 = "Phần Chuyển Tiếp #{0}"
L41_1[1] = L42_1
L41_1[2] = L43_1
L42_1 = {}
L43_1 = "SI_SKIN_DESC_NKM_UNIT_C_ALT_YOO_JIN_RECITAL"
L44_1 = "Cô ấy đến từ thế giới nơi mọi người giành nhau miếng cơm manh áo để tồn tại.\nCô ấy thô bạo về mọi mặt, kể cả bàn tay chơi nhạc của mình.\nVậy, tôi đã dạy cô ấy điều gì đây?\nKhông nhiều. Âm nhạc nói lên bạn là ai, phải không?\n\n<color=#ffd34c>Ngài muốn tôi trông nghiêm túc hơn. Chà... Nếu đó là điều ngài muốn, Sếp ạ, tôi sẽ cố gắng.</color>"
L42_1[1] = L43_1
L42_1[2] = L44_1
L43_1 = {}
