L43_1[2] = L45_1
L44_1 = {}
L45_1 = "SI_SKIN_DESC_NKM_UNIT_ALT_CA_SEO_YOON_RECITAL"
L46_1 = "Chúng tôi đã bò từ dưới đáy rồi vươn tới đỉnh cao. Chúng tôi tự mình luyện tập trong một thế giới không có một khán giả nào. Nhưng bây giờ, chúng tôi được vây quanh bởi sự hòa hợp, bởi mọi người. Đã đến lúc đạt đến sự thăng hoa rồi.\n\n<color=#ffd34c>Tôi hy vọng ngài sẽ vui vẻ khi ở bên chúng tôi. Hôm nay, chúng tôi sẽ chơi nhạc cho ngài, Sếp ạ.</color>"
