L14_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_CHALLENGE_JAPAN_1_3"
L15_1 = "Các phong ấn không thể tồn tại mãi mãi. Đó là lý do tại sao Liên minh vẫn tiếp tục truyền thống của mình và luôn gắn liền với phong ấn, bất chấp nền hòa bình đã kéo dài hơn tuổi thọ của con người.\n\n<color=#ffd34c> ※ Chinatsu, người liên tục chữa trị cho các đồng minh, được bảo vệ bởi một chiến binh hộ tống.</color>"
L13_1[1] = L14_1
L13_1[2] = L15_1
L14_1 = {}
L15_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_CHALLENGE_JAPAN_1_2"
L16_1 = "Bát phong ấn giữ một ngọn núi tách biệt với thế giới thực. Ngọn núi này là nơi tọa lạc của dinh thự cũ của dòng tộc Nanahara. \n\n<color=#ffd34c> ※ Chifuyu rất ghê gớm. Đừng để cô ấy phối hợp với những kẻ thù khác.</color> "
L14_1[1] = L15_1
L14_1[2] = L16_1
L15_1 = {}
L16_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_CHALLENGE_JAPAN_1_1"
L17_1 = "Giám sát phong ấn là một nhiệm vụ quan trọng của Liên Minh Gia Tộc Nanahara. Nếu mối đe dọa trở thành sự thật, sẽ không có cách nào vãn hồi."
L15_1[1] = L16_1
L15_1[2] = L17_1
L16_1 = {}
L17_1 = "SI_EPISODE_DUNGEON_DESC_NKM_DUNGEON_CHALLENGE_JAPAN_1_3"
L18_1 = "Phong ấn không thể kéo dài mãi mãi. Đó là lý do vì sao Liên Minh luôn canh gác nó, bất chấp sự hòa bình đã kéo dài mấy thế hệ."
L16_1[1] = L17_1
