L35_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_SHADE_4_INTERLUDE_2"
L36_1 = "Sự hối hận khiến địa ngục chồng chéo với thực tại, và cảm giác tội lỗi khiến thực tại chẳng khác gì địa ngục.\nNhững người không biết hối hận hay tội lỗi lại biến thực tại thành địa ngục."
L34_1[1] = L35_1
L34_1[2] = L36_1
L35_1 = {}
L36_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_SHADE_4_3"
L37_1 = "Vị vua lười biếng không kiểm tra hay hủy bỏ mệnh lệnh của mình.\nNhững hầu cận trung thành của ông ấy thực hiện các mệnh lệnh ngay cả khi họ biết là vô nghĩa.\nĐây là cách cai trị của một triều đại tai họa."
