L46_1 = "SI_BOSS_DESC_05"
L47_1 = "V.T.A.M. Hạng 3 xuất hiện ở mọi độ sâu.\n\nKhông giống như loại Quái Vật, vốn bị bản năng chi phối, nó có khả năng phán đoán chờ đợi cơ hội, do đó gây ra mối đe dọa lớn hơn.\n\nPhong cách chiến đấu của nó thay đổi rất nhiều tùy thuộc vào vũ khí trang bị xung quanh cơ thể chính của nó.\n\n<color=#FFCF3B>※Tấn công bằng các đơn vị có kỹ năng nhiều đòn đánh\nđể làm rối đoạn các kiểu tấn công của Áo Giáp Bạo Chúa.</color> "
L45_1[1] = L46_1
L45_1[2] = L47_1
L46_1 = {}
L47_1 = "SI_BOSS_DESC_06"
L48_1 = "V.T.A.M. Hạng 3 xuất hiện ở mọi độ sâu.\n\nKhông giống như loại Quái Vật, vốn bị bản năng chi phối, nó có khả năng phán đoán chờ đợi cơ hội, do đó gây ra mối đe dọa lớn hơn.\nPhong cách chiến đấu của nó thay đổi rất nhiều tùy thuộc vào vũ khí trang bị xung quanh cơ thể chính của nó.\n\n<color=#FFCF3B>※Giảm thiểu sát thương bằng cách giảm thiểu số lượng đơn vị trong phạm vi hoạt động của Thanh Kiếm Bạo Chúa.</color> "
L46_1[1] = L47_1
L46_1[2] = L48_1
L47_1 = {}
L48_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_SHADE_3_INTERLUDE_1"
L49_1 = "Có một kẻ lang thang khiến tất cả mọi người đều phẫn nộ.\nMặc dù anh ta khao khát được nghỉ ngơi, anh ta không thể tự mình làm được điều đó."
L47_1[1] = L48_1
L47_1[2] = L49_1
L48_1 = {}
L49_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_SHADE_4_4"
L50_1 = "Một nhân cách đã được mài giũa trong một thời gian dài nghiền ngẫm bản ngã đã bị nghiền nát của cô ấy.\nNgay khi cô ấy tự nguyện chấp nhận nó, nó sẽ trở thành thuốc độc và tàn phá toàn bộ con người cô ấy.\nLuôn luôn là như vậy, khi tạo ra một \"em gái\" mới."
L48_1[1] = L49_1
L48_1[2] = L50_1
L49_1 = {}
L50_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_SHADE_3_2"
L51_1 = "Hội Chứng Ăn Mòn trở nên cấp tính khi ở những tầng siêu sâu của Counterside."
L49_1[1] = L50_1
L49_1[2] = L51_1
L50_1 = {}
L51_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_SHADE_3_INTERLUDE_2"
L52_1 = "Bộ giáp sáng chói của anh ta bị gỉ sét và vũ khí của anh ta trở thành gánh nặng. \nNgay cả khi đó, kẻ lang thang vẫn không thể dừng lại. \nĐó là một hình phạt cho chính bản thân anh ta. "
L50_1[1] = L51_1
L50_1[2] = L52_1
