L12_1 = "SI_PF_TUTORIAL_TEXUTRE_RAID_HELP_2_DESC_02"
L13_1 = "<COLOR=#FFBC00> Bật Hỗ Trợ Bố Ráp</COLOR> để <COLOR=#FFBC00>nhận trợ giúp từ những người dùng khác</COLOR> trong Bố Ráp hoặc giúp họ thực hiện Bố Ráp.\n\n Tiêu diệt Boss và <COLOR=#FFBC00>người đã tham gia Bố Ráp cũng như người đầu tiên khám phá ra Boss sẽ được nhận thưởng</COLOR>."
L11_1[1] = L12_1
L11_1[2] = L13_1
