L13_1 = "SI_PF_CONTRACT_COUNT_CLOSE_TOOLTIP_DESC"
L14_1 = "◇ Mỗi khi tuyển dụng 1 lần sẽ mất 1 lượt Tuyển Dụng. \n◇ Tuyển dụng x10 mất 10 lượt. \n◇ Dùng hết số lượt tuyển dụng còn lại sẽ kết thúc tuyển dụng lần này."
L12_1[1] = L13_1
L12_1[2] = L14_1
L13_1 = {}
L14_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_SHADE_2_INTERLUDE_3"
L15_1 = "Nhiều nơi trên cơ thể bệnh nhân đã biến thành các hình thù sắc nhọn khác nhau. Nhờ khuôn miệng còn nguyên vẹn, anh ấy đã la hét cho đến khi chết và hoàn thành nguyện ước được gặp người vợ quá cố của mình. Ngày đó, tôi cảm thấy mình như một bác sĩ lần đầu tiên đối mặt với bệnh dịch.\n- Từ nhật ký của một bác sĩ phẫu thuật trong quân đội"
L13_1[1] = L14_1
L13_1[2] = L15_1
