L15_1 = "SI_UNIT_TITLE_HORIZON"
L16_1 = "Quỹ Đầu Tư Có Thời Hạn"
L14_1[1] = L15_1
L14_1[2] = L16_1
L15_1 = {}
L16_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_SHADE_2_2_HM"
L17_1 = "Phải có ai đó nói chuyển với họ,\nthuyết phục họ.\nNhưng để vượt qua sự ám ảnh mù quáng của họ, anh ta cũng phải nhìn từ góc độ của họ.\nKhông ai làm được điều đó trong suốt thời gian vừa qua."
L15_1[1] = L16_1
L15_1[2] = L17_1
L16_1 = {}
L17_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_SHADE_2_INTERLUDE_4"
L18_1 = "tôi tìm thấy một quán bar ưa thích. Tôi không nhớ tên hay địa điểm của nó. Tôi đã tới đó hàng ngày để uống và chờ một người không bao giờ đến."
L16_1[1] = L17_1
L16_1[2] = L18_1
L17_1 = {}
L18_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_HORIZON_C_STAND"
L19_1 = "Rita Arsenico là một Lính Hỗ Trợ ra lệnh cho Omertà - đệ tử ruột của mình - đẩy lùi kẻ địch. Khả năng kiểm soát kim loại của cô ấy đặc biệt có khả năng khắc chế Lính Thiết Giáp. \n\nTuy không thừa nhận, nhưng cô ấy là người góp phần tạo nên ác danh của Horizon Finance trong ấn tượng của khách hàng, những người không thể không hợp tác khi đối mặt trước ánh mắt khắc nghiệt và giọng nói đáng sợ của cô ấy. Theo lời kể của một nhân viên pha chế tại quán bar yêu thích của Rita, khách hàng của Rita bao gồm từ những tên tội phạm ghê tởm cho đến luật sư, sự hỗn tạp này có lẽ là sẽ khiến nhiều người cho rằng cô đã từng có một quá khứ thú vị."
L17_1[1] = L18_1
L17_1[2] = L19_1
L18_1 = {}
