L46_1 = "SI_PF_TUTORIAL_TEXUTRE_UNIT_LIMITBREAK_3_DESC"
L47_1 = "Nhân viên có thể được <COLOR=#FFBC00>Hợp Nhất Giới Hạn</COLOR> bằng Lõi Hợp Nhất hoặc đơn vị cùng loại.\n<COLOR=#FFBC00>Hợp Nhất Giới Hạn</COLOR>gia tăng <COLOR=#FFBC00>Cấp Độ Tối Đa thêm 2 cấp </COLOR>và <COLOR=#FFBC00>tốc độ tăng trưởng thông số thêm 2%</COLOR>mỗi khi được thực hiện.\n<COLOR=#FFBC00>Hợp Nhất Giới Hạn</COLOR>có thể được thực hiện <COLOR=#FFBC00>tối đa 5 lần</COLOR>."
L45_1[1] = L46_1
L45_1[2] = L47_1
L46_1 = {}
L47_1 = "SI_PF_TUTORIAL_TEXUTRE_RAID_HELP_3_DESC"
L48_1 = "<COLOR=#FFBC00>Nhận được số điểm Bố Ráp nhất định</COLOR> trong một mùa,\nvà có thể tham gia cùng các Bố Ráp của người dùng khác <COLOR=#FFBC00>mà không cần trả phí vào trận</COLOR>.\nTuy nhiên, ngài <COLOR=#FFBC00>không thể nhận thưởng</COLOR> hay thay đổi loại cổng vào của mình sau khi chọn nó."
L46_1[1] = L47_1
L46_1[2] = L48_1
