L17_1 = "SI_SKIN_DESC_NKM_UNIT_C_FALLEN_ROSARIA_SUMMER"
L18_1 = "Cảm xúc của con người luôn là chất liệu thú vị, đặc biệt ở những khu nghỉ dưỡng mùa hè như chỗ này lại càng nhiều thứ đáng để xem.\nTa thấy có một tam giác tình yêu đang đi ngang qua...\nÀ ừm, Chúa Quỷ đang nhìn gì vậy?\n\n<color=#ffd34c>Ta có thể một mình ăn hết chỗ đá bào này. Muốn đến thử miếng không?</color>"
L16_1[1] = L17_1
