L27_1 = "SI_PF_REARM_RECORD_READY_DESC"
L28_1 = "Truyền dữ liệu và nhận [Dữ Liệu Tái Vũ Trang và Dữ Liệu Đơn Vị].\n[Dữ Liệu Tái Vũ Trang] được sử dụng cho [Tái Vũ Trang].\n\nNhững nhân viên mà bạn đã tuyển dụng tạo\nthêm [Dữ Liệu Tái Vũ Trang] khi dữ liệu của họ được truyền gửi."
L26_1[1] = L27_1
L26_1[2] = L28_1
L27_1 = {}
L28_1 = "SI_DP_GAUNTLET_ASYNC_SEASON_LEAUGE_DESC"
L29_1 = "Các mùa giải Trận Chiến Chiến Lược sẽ kết thúc định kỳ.\nMỗi mùa giải sẽ kết thúc vào ngày cuối cùng lúc 10:00 giờ tối.\nMùa giải mới sẽ bắt đầu vào ngày đầu tiên của mùa giải lúc 4:00 giờ sáng.\nBạn sẽ nhận được phần thưởng căn cứ vào kết quả chung cuộc ở mùa giải trước.\nĐiểm Chiến Thắng của bạn có thể sẽ thay đổi vào cuối mỗi mùa giải, tùy theo chính sách vận hành mùa giải.\nGiải đấu của bạn có thể sẽ thay đổi sau mỗi mùa tùy theo Điểm Chiến Thắng."
L27_1[1] = L28_1
L27_1[2] = L29_1
L28_1 = {}
L29_1 = "SI_PF_REARM_REARM_CONFIRM_POPUP_FINAL_BOX_DESC"
L30_1 = "<size=36>Tái Vũ Trang {0}.</size>\n※ Nhân viên mục tiêu này sẽ biến mất khi được tái vũ trang."
