L30_1 = "SI_PF_OPERATOR_CONFIRM_POPUP_CONFIRM_WARNING_ACTIVE_SKILL_LEVEL"
L31_1 = "<color=#FFCF3B>Cấp độ kỹ năng Chỉ Huy của Người Điều Hành làm nguyên liệu</color> khá cao.\nSau khi truyền thụ kỹ năng Phụ, <color=#FFCF3B>cấp độ kỹ năng Phụ của người điều hành mục tiêu sẽ chỉ đặt lại về 1; nếu là người điều hành cùng loại, cấp độ kỹ năng chỉ huy sẽ chỉ tăng thêm 1 cấp.</color>. \nXác nhận vẫn hợp nhất?"
L29_1[1] = L30_1
