L18_1[2] = L20_1
L19_1 = {}
L20_1 = "SI_UNIT_SKILL_DESC_C_ALT_XIAOLIN_RA_PASSIVE_LV1"
L21_1 = "Điều khiển dòng điện sinh học của cô ấy để cải thiện độ chính xác. Tăng sát thương đòn tấn công cơ bản lên đến 20%, tuỳ thuộc vào khoảng cách giữa cô ấy và mục tiêu."
L19_1[1] = L20_1
L19_1[2] = L21_1
L20_1 = {}
L21_1 = "SI_UNIT_SKILL_DESC_C_ALT_XIAOLIN_RA_LEADER_LV1"
L22_1 = "Các máy bay không người lái giúp người chỉ huy của chúng tải vũ khí của cô ấy. Tăng 15% ASPD trong 9 giây khi triển khai."
L20_1[1] = L21_1
L20_1[2] = L22_1
L21_1 = {}
L22_1 = "SI_UNIT_SKILL_DESC_C_ALT_XIAOLIN_RA_HYPER_LV1"
L23_1 = "Bắn một viên đạn chứa sức mạnh đặc biệt, gây sát thương AoE. Viên đạn này gây ra một vụ nổ phía sau, đẩy lùi kẻ địch."
