L25_1 = "SI_UNIT_DESC_C_YOO_MI_NA_RA"
L26_1 = "Đơn vị tấn công Tầm Xa mạnh mẽ có kỹ năng diện rộng"
L24_1[1] = L25_1
L24_1[2] = L26_1
L25_1 = {}
L26_1 = "SI_UNIT_DESC_C_CIVIL_IRIE_RA"
L27_1 = "Chế nhạo và sử dụng kỹ năng áp chế diện rộng lên tiền tuyến, bảo vệ đồng minh."
L25_1[1] = L26_1
L25_1[2] = L27_1
L26_1 = {}
L27_1 = "SI_UNIT_DESC_C_ALT_XIAOLIN_RB"
L28_1 = "Lính hỗ trợ tấn công gây ra các đòn tấn công AoE cho một khu vực rộng lớn từ một vị trí cố định"
L26_1[1] = L27_1
L26_1[2] = L28_1
L27_1 = {}
L28_1 = "SI_UNIT_DESC_C_ALT_XIAOLIN_RA"
L29_1 = "Yểm trợ mạnh mẽ từ phía sau và có độ chính xác cao."
L27_1[1] = L28_1
L27_1[2] = L29_1
L28_1 = {}
L29_1 = "SI_SKIN_TITLE_NKM_UNIT_C_YOO_MI_NA_RA_OLD"
L30_1 = "Chất Xúc Tác"
L28_1[1] = L29_1
L28_1[2] = L30_1
L29_1 = {}
L30_1 = "SI_SKIN_DESC_NKM_UNIT_C_YOO_MI_NA_RA_OLD"
L31_1 = "Thời gian không phải là thứ duy nhất mà người ta cần để trưởng thành. Động lực và sự tự nhận thức cũng vậy. Đôi khi tính cách của con người thay đổi khi họ lớn lên. Trong trường hợp này, như thế là tốt hơn. <color=#ffd34c>Ha ha, tôi đoán bây giờ tôi là dân chuyên nghiệp rồi.</color>"
L29_1[1] = L30_1
L29_1[2] = L31_1
L30_1 = {}
L31_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_CIVIL_IRIE_RA"
L32_1 = "Irie đang tìm kiếm vật liệu chơi khăm mới khi cô ấy nảy ra một ý tưởng tuyệt vời. Cô ấy đã điều chỉnh CRF của mình thành hình cầu, thứ khiến cơ thể nhẹ và linh hoạt như một quả bóng cao su, và nó biến thành một chiếc khiên tuyệt vời. Lá chắn có độ đàn hồi cao này có thể được nảy bật vào kẻ thù đang lao tới và được kéo giãn rộng để bảo vệ đồng minh. Irie nóng lòng muốn chơi khăm bằng phát minh đặc biệt này."
L30_1[1] = L31_1
L30_1[2] = L32_1
L31_1 = {}
L32_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_ALT_XIAOLIN_RB"
L33_1 = "Các nhà nghiên cứu đã quyết định rằng Xiao Lin là người phù hợp để giúp họ lái thử Falcon Nest, một loại tàu sân bay không người lái đang trong giai đoạn xác minh kỹ thuật. Tàu sân bay không người lái này được thiết kế cho mục đích bảo vệ căn cứ bằng các máy bay không người lái nhỏ có khả năng nhanh chóng quét sạch kẻ thù ở phía sau. Các nhà nghiên cứu kỳ vọng Xiao Lin và Falcon Nest sẽ thể hiện màn trình diễn tuyệt vời khi chiến đấu cùng nhau."
L31_1[1] = L32_1
L31_1[2] = L33_1
L32_1 = {}
L33_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_ALT_XIAOLIN_RA"
L34_1 = "Xiao Lin đã cải thiện hơn nữa khả năng điều khiển điện sinh học của mình, khả năng mà trước đây cô đã sử dụng để bắn chính xác. 4 máy bay không người lái hỗ trợ của cô ấy, được cô ấy điều khiển thông qua dòng điện, bắn điện vào mục tiêu và loại bỏ ngay cả khả năng sống sót mỏng manh nhất. Người Gõ Cửa, sau khi được tăng cường bởi sự tương tác lẫn nhau giữa cô ấy và drone, nay đã tạo ra một phương pháp bao vây tốt để giải quyết tình trạng bế tắc trên chiến trường."
