L22_1 = "SI_SKIN_DESC_NKM_UNIT_S_SOF_JANE_CHILD"
L23_1 = "Theo bạn thì đâu là thứ quan trọng nhất trong công thức dược phẩm? Sàng lọc nguyên liệu? Kiểm tra an toàn? Chi phí sản xuất thấp?\nTheo tôi thì đó là hiệu quả, tuy nhiên, lúc đó thì thuốc đã được bào chế rồi. Và vị ngọt trái cây sẽ là điểm cộng!\n\n<color=#ffd34c>Tôi là một nhà khoa học thông minh và lại dễ thương nữa. Hãy đối xử với tôi thật cẩn thận nhé.</color>"
L21_1[1] = L22_1
L21_1[2] = L23_1
L22_1 = {}
L23_1 = "SI_SKIN_DESC_NKM_UNIT_C_POLICE_LEE_YUMI_CHILD"
L24_1 = "Bánh mỳ dài bọc đường. Bánh rán gạo tròn nhân đậu đỏ.\nBánh su kem mịn dày. Bánh rán Churro giòn tan.\nBánh quy pretzel phô mai kem ăn với sô cô la nóng.\nChúng ta đang sống trong thời dư thừa đồ ngọt.\n\n<color=#ffd34c>Bánh quy ăn ngon nhất khi được nhúng sữa. Sao lại thế nhỉ?</color>"
L22_1[1] = L23_1
L22_1[2] = L24_1
