L15_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_CLB001_2_EPILOGUE"
L16_1 = "Chương trình mô phỏng mới này rất hiệu quả, nhưng các nhà phát triển của nó đã quyết định rằng việc triển khai các nhân vật thực tế như vậy trong một không gian ảo có thể là quá mức tiên tiến so với thời điểm hiện tại."
L14_1[1] = L15_1
L14_1[2] = L16_1
L15_1 = {}
L16_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_CLB001_2_3_CM"
L17_1 = "Đây sẽ là một màn trình diễn ngoạn mục.\n<color=#ff2626> ※ Cửa ải này có thể sử dụng nhiều đơn vị. </color>\n <color=#ffd34c>\n\n ※ [I-NO]: Kỹ năng tối thượng của I-NO gây sát thương cận tử cho tất cả các đơn vị trên chiến trường, cả Mặt Đất và Trên Không.\nHiệu suất của cô trở nên tàn nhẫn hơn mỗi khi ai đó trong số khán giả ngất đi. Đừng để họ nghe cô ấy chơi quá lâu.</color>"
L15_1[1] = L16_1
L15_1[2] = L17_1
L16_1 = {}
L17_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_CLB001_2_3"
L18_1 = "Trên thế giới này không gì nhàm chán hơn một trận chung kết long trọng, đồng ý không?"
L16_1[1] = L17_1
L16_1[2] = L18_1
L17_1 = {}
L18_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_CLB001_2_1_CM"
L19_1 = "Một cửa ải dành cho những ai muốn chinh phục độ khó cao. Danh dự là phần thưởng duy nhất.\n<color=#ff2626> ※ Chỉ cửa ải này mới cho phép sử dụng nhiều đơn vị đến vậy.</color>\n<color=#ffd34c>※ Nếu bạn có 5 đơn vị trở lên trên chiến trường, kẻ thù của bạn sẽ coi đó là gian lận và ngay lập tức sử dụng kỹ năng Tối Thượng.\n\n※ [Millia Rage]: Tấn công và sử dụng Psych Burst, đẩy lùi kẻ thù xung quanh và tăng ATK và ASPD của bản thân.\n※ [Ramlethal Valentine]: Đòn đánh cuối cùng của Gatling Combo tạo ra một hiệu ứng và cộng dồn không thể hủy bỏ buff cho cô ấy. Các hiệu ứng tăng cường hoàn toàn bị hủy bỏ mỗi khi cô ấy bị đánh bại.</color>"
L17_1[1] = L18_1
L17_1[2] = L19_1
