L12_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_CIVIL_ZENA"
L13_1 = "Zena Bird là Tổng Tư Lệnh của Hỗ Trợ Chính Thức.\nCô ấy là một lính tiên phong mới nổi,\nngười bù đắp điểm yếu về chỉ số cơ bản bằng các kỹ năng.\nCô ấy là lớp phó khi gặp phải một thảm họa\ntrong chuyến đi tốt nghiệp.\nSau đó, cô đã kích hoạt Đồng hồ để bảo vệ bạn bè của mình.\nSau khi thoát khỏi khủng hoảng, cô ấy đã tham gia\nHỗ Trợ Chính Thức để giúp đỡ nhiều người hơn với\nsức mạnh mới của mình.\nLý do tại sao cô ấy trở thành Tổng Tư Lệnh, mặc dù với\ntư cách Counter và người lãnh đạo, cô ấy còn thiếu kinh nghiệm,\nlà vì không ai muốn nhận trách nhiệm này.\nZena đang cảm thấy áp lực với vị trí của mình,\nnhưng cô ấy không ngừng cố gắng để trở thành\nngười phù hợp với chức vụ của mình.\n"
L11_1[1] = L12_1
L11_1[2] = L13_1
L12_1 = {}
L13_1 = "SI_DP_NEGOTIATE_NO_EXIST_UNIT"
L14_1 = "Hiện không có đơn vị để đàm phán lương."
L12_1[1] = L13_1
L12_1[2] = L14_1
L13_1 = {}
L14_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_BD_ELIZABETH"
L15_1 = "Elizabeth Pendragon là một người tấn công tự do di chuyển trên chiến trường để thực hiện các đòn tấn công AoE.\n\nPrydwen là một cơ quan tình báo bí mật đã được đồn đại từ lâu. Sự thật duy nhất trong tất cả những tin đồn về tổ chức này là Thủ lĩnh của Prydwen đã luôn sử dụng cái tên Pendragon trong suốt những năm qua.\n\nXuất thân từ một gia đình danh tiếng, Elizabeth là tấm gương sáng về nghĩa vụ quý tộc, từ bỏ cuộc sống yên bình của mình để phục vụ hoàng gia và công chúng.\n\nXử lý các đồ tạo tác từ Counterside không phải là một công việc tao nhã, nhưng cô ấy giải quyết tất cả những thách thức mà cô ấy phải đối mặt trong công việc một cách duyên dáng.\n\nĐiểm yếu duy nhất là cô ấy đang làm mọi thứ một cách quá tự tin. Các đặc vụ khác coi người phụ nữ tự tin này như một quả bom tuyệt đẹp.\n "
L13_1[1] = L14_1
L13_1[2] = L15_1
L14_1 = {}
L15_1 = "SI_DESC_TOOLTIP_35"
L16_1 = "Bất kỳ ai cũng có thể tham gia chế độ Trận chiến Xếp hạng, nhưng sau khi sử dụng hết Điểm thưởng của mình, họ sẽ không thể nhận được Điểm PvP nữa."
L14_1[1] = L15_1
L14_1[2] = L16_1
L15_1 = {}
L16_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_AMY"
L17_1 = "Amy Strickland là một người tiên phong,\nngười thực hiện các cuộc tấn công tầm xa\nbằng chiếc yoyo đặc biệt của mình.\nKhi cô ấy hòa vào nhịp điệu của trận chiến,\nkỹ năng yoyo của cô ấy trở nên tuyệt vời hơn và nhanh hơn.\nLà thủ lĩnh của Freedom Riders,\nAmy không bao giờ trốn tránh đối mặt\nvới nguy hiểm. Điều này thường khiến cô ấy\nvướng vào đủ loại rắc rối, nhưng cô ấy luôn\nđộng viên người khác và giải quyết xung đột.\nCô ấy tin rằng cô trở hành một\nCounter nhằm giúp đỡ người khác và\nluôn cố gắng sử dụng quyền năng của mình đúng chỗ.\nCô ấy tự mình làm mọi việc\nmà không cần phần thưởng, đây là\nmột thái độ hiếm thấy trong ngành công nghiệp hiện nay."
