L2_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_S_STATE_RIFLE"
L3_1 = "Lính tấn công này định kỳ thực hiện các cuộc tấn công khu vực,\nvà mạnh hơn sau mỗi đòn tấn công.\nHọ là đơn vị cơ sở của lực lượng phòng thủ quốc gia Hoa Kỳ. Họ đang\ntham gia vào cuộc chiến chống Ăn Mòn, thử nghiệm\nthiết bị mới được phát triển trong một dự án đổi mới quân đội. Vật Thể Ăn Mòn sẽ\nsớm phải sợ hãi trước Sao và Sọc.\n"
L1_1[1] = L2_1
L1_1[2] = L3_1
L2_1 = {}
L3_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_S_TIDE_SUBMACHINEGUN"
L4_1 = "Lính tấn công tầm xa trở nên mạnh mẽ hơn\nkhi trận chiến diễn ra.\nTrinh sát là đơn vị được sử dụng ban đầu trong trận chiến,\nloại bỏ các mối đe dọa của kẻ thù bằng đòn phủ đầu.\nĐược trang bị những bộ giáp chiến đấu nhẹ\nvà súng tiểu liên, họ đi qua\nchiến trường nguy hiểm để giúp đồng minh băng qua\nchiến tuyến của kẻ thù và thu thập thông tin có giá trị.\nNhiều người trong số họ được biết đến là kẻ ba hoa,\nnhưng có lẽ đó là cách duy nhất để họ\ngiảm bớt căng thẳng và sợ hãi\nhọ phải trải qua trong trận chiến.\n "
L2_1[1] = L3_1
L2_1[2] = L4_1
L3_1 = {}
L4_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_S_ORCA_EDDIE"
L5_1 = "Eddie Fisher là một lính tấn công\ncó thể lãnh đạo hiệu quả những người lính đánh thuê của mình.\nAnh ta được biết đến nhiều hơn với cái tên Người đàm phán\ntrong ngành. Anh ấy có biệt danh này\nvì anh ấy luôn nhận\nsố tiền chính xác từ những khách hàng kiếm đủ\nmọi lý do để cắt giảm lương. Điều đó khiến\nmột số khách hàng tức giận, nhưng nhiều người\nvẫn muốn thuê anh ấy vì\nanh ấy luôn hoàn thành công việc của mình.\nVũ khí của Eddie không phải là súng hay chất nổ,\nmà là cái lưỡi mượt mà và cách đánh giá\ntình huống điềm tĩnh. Anh ấy là\nngười hướng dẫn tốt nhất khi nói đến\nnhững bài học cho người mới, những người thường mạo hiểm\nmạng sống của mình để kiếm chút tiền tiêu vặt.\n"
L3_1[1] = L4_1
L3_1[2] = L5_1
L4_1 = {}
L5_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_VATICAN_BENEDICT"
L6_1 = "Benedict Constantine là một lính phòng vệ đa năng,\nngười bảo vệ đồng minh khỏi bị thương nặng,\ntrong khi làm choáng kẻ thù.\nHội đồng Điều tra Kỳ sự là một tổ chức\nđược thành lập để\nbảo vệ Người của Lord khỏi Hiệu Ứng Ăn Mòn. Là một thành viên của Hội đồng,\nBenedict tàn phá tiền tuyến bằng\nsự tận tâm sắt đá và kiếm thuật phi thường của mình.\nSự phục vụ tận tâm của anh ấy được\nnhiều người ngưỡng mộ.\nNhưng có những người nghi ngờ,\nliệu anh ấy có đang đi đúng con đường của\nđức tin hay không. Các giáo sĩ của Hội đồng\nlo lắng rằng Benedict dường như đã thay đổi\nquan điểm của mình về các học thuyết sau khi bước vào\nthư viện bí mật ở Thành phố Vatican."
L4_1[1] = L5_1
