L42_1 = "SI_ITEM_DESC_IQI_EQUIP_COUNTER_ACC_681341"
L43_1 = "Một chiếc núm vặn được trao cho những Counter không sợ hãi.\nNó chủ yếu thuộc sở hữu của những người tham gia Cuộc Chiến Đại Thanh Lọc."
