L8_1 = "SI_COLLECTION_UNIT_INTRO_OPR_RAS_TOWER"
L9_1 = "  Sigma là trưởng phòng Chiến Lược Tương Lai và là một nhân viên gương mẫu không bao giờ xao nhãng công việc hàng ngày của mình: đọc truyện tranh, để trí tưởng tượng bay bổng và trả lời các cuộc gọi của bố.\n Nhưng đến khi trở thành Người Điều Hành, Sigma mới thực sự tỏa sáng . Cô ấy là phi công không có giấy phép xuất sắc nhất thế giới có tỷ lệ tai nạn là 0, với khả năng chiến thuật chỉ huy một chiều mà ngay cả học sinh tiểu học cũng có thể hiểu được. Vì vậy, đừng ngạc nhiên nếu bạn nghe thấy một cô bé ra lệnh với các nhân viên còn lại của tàu. "
L7_1[1] = L8_1
L7_1[2] = L9_1
L8_1 = {}
L9_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_MAID_C_TONFA"
L10_1 = "Mone là một lính phòng vệ đặc biệt giỏi trong việc đẩy lùi chiến tuyến kẻ thù và phong tỏa các kỹ năng của chúng. \n\n Sinh ra ở một làng chài nghèo, cô lớn lên dưới sự yêu thương đùm bọc của mọi người dân trong làng. Một ngày nọ, cô gặp Veronica và cùng cô ấy xây dựng Flora Maid Service. Cô ấy hiện đang luyện tập chăm chỉ với tư cách là thành viên trẻ nhất trong công ty của mình. \n Mone thường khiến Lily tức giận vì cô ấy luôn làm việc mà không suy nghĩ, nhưng cô ấy trung thành với chủ nhân của mình như những người hầu cận khác. "
L8_1[1] = L9_1
