L10_1 = "SI_COLLECTION_UNIT_INTRO_OPR_MARK_FINRI"
L11_1 = "Mark Finley là một đặc vụ tình báo đã làm nhiệm vụ gián điệp ở khắp mọi nơi trên thế giới từ khi còn trẻ. Anh ta được cấp trên đặc biệt khen ngợi vì khả năng thực hiện các hoạt động tác chiến ở Counterside đầy nguy hiểm.\nHiện tại, anh ta được cho là một thành viên của Văn Phòng Tình Báo Chỉ Huy Liên Minh Quản Trị. Tuy nhiên, sự nghiệp này của anh ấy cũng có thể chỉ là ngụy trang."
L9_1[1] = L10_1
L9_1[2] = L11_1
L10_1 = {}
L11_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_STREGA_2_INTERLUDE_1"
L12_1 = "Các công cụ bị bùa mê rất nguy hiểm.\nChúng có thể cắn vào tay người sử dụng chúng. "
L10_1[1] = L11_1
L10_1[2] = L12_1
L11_1 = {}
L12_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_STREGA_1_INTERLUDE_1"
L13_1 = "Chào mừng đến với quán cà phê phù thủy, Strega! \nTại đây, bạn có thể thoát khỏi cuộc sống trần tục hàng ngày, tận hưởng phép thuật huyền bí và nước thánh ngọt ngào của chúng tôi. \nLần đầu tiên bạn đến đây ư? Vui lòng xem hướng dẫn về quán cà phê của chúng tôi trước nhé. "
L11_1[1] = L12_1
L11_1[2] = L13_1
L12_1 = {}
L13_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_STREGA_2_INTERLUDE_3"
L14_1 = "Các phù thủy không tin vào khoa học, nhưng ngay cả họ cũng không thể phủ nhận sức mạnh của di truyền học."
L12_1[1] = L13_1
L12_1[2] = L14_1
L13_1 = {}
L14_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_MAID_C_MASK"
L15_1 = "Lily là lính hỗ trợ có khả năng vô hiệu hóa các Ưu Điểm Vai Trò của mục tiêu và khiến kẻ thù ở tuyến sau chìm vào giấc ngủ. \n\n Cô ấy sử dụng mọi thứ có thể — bài hát ru, khăn giường sang trọng, thậm chí cả thuốc ngủ tức thì và súng — để loại bỏ những kẻ thù là ác mộng của cô ấy. Tất nhiên, cô ấy tuyên bố rằng hiện tại cô ấy chỉ sử dụng các phương pháp vừa phải như liệu pháp hương thơm. \n Là cấp trên nghiêm khắc của Mone và Lycoris, cô ấy đang nghiên cứu để được xã hội chấp nhận hơn với sự giúp đỡ của Người Hầu Chính. "
L13_1[1] = L14_1
L13_1[2] = L15_1
L14_1 = {}
L15_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_REPLACER_CA_KING"
L16_1 = "  Quân Vua Nhân Bản là một Lính Phòng Vệ có khả năng triệu tập nhiều binh lính và thực hiện các cuộc tấn công AoE không giới hạn trong một số tình huống nhất định.\n\nAnh ta cũng là người sáng lập Nghiệp Đoàn Nhân Bản, tại đó, các thành viên cốt lõi luôn những người ủng hộ nhiệt thành cho lý tưởng của anh ta. Turncoats tuyên bố rằng tất cả những người còn lại của tổ chức ngưỡng vọng anh ta như thể anh ta là người tiên phong.\nBất chấp những nỗ lực mạnh mẽ của nhiều cơ quan tình báo, anh ta vẫn giữ bí mật danh tính của mình. Một số người nghi ngờ anh ta có thể đã làm việc cho một cơ quan tình báo hoặc một trung đoàn quân đội bất hợp pháp hoạt động bí mật. "
L14_1[1] = L15_1
L14_1[2] = L16_1
L15_1 = {}
L16_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_REPLACER_CA_QUEEN"
L17_1 = "  Quân Hậu Nhân Bản là một Lính Bắn Tỉa kiểm soát kẻ thù bằng Hiệu Ứng Bất Lợi và liên tục nâng cao sức mạnh của bản thân thông qua các cuộc tấn công AoE.\n\nCô ta hiện đang lãnh đạo tổ chức của mình ở vị trí của Quân Vua, cô ấy được coi là nguy hiểm như một V.T.B.A.M Loại 4. Vì cô ấy rất nỗ lực loại bỏ gián điệp trong tổ chức của mình, nên không có nhiều thông tin được tiết lộ ra bên ngoài.\nNhưng theo những gì chúng tôi biết, cô ta là một người ủng hộ nhiệt thành của Quân Vua, nhưng dường như không quan tâm đến những lý tưởng của anh ta."
L15_1[1] = L16_1
L15_1[2] = L17_1
L16_1 = {}
L17_1 = "SI_COLLECTION_UNIT_INTRO_OPR_REPLACER_COMMANDAR"
L18_1 = "Những người ủng hộ lý tưởng xoắn của Nghiệp Đoàn Nhân Bản bao gồm các cựu sĩ quan quân đội. Họ sử dụng kiến thức và kinh nghiệm có được trong những ngày tháng phục vụ quân ngũ để đào tạo những người khác một cách có hệ thống và chiến lược, góp phần đưa tổ chức của họ phát triển trở thành một mối đe dọa thực sự đối với phần còn lại của thế giới. Một số người trong số họ đã đầu hàng trong trận chiến, nhưng hầu hết vẫn tin rằng họ là những người được chọn."
L16_1[1] = L17_1
L16_1[2] = L18_1
L17_1 = {}
L18_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_REPLACER_C_KNIGHT"
L19_1 = "  Quân Xe Nhân Bản là một Lính Phòng Vệ lao vào bất cứ nơi nào trên chiến trường để phá hủy đội hình của kẻ thù.\n\nLà một tội phạm quốc tế bị truy nã ở nhiều quốc gia, cô ta nổi tiếng với thiên hướng tiêu diệt hoàn toàn kẻ địch. Sự bạo lực của cô ấy, kết hợp với tính cách cực đoan của cô ấy, cũng khiến cô ấy không được lòng những người phe mình.\nDựa trên dữ liệu nghiên cứu bị rò rỉ, các nhà nghiên cứu của Nghiệp Đoàn Nhân Bản đã cố tình truyền cho các đối tượng thử nghiệm của họ tính hiếu chiến và kiêu ngạo thông qua việc huấn luyện cưỡng bức và cạnh tranh khốc liệt. Hãy ghi nhớ điều này trong trường hợp bạn gặp phải cô ấy. "
L17_1[1] = L18_1
L17_1[2] = L19_1
L18_1 = {}
L19_1 = "SI_MOB_NAME_BOSS_DIVE_SCAVENGER_S_HAMMER"
L20_1 = "Rojo"
L18_1[1] = L19_1
L18_1[2] = L20_1
L19_1 = {}
L20_1 = "SI_COLLECTION_UNIT_INTRO_OPR_LENA"
L21_1 = "Lena là một học viên xuất sắc đã tốt nghiệp Học Viện Đào Tạo Người Điều Hành với danh hiệu cao quý nhất. Bởi vì cô ấy đã hoàn thành chương trình tại đây quá nhanh với quyết tâm trở thành một Nhà Điều Hành vĩ đại, các giáo sư luôn ca ngợi cô ấy là tấm gương lớn để truyền cảm hứng cho học viên của họ trong buổi học đầu tiên tại Học Viện.\nLena đã bỏ học để trở thành một nhân viên chính phủ và trở thành một Người Điều Hành vì cô ấy thần tượng Frederica, nữ chính của vở opera bi lụy nổi tiếng, Cây Cầu Cám Dỗ. Tuy nhiên, không giống như thần tượng của mình, Lena vẫn thích uống bia."
L19_1[1] = L20_1
L19_1[2] = L21_1
L20_1 = {}
L21_1 = "SI_COLLECTION_UNIT_INTRO_OPR_ALICIA"
L22_1 = "Lime là phiên bản tiếp theo của phần mềm thị trường đại chúng do Chiến Tranh Tương Lai phát triển. Trong khi phiên bản trước đó chủ yếu tập trung vào tính thực tế, Lime được quảng cáo như một thư ký AI cung cấp các biểu thức và chức năng tương tác độc đáo.\nNó có thể không hoạt động tốt như sản phẩm cạnh tranh của Alphatrix được phát hành sau đó, nhưng vẫn được yêu thích nhờ độ tin cậy của sản phẩm và tiện ích bổ sung phong phú được bổ sung trong những năm qua. "
L20_1[1] = L21_1
L20_1[2] = L22_1
L21_1 = {}
L22_1 = "SI_ITEM_DESC_IQI_EQUIP_COUNTER_ACC_651341"
L23_1 = "Núm vặn của một bạo chúa trong truyện kể.\nNó tỏa ra năng lượng nóng cháy và giận dữ.\n<color=#ffd34c>Các tùy chọn bộ của nó là không thể thay đổi được.</color>"
