L15_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_S_ADMIN_SHIELD"
L16_1 = "Những người Lính Phòng Vệ tạo rào chắn khi HP của họ xuống thấp. Họ là những đơn vị chủ chốt của Cục Quản Lý Cũ.\n\nBộ giáp dày cộp của họ cho phép họ thể hiện sức mạnh thể chất vượt trội so với trang bị hạng nặng. Các Tổng Tư Lệnh tiền tuyến cũng mặc bộ đồ bảo vệ tuyệt vời này."
L14_1[1] = L15_1
L14_1[2] = L16_1
L15_1 = {}
L16_1 = "SI_SHIP_SKILL_DESC_GLEIPNIR_ARMOR_SKILL1"
L17_1 = "Rào chắn pha đặc biệt hấp thụ 50% sát thương nhận vào trong 10 giây. Nếu sát thương hấp thụ vượt quá 5% HP, kỹ năng này đẩy lùi ngay lập tức tất cả kẻ địch xung quanh kèm theo sát thương diện rộng."
L15_1[1] = L16_1
L15_1[2] = L17_1
L16_1 = {}
L17_1 = "SI_SHIP_SKILL_DESC_ENTERPRISE_HYPER1"
L18_1 = "Tạo ra rào chắn pha mạnh để gây sát thương. Các rào chắn này di chuyển và dồn kẻ thù vào trung tâm bản đồ, sau đó phát nổ, bắn kẻ thù lên không trung bằng sát thương AoE."
L16_1[1] = L17_1
L16_1[2] = L18_1
L17_1 = {}
L18_1 = "SI_SHIP_SKILL_DESC_GLEIPNIR_ARMOR_SKILL1_LV2"
L19_1 = "Rào chắn pha đặc biệt nâng cao hấp thụ 50% sát thương nhận vào trong 10 giây. Nếu sát thương hấp thụ vượt quá 5% HP, kỹ năng này đẩy lùi ngay lập tức tất cả kẻ địch xung quanh kèm theo sát thương diện rộng. Nếu sát thương dưới mức đó, kỹ năng này sẽ gây 50% sát thương."
L17_1[1] = L18_1
L17_1[2] = L19_1
L18_1 = {}
L19_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_M_ADMIN_CANNON"
L20_1 = "Chuyên bắn phá ở khoảng cách cực xa, các đơn vị bắn tỉa này có thể cung cấp hỏa lực mạnh dần theo thời gian chúng ở trên chiến trường. \n\nHọ là những đơn vị phòng thủ tối thượng của Cục Quản Lý Cũ. Hỏa lực lớn của đơn vị này có thể tiêu diệt mục tiêu cách xa hàng dặm. \n\nVề mặt lý thuyết, súng hạt 155mm của nó thậm chí cũng hiệu quả khi chống lại Vật Thể Ăn Mòn Loại 4."
L18_1[1] = L19_1
L18_1[2] = L20_1
