L14_1 = "SI_SHIP_SKILL_DESC_COMMON_REPAIR_SKILL1_LV2"
L15_1 = "Sử dụng drone sửa chữa nâng cao để khôi phục chức năng của tàu. Phục hồi mạnh HP của tàu định kỳ."
