L3_1 = "Sử dụng <COLOR=#FFBC00>Nhà Điều Hành có những kỹ năng phụ khác nhau</COLOR> làm nguyên liệu để có được kỹ năng phụ mà bạn muốn.\nNhà Điều Hành nguyên liệu <COLOR=#FFBC00>phải cùng cấp hay có cấp cao hơn Nhà Điều Hành mục tiêu</COLOR>.\n<COLOR=#FFBC00>Bật nút Thay Đổi Kỹ Năng Phụ</COLOR> để thay đổi kỹ năng phụ.\nKhi được thay đổi, <COLOR=#FFBC00>kỹ năng phụ của bạn được đặt lại thành 1</COLOR>."
L1_1[1] = L2_1
L1_1[2] = L3_1
L2_1 = {}
L3_1 = "SI_PF_EVENT_MISSION_INFO_KILLER_TEXT"
L4_1 = "<color=#ffcf3b><b>Tất Ấm Áp</b></color>, \ncó sẵn để nhận hàng tuần thông qua hồi Sự Kiện này, có thể được trao đổi lấy nhiều sản phẩm khác nhau."
L2_1[1] = L3_1
L2_1[2] = L4_1
L3_1 = {}
L4_1 = "SI_PF_EVENT_MISSION_INFO_VALENTINE_TEXT"
L5_1 = "<color=#ffcf3b><b>Bóng Choco</b></color>, \ncó sẵn để nhận hàng tuần thông qua hồi Sự Kiện này, có thể được trao đổi lấy nhiều sản phẩm khác nhau."
L3_1[1] = L4_1
L3_1[2] = L5_1
L4_1 = {}
L5_1 = "SI_PF_EVENT_MISSION_INFO_MAID_TEXT"
L6_1 = "<color=#ffcf3b><b>Tờ Rơi Tạm Thời</b></color> và <color=#ffcf3b><b>Băng-đô</b></color>, có sẵn để nhận hàng tuần thông qua hồi Sự Kiện này, có thể được trao đổi lấy nhiều vật phẩm khác nhau."
L4_1[1] = L5_1
