L10_1 = {}
L11_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_ADMIN_NA_YUBIN"
L12_1 = "(Văn bản này đã được khôi phục bởi Quản trị viên Cấp 1.)\nNa Yubin là lính tấn công chịu trách nhiệm hỗ trợ hỏa lực phía sau cho Sư Đoàn FENRIR. Anh ta thường thực hiện các nhiệm vụ kiểm soát, nhưng anh ta cũng tung ra các đòn tấn công phạm vi mạnh mẽ trong trận chiến để lật ngược tình thế.\n\nAnh ta là một trong số ít đặc vụ có thể đánh giá tình huống từ một góc nhìn bao quát. Bởi vì anh ấy luôn suy nghĩ về việc di chuyển sau chiến đấu, anh ấy thường bị các thành viên khác của sư đoàn mắng mỏ vì sự lẩn thẩn của mình.\n\nMặc dù Na Yubin đã được đề nghị tham gia khóa đào tạo Tổng Tư Lệnh bởi một số đơn vị mà anh ấy từng làm việc, nhưng anh ấy tiếp tục từ chối lời đề nghị với lý do rằng anh ấy vẫn còn rất nhiều điều để học hỏi từ FENRIR. Đáp lại điều này, người Tổng Tư Lệnh đã nhận xét rằng, trước hết anh ta nên xa rời phương pháp luận của sách giáo khoa.\n "
L10_1[1] = L11_1
L10_1[2] = L12_1
