L39_1[2] = L41_1
L40_1 = {}
L41_1 = "SI_PF_TUTORIAL_TEXUTRE_SHIP_MAKE_2_DESC"
L42_1 = "<COLOR=#FFBC00>Mỗi con tàu có điều kiện xây dựng riêng.</COLOR> Bạn có thể kiểm tra chúng ở phía dưới cùng của mỗi cửa sổ tàu."
L40_1[1] = L41_1
L40_1[2] = L42_1
L41_1 = {}
L42_1 = "SI_PF_TUTORIAL_TEXUTRE_DUNGEON_INFO_2_DESC_01"
L43_1 = "<COLOR=#FFBC00>Đánh bại Boss kẻ thù</COLOR> để <COLOR=#FFBC00>thắng</COLOR> trận chiến.\nĐiều kiện thắng có thể thay đổi, tùy theo loại trận chiến."
L41_1[1] = L42_1
L41_1[2] = L43_1
L42_1 = {}
L43_1 = "SI_PF_TUTORIAL_TEXUTRE_WARFARE_CONTROL_2_DESC"
L44_1 = "<COLOR=#FFBC00>Tiểu đội sử dụng 1 Đạn Dược mỗi trận chiến</COLOR>.\nCác tiểu đội tham gia trận chiến mà không có đạn<COLOR=#FFBC00> sẽ tự động thua</COLOR> và bị phá hủy."
L42_1[1] = L43_1
L42_1[2] = L44_1
L43_1 = {}
L44_1 = "SI_PF_TUTORIAL_TEXUTRE_DUNGEON_UNIT_TYPE_1_DESC"
L45_1 = "<COLOR=#FFBC00>Một số đơn vị nhất định có thể bay</COLOR>.\nHãy nhớ rằng một số đơn vị <COLOR=#FFBC00>không thể tấn công các đơn vị Trên Không</COLOR>.\n<COLOR=#FFBC00>Tàu và Boss </COLOR>đều không bị ảnh hưởng bởi<COLOR=#FFBC00></COLOR> Mặt Đất và Trên Không."
L43_1[1] = L44_1
L43_1[2] = L45_1
L44_1 = {}
L45_1 = "SI_PF_TUTORIAL_TEXUTRE_RAID_INFO_2_DESC_02"
L46_1 = "<COLOR=#FFBC00>Chi phí thông tin gia tăng, tùy theo Cấp Độ của Boss</COLOR>.\nHãy thận trọng: Bạn có thể phải đánh với một Boss rất nhiều lần."
L44_1[1] = L45_1
L44_1[2] = L46_1
L45_1 = {}
L46_1 = "SI_PF_TUTORIAL_TEXUTRE_DUNGEON_INFO_2_DESC_02"
L47_1 = "Nếu <COLOR=#FFBC00>tàu của bạn bị phá hủy</COLOR>, bạn sẽ <COLOR=#FFBC00>thua</COLOR> trận chiến.\nBạn cũng sẽ thua nếu bạn <COLOR=#FFBC00>vượt giới hạn thời gian</COLOR>."
L45_1[1] = L46_1
L45_1[2] = L47_1
L46_1 = {}
L47_1 = "SI_PF_TUTORIAL_TEXUTRE_UNIT_ENCHANT_2_USE"
L48_1 = "<COLOR=#FFBC00>Chỉ có thể sử dụng cúp cho EXP Cường Hóa. Hãy sử dụng chúng bất cứ khi nào bạn có!</COLOR>"
L46_1[1] = L47_1
L46_1[2] = L48_1
L47_1 = {}
L48_1 = "SI_PF_TUTORIAL_TEXUTRE_SYSTEM_COLLETION_2_DESC"
L49_1 = "<COLOR=#FFBC00>Tập hợp tất cả thành viên trong cùng nhóm</COLOR> để nhận phần thưởng Lập Nhóm.\nTập hợp những thành viên mà bạn chưa có!"
L47_1[1] = L48_1
L47_1[2] = L49_1
L48_1 = {}
L49_1 = "SI_PF_TUTORIAL_TEXUTRE_UNIT_NEGOTIATION_2_DESC"
L50_1 = "<COLOR=#FFBC00>Kết quả đàm phán cuối cùng có thể thay đổi</COLOR>, tùy theo thay đổi thành công đàm phán của bạn.\nNó cũng ảnh hưởng đến <COLOR=#FFBC00>Mức Trung Thành</COLOR> của đơn vị. Hãy đàm phán cẩn thận!"
L48_1[1] = L49_1
L48_1[2] = L50_1
L49_1 = {}
L50_1 = "SI_PF_TUTORIAL_TEXUTRE_DUNGEON_HIT_COUNT_1_DESC"
L51_1 = "<COLOR=#FFBC00>Đòn tấn công nhắm đến nhiều kẻ thù</COLOR> có<COLOR=#FFBC00> Đòn Hiệu Quả</COLOR>.\nChúng<COLOR=#FFBC00> được triển khai theo thứ tự từ điểm tấn công</COLOR>, và số đòn vượt đòn hiệu quả<COLOR=#FFBC00> có sát thương thấp hơn đáng kể</COLOR>.\nSử dụng <COLOR=#FFBC00>nhiều đơn vị</COLOR> nhất có thể để<COLOR=#FFBC00> phân tán sát thương AoE sắp tới</COLOR>."
