L33_1 = "SI_PF_FRIEND_MENTORING_MISSION_LIST_TEXT"
L34_1 = "<size=36>Nhiệm Vụ Sự Kiện</size>\nHoàn thành tất cả những nhiệm vụ này để nhận phần thưởng đặc biệt!"
L32_1[1] = L33_1
