L31_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_ALPHA_CHOI"
L32_1 = "Gabriel Jun Kẻ Phạm Luật Xấu Xa là\nmột người bảo vệ mạnh mẽ, nâng cao khả năng né tránh của đồng minh\nbằng kiếm thuật độc đáo của mình.\nAnh ấy đã đi khắp thế giới và\nhọc được nhiều kỹ năng kiếm thuật khác nhau,\nnhưng không kiếm thức nào làm anh ấy hài lòng.\nVì vậy, anh ấy đã tạo một kiếm thức mới của riêng mình,\nchỉ sau một tháng. Kiếm Thuật Bất Động\ncho phép anh ấy chống lại kẻ thù từ mọi phía,\nnhưng anh ấy là người duy nhất có thể thành thạo nó.\nHiện tại, anh ấy đang đóng vai trò là Người Phán Xét của Cái Ác\nđể duy trì sự cân bằng của thế giới,\nđiều mà anh ấy đã nhận ra khi tạo ra kiếm thuật của mình.\n*Tuyên bố này không được xác nhận là đúng.\nĐó chỉ là một tuyên bố cá nhân của đối tượng.\n"
L30_1[1] = L31_1
L30_1[2] = L32_1
