L6_1 = "SI_PF_TUTORIAL_TEXUTRE_EQUIP_BREAKUP_1_DESC"
L7_1 = "Trong <COLOR=#FFBC00>Kho lưu trữ</COLOR>, bạn có thể <COLOR=#FFBC00>tháo dỡ trang bị không mong muốn</COLOR> và đổi lấy Xu Vàng.\nXin lưu ý rằng trang bị đã bị tháo dỡ <COLOR=#FFBC00>không thể khôi phục được</COLOR>.\n\nKhông thể tháo dỡ trang bị bị <COLOR=#FFBC00>khóa</COLOR> hoặc <COLOR=#FFBC00>đang sử dụng</COLOR>."
L5_1[1] = L6_1
L5_1[2] = L7_1
L6_1 = {}
L7_1 = "SI_PF_TUTORIAL_TEXUTRE_DIVE_ARTIFACT_2_DESC"
L8_1 = "Bạn chỉ có thể nhận 1 trong 3 loại Thần Khí Nhân Tạo, Thần Khí được chọn sẽ kéo dài đến khi kết thúc Lặn. \nCác Thần Khí được thu thập sẽ được thêm vào Kho Thần Khí ở sườn trái màn hình."
L6_1[1] = L7_1
L6_1[2] = L8_1
L7_1 = {}
L8_1 = "SI_PF_TUTORIAL_TEXUTRE_PVP_INFO_1_DESC"
L9_1 = "Trong Đấu Gauntlet, bạn có thể <COLOR=#FFBC00>chiến đấu với người chơi khác</COLOR>."
L7_1[1] = L8_1
L7_1[2] = L9_1
