L9_1 = "SI_PF_TUTORIAL_TEXUTRE_SYSTEM_COLLETION_1_DESC"
L10_1 = "Bạn có thể kiểm tra nhân viên và tàu mà bạn có, cũng như những nhân viên và tàu mà bạn chưa có.\nBạn cũng có thể xem lại Xu Hướng cũ và cảnh cắt Chuyện Bên Lề."
