L10_1 = "SI_PF_TUTORIAL_TEXUTRE_PVP_MATCH_1_DESC"
L11_1 = "Bạn có thể nhận một mức Điểm Đấu Gauntlet nhất định mỗi ngày thông qua Trận chiến Luyện Tập.\nTrận Chiến Luyện Tập dược tiến hành không đồng bộ.\n\nBạn có thể nhận một số Điểm PvP nhất định/ngày thông qua Trận Chiến Luyện Tập.\n<COLOR=#FFBC00>※ Không thể nhận điểm thông qua Trận Chiến Luyện Tập với Đối Tác.</COLOR>\n"
L9_1[1] = L10_1
L9_1[2] = L11_1
L10_1 = {}
L11_1 = "SI_PF_TUTORIAL_TEXUTRE_PVP_RANK_1_DESC"
L12_1 = "Trận Chiến Xếp Hạng được <COLOR=#FFBC00>tổ chức trong thời gian thực</COLOR>.\nTrong Trận Chiến Xếp Hạng, bạn sẽ được ghép trận với những người dùng có cùng khung <COLOR=#FFBC00>Điểm Chiến Thắng</COLOR> như bạn.\nNếu bạn thắng, bạn nhận được Điểm Chiến Thắng; nếu thua, bạn sẽ mất chúng."
L10_1[1] = L11_1
L10_1[2] = L12_1
