L16_1 = "SI_PF_TUTORIAL_TEXUTRE_WARFARE_EMERGENCY_REPAIR_DESC"
L17_1 = "Chúng có thể được thêm vào ô nơi các tiểu đội của bạn có thể di chuyển đến, nhưng sẽ không vào các ô mà kẻ thù đã chiếm.\n<COLOR=#FFBC00>Các tiểu đội được sửa chữa nhanh được thêm vào trạng thái Hành Động Hoàn Tất</COLOR>."
L15_1[1] = L16_1
L15_1[2] = L17_1
L16_1 = {}
L17_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_M_FOX_VEHICLE"
L18_1 = "Một đội tiên phong đẩy lùi kẻ địch khi được triển khai.\nChúng là phương tiện đa dụng cơ động cao được\ncung cấp trong Cuộc Chiến Đại Thanh Lọc. Họ\nchỉ có vũ khí trang bị đơn giản, nhưng họ có thể\nlao vào khu vực chiến đấu để ngăn chặn nhanh các bước tiến của kẻ thù.\nKhẩu súng máy gắn trên đầu\ncho phép họ tham gia một trận chiến tương đối an toàn chống lại Vật Thể Ăn Mòn Loại 1.\nVì lý do này, chúng đã từng được Lực lượng Thống Nhất\nsử dụng để duy trì an ninh xung quanh trại của họ.\nTrải nghiệm phấn khích khi đi xe vẫn không thay đổi\nngay cả khi đã cài đặt AI."
L16_1[1] = L17_1
L16_1[2] = L18_1
L17_1 = {}
L18_1 = "SI_PF_TUTORIAL_TEXUTRE_OPERATION_COUNTER_CASE_1_DESC"
L19_1 = "Trong Hồ Sơ Counter, bạn có thể <COLOR=#FFBC00>xem các hồ sơ của những đơn vị mà bạn nhận</COLOR>.\nCác hồ sơ bao gồm dữ liệu về bối cảnh của đơn vị mà bạn có thể kiểm tra và thu thập <COLOR=#FFBC00>phần thưởng</COLOR> từ họ."
L17_1[1] = L18_1
L17_1[2] = L19_1
