L36_1[2] = L38_1
L37_1 = {}
L38_1 = "SI_PF_TUTORIAL_TEXUTRE_FIERCE_04_DESC_01"
L39_1 = "Bạn có thể nhận được phần thưởng Nguy Hiểm Cận Kề, tùy thuộc vào xếp hạng của bạn. Phần thưởng xếp hạng có thể được thu thập thông qua menu Nguy Hiểm Cận Kề chính trong thời gian Ấn Định. <COLOR=#FFBC00>Phần thưởng chưa có người nhận sẽ biến mất. </COLOR>"
L37_1[1] = L38_1
L37_1[2] = L39_1
L38_1 = {}
L39_1 = "SI_PF_TUTORIAL_TEXUTRE_FIERCE_03_DESC_01"
L40_1 = "Bạn có thể nhận được phần thưởng Điểm Nguy Hiểm Cận Kề, tùy thuộc vào Điểm Tiêu Diệt của bạn. <COLOR=#FFBC00>Phần thưởng không có người nhận</COLOR> trong các giai đoạn Loại Bỏ và Ấn Định<COLOR=#FFBC00> biến mất </COLOR> sau mùa giải Nguy Hiểm Cận Kề."
L38_1[1] = L39_1
L38_1[2] = L40_1
L39_1 = {}
L40_1 = "SI_PF_TUTORIAL_TEXUTRE_FIERCE_01_DESC_02"
L41_1 = "Nguy Hiểm Cận Kề bao gồm <COLOR=#FFBC00>giai đoạn Tiêu Diệt</COLOR> trong đó bạn chiến đấu với Boss và <COLOR=#FFBC00> giai đoạn Ấn Định</COLOR> trong đó bạn có thể nhận phần thưởng dựa trên xếp hạng của mình."
