L50_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_DAILY_DAMAGE_4"
L51_1 = "Đây là thông báo từ Bộ Phận Quản Lý.\nVị CEO và người dân đóng thuế trung thực của chúng ta đã thể hiện sự quan tâm sâu sắc đến kết quả các trận chiến mô phỏng trong thời gian qua của các bạn. Ngoài ra, xin thông báo rằng tin chiếc máy huấn luyện được làm từ các cấu phần dự phòng từ Xưởng Bảo Lưu là tin đồ vô căn cứ.  \n\n<color=#FFCF3B>Hãy tiêu diệt mục tiêu trong 1 phút. Nên sử dụng các đơn vị có hỏa lực mạnh.</color>"
L49_1[1] = L50_1
L49_1[2] = L51_1
L50_1 = {}
L51_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_DAILY_DAMAGE_1"
L52_1 = "Đây là thông báo từ Bộ Phận Quản Lý.\nVị CEO hào phóng của chúng ta đã tạo ra một chiếc máy huấn luyện để khuyến khích đặc vụ thực chiến và giúp họ cải thiện hiệu quả công việc. Hãy lập một đội và tham gia giao chiến trong cuộc chiến giả định với máy. Các đội có kết quả xuất sắc sẽ nhận được phần thưởng khuyến khích.\n\n<color=#FFCF3B>Hãy tiêu diệt mục tiêu trong 1 phút. Nên sử dụng các đơn vị có hỏa lực mạnh.</color>"
L50_1[1] = L51_1
L50_1[2] = L52_1
