L24_1 = "SI_ITEM_DESC_IQI_EQUIP_SOLDIER_WEAPON_223121"
L25_1 = "Khẩu súng trường tiến công đầu tiên được chế tạo để chiến đấu chống Ăn Mòn.\nCó lực hãm chống cá nhân tuyệt vời.\nTăng hỏa lực của Binh Lính."
L23_1[1] = L24_1
L23_1[2] = L25_1
L24_1 = {}
L25_1 = "SI_SKIN_DESC_NKM_UNIT_M_RAS_TOWER_WEDDING"
L26_1 = "Con bé có thể dễ dàng tính toán các dòng vốn quốc tế, nhưng lại chưa thể nắm bắt được cảm xúc của con người và các phong tục. Nhưng con bé không phải là cô con gái đầu tiên muốn cưới bố mình khi lớn lên. Có lẽ bây giờ chúng tôi nên chơi cùng nhau để lưu lại kỷ niệm  khi Sigma lớn lên.\n\n<color=#ffd34c>Vậy đấy - đây là món quà tuyệt vời nhất từ hạc tiên!</color>"
L24_1[1] = L25_1
L24_1[2] = L26_1
L25_1 = {}
L26_1 = "SI_SKIN_DESC_NKM_UNIT_C_VATICAN_CINDY_HALLOWEEN"
L27_1 = "Khát khao bạo lực không chỉ dành cho cái ác; nó cũng tồn tại ở những con chiên bé nhỏ của Chúa. Và đó là cách hòa bình của thế giới được duy trì. Thật tuyệt khi biết thế phải không?\n<color=#ffd34c>Mm, cái mặt nạ này? Một chiến tích chiến tranh. Từ một người hát rong khá nổi tiếng quanh khu phố này.</color> "
L25_1[1] = L26_1
