L27_1 = "SI_SKIN_DESC_NKM_UNIT_C_BD_ELIZABETH_SUMMER"
L28_1 = "Đảo Blue Rose rực rỡ một màu xanh lam trong những đêm diễn ra lễ hội được tổ chức trùng với thời kỳ hoạt động của bướm xanh.\nNhững con bướm này không thể sống bên ngoài đảo vì sự lựa chọn thức ăn hạn chế của chúng và nhiều kẻ săn mồi.\nTuy nhiên, sự dễ bị tổn thương như vậy chỉ làm tăng thêm sự quý giá của chúng.\n\n<color=#ffd34c>Chúng rất đẹp phải không? Tôi biết một vài điều về những thứ xinh đẹp đấy</color>"
L26_1[1] = L27_1
