L31_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_DAYMINE_GANGSAN"
L32_1 = "Choi Gangsan là một chàng trai dễ mến\nvới vóc dáng vạm vỡ do yêu thể thao.\nAnh ta là một lính phòng vệ, người chế nhạo kẻ thù và bảo vệ đồng minh.\nChiếc khiên của anh ta được tạo ra từ Đồng hồ, rõ ràng\nlà bị ảnh hưởng bởi kinh nghiệm làm cảnh sát chống bạo động,\ntrông giống như một chiếc khiên bình thường. Nhưng nó thực sự\nmạnh hơn bất kỳ hợp kim Vàng Vĩnh Cửu nào.\nAnh ấy hơi nhạy cảm,\nthắt chặt bảo vệ của mình ngay cả với những sự kiện nhỏ trong cuộc sống\nhàng ngày — một chú Chihuahua đi ngang qua hoặc một chiếc xe tải xông khói\nđi qua — nhưng anh ấy là một người đàn ông chính trực,\nngười không bao giờ tiếc thân khi cứu mạng người khác."
L30_1[1] = L31_1
L30_1[2] = L32_1
L31_1 = {}
L32_1 = "SI_CONTRACT_RESET_TIME"
L33_1 = "Đặt lại hàng ngày lúc 4:00 giờ sáng"
L31_1[1] = L32_1
L31_1[2] = L33_1
L32_1 = {}
L33_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_ALPHA_SEAROM"
L34_1 = "Oh Saerom là một người hâm mộ lớn của chương trình truyền hình,\nCounter Giấu Mặt. Cô ấy là một lính tiên phong,\nngười xuất sắc trong việc chủ động và đẩy nhanh cuộc chiến.\nƯớc mơ của cô ấy là trở thành một Counter,\nngười đánh bại những kẻ xấu xa như Counter Giấu Mặt.\nCô ấy đã đăng ký tham gia Cải Cách Alphatrix\nbất chấp sự phản đối của gia đình, hy vọng\ntìm được những anh hùng có thể chiến đấu cùng cô ấy.\nTất nhiên, trong đời thực, những kẻ phản diện không\nxuất hiện đúng thời điểm như trong các\nchương trình siêu anh hùng. Vì vậy, hiện tại, Saerom chỉ đang chống lại\ncác Vật Thể Ăn Mòn đe dọa dân thường.\n "
L32_1[1] = L33_1
L32_1[2] = L34_1
L33_1 = {}
