L7_1 = {}
L8_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_POLICE_LEE_YUMI"
L9_1 = "Lee Yumi là một lính phòng vệ của SWAT 4, người chạy trên chiến tuyến với kỹ năng trốn tránh tuyệt vời của mình.\n\nMặc dù cô ấy là sĩ quan cảnh sát, cô ấy rất thù địch với bọn tội phạm nên cô ấy thường xuyên vung kiếm thay vì còng tay họ. Hành vi của cô ấy đã liên tục bị chỉ trích bởi các phương tiện truyền thông đại chúng, nhưng với tư cách là Counter duy nhất trong lực lượng cảnh sát có tỷ lệ bắt giữ cao nhất, cô ấy không thể bị đụng đến, ngay cả khi đó là cấp trên của cô. Đồng nghiệp của cô ấy, Kang Soyoung, cũng biết điều này và thường cố gắng đẩy trách nhiệm của mình cho Yumi. Cả hai luôn cãi vã với nhau, nhưng khi đối mặt với tội ác, họ trở thành cộng sự đắc lực nhất.\n\nVì Yumi luôn bận rộn chạy đến hiện trường vụ án, tất cả chủ tiệm bánh trong khu vực đều biết mặt cô ấy."
L7_1[1] = L8_1
L7_1[2] = L9_1
