L8_1[2] = L10_1
L9_1 = {}
L10_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_ALPHA_LEEJIN"
L11_1 = "Lee Jin là lính hỗ trợ, đốt cháy những kẻ địch\nở hậu phương, những kẻ cho rằng mình an toàn.\n Ngọn lửa của cô ấy nhấn chìm kẻ thù,\nnhưng nâng cao tinh thần của các đồng minh.\nLee Jin là thư ký của CEO Tập đoàn Alphatrix,\nvà được kỳ vọng sẽ đảm nhận vị trí quan trọng trong tương lai.\nNhưng thật không may, cô ấy bị đổ lỗi\nvì đã trở thành Counter trong cuộc chiến\ntranh giành quyền sở hữu của công ty, và bị giáng chức\nxuống nhóm quảng bá mới thành lập.\nGiữa một nhóm những kẻ gây rối và lập dị,\nLee Jin đã đổi mới suy nghĩ của mình và\nđang cố gắng hết sức để trở thành một phụ tá hoàn hảo cho thủ lĩnh của cô ấy.\n"
