L39_1 = "SI_SKIN_DESC_NKM_UNIT_C_YOO_MI_NA_WINTER"
L40_1 = "Hai bên má đào ửng đỏ.\nQuấn mình chiếc khăn ấm áp,\ncứ mỗi chốc lại nhấp ngụm cà phê,\nnàng bồn chồn chờ một ai đó.\n\n<color=#ffd34c>*Thở dài*... Xe buýt lại bị hoãn chuyến à?</color>"
L38_1[1] = L39_1
L38_1[2] = L40_1
L39_1 = {}
L40_1 = "SI_ITEM_MISC_DESC_IMI_ITEM_MISC_BG_TWN_MARKET"
L41_1 = "Một con phố về đêm được thắp sáng bằng những chiếc đèn lồng đỏ tuyệt đẹp. Có thể được sử dụng làm nền Sảnh."
L39_1[1] = L40_1
L39_1[2] = L41_1
L40_1 = {}
L41_1 = "SI_SKIN_DESC_NKM_UNIT_C_HILDE_VALEN"
L42_1 = "Người ta nói cứ say với bóng hồng.\nNhưng đừng nhìn ngắm quá lâu.\nDù nàng đã say khướt mất rồi.\nNhưng bạn vẫn có thể bị ăn đấm.\n\n<color=#ffd34c>Nhìn cái gì mà nhìn? Thấy tôi mắc cười quá hả? *Hic*.</color>"
L40_1[1] = L41_1
L40_1[2] = L42_1
