L42_1 = {}
L43_1 = "SI_PF_TUTORIAL_TEXUTRE_FIERCE_03_DESC_02"
L44_1 = "Phần thưởng chưa được nhận bị hủy kích hoạt khi bạn đặt lại các tiểu đội. <COLOR=#FFBC00>Các phần thưởng, sau khi được nhận, không thể dược nhận lại sau khi đặt lại.</COLOR> "
L42_1[1] = L43_1
L42_1[2] = L44_1
