L35_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_ZODIAC_YANG_HANSOL"
L36_1 = "Hiệp sĩ của Bạch Dương. Yang Hansol là một lính tấn công,\nngười đẩy lùi kẻ thù bằng hào quang kiếm.\nGần đây, anh ta đã thức tỉnh sức mạnh của mình và gia nhập\nHiệp sĩ Hoàng Đạo với tư cách là một hộ vệ. Không chắc chắn về khả năng của mình,\nanh vung kiếm tre của mình 10.000 lần mỗi ngày\nvới hy vọng một ngày nào đó anh sẽ trở thành một hiệp sĩ thực sự.\nTuy nhiên, bài kiểm tra đã\nxác nhận rằng sức mạnh tiềm tàng của anh ấy vượt xa những Counter trung bình.\nAnh ấy là người duy nhất không biết điều đó.\nĐiều anh ấy thực sự cần là thời gian chứ không phải tập luyện.\nNhưng các hiệp sĩ khác đều đồng ý giữ im lặng cho đến khi anh ấy tự hiểu ra mọi việc,\nvì họ không muốn cản trở\nsự nhiệt tình của anh ấy trong việc cải thiện bản thân."
L34_1[1] = L35_1
L34_1[2] = L36_1
L35_1 = {}
