L19_1 = "SI_DESC_UNIT_LIMITBREAK_1079"
L20_1 = "Cảm ơn bạn đã hiểu những khó khăn khi làm việc trong lĩnh vực này. Chúng tôi sẽ không để lãng phí dù chỉ một con vít."
