L20_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_ORCA"
L21_1 = "Orca là một người tiên phong tiếp tục cuộc chiến của cô ấy bằng cách chữa lành vết thương cho những kẻ thù bị đánh bại. \n\nOrca thực sự là chỉ chiếc Đồng hồ màu đỏ tỏa sáng một cách kỳ lạ. Theo tin đồn, Counter giành được Orca buộc phải đi lang thang trong Khu vực bị ăn mòn và săn lùng Vật Thể Ăn Mòn cho đến khi chúng chết. Một số người nói rằng lòng căm thù của những người chủ trước đã truyền vào Orca, buộc chủ sở hữu mới bị ám ảnh bởi việc đi săn bắn. \n\nBáo cáo về những người chứng kiến chủ sở hữu Orca chưa bao giờ ngừng kể từ khi Cục Quản Lý được thành lập. Đáng ngạc nhiên là chủ sở hữu gần đây nhất không giống như các trường hợp trước lại có thể kiểm soát một phần ham muốn đi săn.\n "
L19_1[1] = L20_1
L19_1[2] = L21_1
L20_1 = {}
L21_1 = "SI_ITEM_MISC_DESC_IMI_ITEM_MISC_BG_STREGA_CAFE"
