L44_1 = "SI_EPISODE_EPISODE_DESC_NKM_WARFARE_EVENT_ESPR_2_8"
L45_1 = "Chuyện xảy ra khi tôi còn nhỏ. Khi tôi ở một mình trong trang viên, tôi thường nghe thấy một giọng nói êm ái nói chuyện với tôi từ đâu đó giữa những cuốn sách trong phòng làm việc. Nó thì thầm với tôi về lời cầu khấn nhuộm đỏ mặt trăng và cách thách thức cái chết. Tôi muốn biết giọng nói này là của ai.\nĐó là khi tôi còn nhỏ."
L43_1[1] = L44_1
L43_1[2] = L45_1
L44_1 = {}
L45_1 = "SI_SKIN_DESC_NKM_UNIT_S_YG_SORIM_X_MAS"
L46_1 = "Hãy cảnh giác với con sói cô đơn lang thang trên cánh đồng tuyết trắng.\nNhìn vào mắt nó, bạn sẽ chẳng thấy gì ngoài hố đen thăm thẳm lạnh lẽo...\nĐó là điều là cô ấy yêu cầu tôi viết.\nTôi đã cố gắng khuyên cô ấy rằng màu đỏ quá nổi bật trên nền tuyết\n\n<color=#ffd34c>Kỹ năng ngụy trang của tôi là hoàn hảo. Làm sao tôi có thể bị phát hiện dễ dàng mỗi khi chơi trốn tìm được.</color>"
L44_1[1] = L45_1
L44_1[2] = L46_1
L45_1 = {}
L46_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_POLICE_2_1"
L47_1 = "Nước Thánh luôn được tôn vinh.\nKhông có tin đồn nào về nó cho biết điều gì xảy ra sau khi bạn uống nó."
L45_1[1] = L46_1
L45_1[2] = L47_1
L46_1 = {}
L47_1 = "SI_PF_TUTORIAL_TEXUTRE_OPERATION_SIDE_STORY_1_DESC"
L48_1 = "Bao gồm câu chuyện về các nhân vật cụ thể, tác chiến [Chuyện Bên Lề] chủ yếu là <COLOR=#FFBC00>Trận Chiến Sự Kiện</COLOR>."
