L10_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_DAILY_DEFENCE_2"
L11_1 = "Đây là thông báo từ Trợ Lý Lee Yoonjung.\nGiáo Sư Olivie rất hài lòng với dữ liệu thu thập được đến nỗi bà đã quyết định tăng độ nghiêm trọng của khủng hoảng. Những người tham gia chương trình này sẽ nhận được thêm phần thưởng. Xin chân thành cảm ơn sự tham gia của các bạn.\n\n<color=#FFCF3B>Hãy bảo vệ tàu của bạn trước đội quân địch loại Bao Vây. Nên sử dụng đơn vị Tháp hoặc đơn vị tấn công có Đẩy Lùi.</color>"
L9_1[1] = L10_1
L9_1[2] = L11_1
L10_1 = {}
L11_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_DAILY_DEFENCE_3"
L12_1 = "Đây là thông báo từ Trợ Lý Lee Yoonjung.\nCăn cứ theo dữ liệu thu được từ buổi huấn luyện trước, chúng tôi đã phát triển chương trình mô phỏng tác chiến phức tạp hơn. Những người tham gia chương trình này sẽ nhận được nhiều phần quà khác nhau. Xin chân thành cảm ơn sự tham gia của các bạn.\n\n<color=#FFCF3B>Hãy bảo vệ tàu của bạn trước đội quân địch loại Bao Vây. Nên sử dụng đơn vị Tháp hoặc đơn vị tấn công có Đẩy Lùi.</color>"
L10_1[1] = L11_1
L10_1[2] = L12_1
L11_1 = {}
L12_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_DAILY_DEFENCE_4"
L13_1 = "Đây là thông báo từ Trợ Lý Lee Yoonjung.\nĐộ khó của chương trình mô phỏng tác chiến đã được tăng lên nhiều lần theo yêu cầu của Giáo Sư Olivie. Ngoài ra, nhiều phần quà mới đã được bổ sung thay lời tri ân của Lab. Xin chân thành cảm ơn sự tham gia của các bạn.\n\n<color=#FFCF3B>Hãy bảo vệ tàu của bạn trước đội quân địch loại Bao Vây. Nên sử dụng đơn vị Tháp hoặc đơn vị tấn công có Đẩy Lùi.</color>"
L11_1[1] = L12_1
L11_1[2] = L13_1
