L40_1 = {}
L41_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_FREEDOM_LEE_MINSEO"
L42_1 = "Lee Minseo là lính hỗ trợ cản trở\nsự di chuyển của kẻ địch bằng các đòn tấn công tầm xa.\nCô ấy bị cuốn vào một vụ Ăn Mòn\nkhi phớt lờ những lời cảnh báo, cố gắng\nlập kỷ lục mới trong trò chơi , nhưng cô ấy\nđã sống sót một cách thần kỳ nhờ trở thành Counter.\nVấn đề là cô ấy chỉ sử dụng sức mạnh của mình\nđể cosplay. Là một người hâm mộ cuồng nhiệt của\nseries Necronomiko, một trò chơi cổ điển, Minseo\nluôn mặc trang phục của nhân vật chính trong trò chơi đó. Nhưng không giống như Necronomiko,\nngười chiến đấu dũng cảm chống lại quái vật,\ncô ấy thậm chí sợ phải chiến đấu với Vật Thể Ăn Mòn Cấp 1,\nđiều này ngăn cản cô ấy trở thành lính đánh thuê."
L40_1[1] = L41_1
L40_1[2] = L42_1
L41_1 = {}
L42_1 = "SI_DESC_NEGO_GREATSUCCESS_1011"
L43_1 = "Từ lúc sinh ra tôi đã muốn làm chiến binh cả đời."
