L41_1[2] = L43_1
L42_1 = {}
L43_1 = "SI_SKIN_DESC_NKM_UNIT_C_SCHOOL_PRESIDENT_SUMMER"
L44_1 = "Tôi đang dạy bọn trẻ cách chiến đấu dưới nước,\ntrong trường hợp chúng gặp V.T.B.A.M khi ở ngoài biển.\nCho đến nay, bọn trẻ đã theo kịp tôi rất tốt\nngoại trừ khi chúng tôi tập chạy trên mặt nước.\n\n<color=#ffd34c>Hãy sửa lại tư thế của ngài. Chỉ cần thư giãn và để tôi chăm sóc cho ngài nhé.</color>"
