L16_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_M_ADMIN_MACHINEGUN"
L17_1 = "Đội tiên phong phát triển mạnh hơn khi bắn mà không cần di chuyển. Chúng là các đơn vị thiết giáp của Cục Quản Lý Cũ, được sử dụng để xuyên thủng phòng tuyến của kẻ thù.\n\nHỏa lực liên tục của họ có thể hạ gục cả Vật Thể Ăn Mòn.\n\nCần phải vận hành một cách thận trọng, vì đồ dự phòng của chúng sắp hết."
L15_1[1] = L16_1
L15_1[2] = L17_1
L16_1 = {}
L17_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_M_SL_AIR_FIGHTER"
L18_1 = "Một lính tấn công tầm xa,\nhỗ trợ hỏa lực từ trên không.\nChúng là những máy bay chiến đấu drone,\nsử dụng một khẩu súng máy nhỏ từ độ cao thấp.\nLà sản phẩm của Dự án Chiến Tranh Tương Lai,\nchúng được các binh sĩ yêu thích vì cấu trúc đơn giản,\nbảo trì dễ dàng. Được phát hành\ntheo giấy phép nguồn mở, chúng vẫn được\nsản xuất trên khắp thế giới.\nChúng được trang bị AI được mô hình hóa\ntheo một con chim sẻ. Có tin đồn rằng\nchúng có thể được huấn luyện như thú cưng theo thời gian,\nnhưng chúng thường bị bắn hạ trước đó,\nnên sự thật vẫn chưa được hé lộ."
L16_1[1] = L17_1
L16_1[2] = L18_1
L17_1 = {}
L18_1 = "SI_FP_CONTRACT_BANNER_PICKUP_FUTURE_HARPY_DESC"
L19_1 = "Một chiếc máy bay chiến đấu biến hình thực hiện các đòn tấn công Tầm Xa Trên Không cho đến khi bị nhận một lượng sát thương nhất định, và sau đó trở thành người bảo vệ tiền tuyến trên mặt đất."
