L16_1 = "SI_BOSS_DESC_01"
L17_1 = "Một vũ khí khổng lồ không rõ nguồn gốc đến từ bên ngoài không gian của chúng ta. Nó chuyên dùng để nghiền nát kẻ thù đang đến gần và cũng có khả năng thực hiện các cú nhảy không gian không được hỗ trợ nhờ hệ thống động cơ tương tự như chiến hạm đa chiều.\n\nBan đầu nó có thể được lập trình để di chuyển đến và đi khỏi Counterside để săn V.T.B.A.M, nhưng khi bị phát hiện, nó đã mất kiểm soát, bị hư hỏng đến mức không thể sửa chữa do Tia Ăn Mòn.\n\n<color=#FFCF3B> ※ Quản Trị Viên nhận thêm sát thương khi bị tấn công ở phía sau, nơi dễ bị tổn thương.</color>"
L15_1[1] = L16_1
L15_1[2] = L17_1
L16_1 = {}
L17_1 = "SI_BOSS_DESC_02"
L18_1 = "Một vũ khí khổng lồ không rõ nguồn gốc đến từ bên ngoài không gian của chúng ta. Nó chuyên dùng để đánh bại kẻ thù ở khoảng cách xa và cũng có khả năng thực hiện các cú nhảy không gian không được hỗ trợ nhờ hệ thống động cơ tương tự như chiến hạm đa chiều.\n\nBan đầu nó có thể được lập trình để di chuyển đến và đi khỏi Counterside để săn V.T.B.A.M, nhưng khi bị phát hiện, nó đã mất kiểm soát, bị hư hỏng đến mức không thể sửa chữa do Tia Ăn Mòn.\n\n<color=#FFCF3B> ※ Quản Trị Viên nhận thêm sát thương khi bị tấn công ở phía sau, nơi dễ bị tổn thương. </color>"
