L10_1 = "SI_PF_TUTORIAL_TEXUTRE_UNIT_ENCHANT_1_DESC_02"
L11_1 = "Thực hiện Cường Hoá cho các đơn vị để phát triển Tiềm Năng của họ."
L9_1[1] = L10_1
L9_1[2] = L11_1
L10_1 = {}
L11_1 = "SI_ITEM_MISC_DESC_IMI_ITEM_MISC_EVENT_XMAS_CONTRACT_DOC"
L12_1 = "Lệnh tuyển dụng mới đã được đưa ra để chuẩn bị cho mùa nghỉ lễ Giáng Sinh sắp tới.\nCó tài liệu quản lý cần thiết. Thỏa thuận tuyển dụng là không bắt buộc.\nSẽ bị xóa sau khi Cửa Hàng đóng cửa."
L10_1[1] = L11_1
L10_1[2] = L12_1
