L13_1 = "SI_MISSION_TITLE_GROWTH_010_340"
L14_1 = "Thực hiện Đàm Phán Lương"
L12_1[1] = L13_1
L12_1[2] = L14_1
L13_1 = {}
L14_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_S_TIDE_SHOTGUN"
L15_1 = "Một đội tiên phong đẩy lùi kẻ thù bằng\ncác cuộc tấn công khu vực để giảm khả năng phòng thủ của chúng.\nKẻ hủy diệt là những đặc vụ được\ntriển khai khi Vật Thể Ăn Mòn xuất hiện.\nBộ giáp Kẻ Hủy Diệt được gia cố gần như\nmột thiết bị hạng nặng cỡ người.\nNhưng việc triển khai chúng bị hạn chế vì\náo giáp đòi hỏi quá trình hàn\ncác mạch trực tiếp đến các dây thần kinh trung ương.\nCác đơn vị này được tuyển chọn thông qua một cuộc kiểm tra nghiêm ngặt,\nchỉ khi các sĩ quan cảnh sát\nbị khuyết tật trong khi thi hành nhiệm vụ,\nsẵn sàng tình nguyện."
L13_1[1] = L14_1
L13_1[2] = L15_1
L14_1 = {}
L15_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_M_ADMIN_TANK"
L16_1 = "Kẻ tấn công có khả năng thực hiện các đòn tấn công AoE, được tăng cường tạm thời khi được triển khai. \n\nHọ là những đơn vị thiết giáp của Cục Quản Lý Cũ dùng để trấn giữ phòng tuyến. Pháo chùm công suất lớn của chúng có thể tiêu diệt Vật Thể Ăn Mòn. Mô-đun laser liên tục được nghiên cứu bởi nhiều quốc gia dưới sự giám sát của Cục Quản Lý."
L14_1[1] = L15_1
