L36_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_ZODIAC_CHARLOTTE"
L37_1 = "Hiệp sĩ của Xử Nữ. Esterosa de Chevalier là một tiên phong chiến đấu trên tiền tuyến trong khi bảo vệ bản thân bằng kết giới.\n\nMặc dù cô ấy không xuất thân từ gia đình hiệp sĩ nhưng cô ấy đã đạt được thành công mà chưa người tiền nhiệm nào có thể: trở thành đội trưởng của Hiệp sĩ Hoàng Đạo. Vì lý do này, cô ấy tiếp tục phải nhận áp lực từ sự phản đối của các trưởng lão.\n\nDo trách nhiệm to lớn mà cô ấy phải gánh vác, cô ấy luôn giữ thái độ nghiêm khắc và nghiêm túc. Nhưng bên trong, cô ấy thực sự rất tốt bụng và dễ mủi lòng. \n\nCô ấy tin rằng mình đang che giấu Con người thật của cô ấy rất ổn, nhưng tất cả những hiệp sĩ đã dành thời gian ở gần cô đều biết rằng cô ấy không thể rời mắt khỏi những con vật dễ thương và cô ấy thường nói mơ khi gặp ác mộng.\n "
L35_1[1] = L36_1
L35_1[2] = L37_1
L36_1 = {}
L37_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EP3_ACT4_EPILOGUE"
L38_1 = "Cảm ơn bạn đã xử lý đối tượng cực kỳ nguy hiểm.\nCòn về phản hồi có mức năng lượng cao mà vệ tinh phát hiện được, các điều tra viên của chúng ta đã kết luận rằng đó chỉ đơn giản là trục trặc máy móc."
L36_1[1] = L37_1
L36_1[2] = L38_1
