L28_1 = "SI_EPISODE_EPISODE_DESC_NKM_WARFARE_EP5_1_4"
L29_1 = "Khi đề cập đến chiến thuật chống Ăn Mòn, không từ ngữ nào nhấn mạnh được hết tầm quan trọng của việc phản ứng kịp thời hết, do hầu hết các vụ việc có thể được xử lý một cách dễ dàng nếu được phản ứng kịp thời, trước khi trở thành các thảm hại nghiêm trọng.\nTiếc thay, sự bất cẩn và tham lam thường khiến mọi việc trở nên tồi tệ hơn."
L27_1[1] = L28_1
