L18_1 = "SI_SHOP_CASH_ITEM_DESC_140003"
L19_1 = "Gói sự kiện ra mắt\ndành cho chủ nhân TASKFORCE."
L17_1[1] = L18_1
L17_1[2] = L19_1
L18_1 = {}
L19_1 = "SI_EPISODE_EPISODE_DESC_NKM_WARFARE_FIELD_EP1_2_4"
L20_1 = "Trích dẫn từ bài viết nổi bật của tờ Task Planet vào ngày 7 tháng Ba\nSau cùng, Daymine không kiếm được Vàng Vĩnh Cửu từ tọa độ không gian đã thu được sau một khoảng thời gian dài.\nThất bại của Daymine đã dạy nhiều bài học cho ngành TASKFORCE hiện đang bùng nổ."
L18_1[1] = L19_1
L18_1[2] = L20_1
L19_1 = {}
L20_1 = "SI_EPISODE_EPISODE_DESC_NKM_WARFARE_FIELD_EP1_2_3"
L21_1 = "Trích dẫn từ bài viết nổi bật của tờ Task Planet vào ngày 7 tháng Ba\nKhi sự hỗ trợ dừng lại, trang thiết bị xuống cấp và mọi người bắt đầu bỏ việc. Hiệu quả công việc giảm mạnh dẫn đến việc ngân sách bị cắt xén nhiều hơn.\nBan lãnh đạo của Daymine vẫn chỉ chăm chăm tìm cách giảm chi phí."
L19_1[1] = L20_1
L19_1[2] = L21_1
L20_1 = {}
L21_1 = "SI_EPISODE_EPISODE_DESC_NKM_WARFARE_FIELD_EP1_2_2"
L22_1 = "Trích dẫn từ bài viết nổi bật của tờ Task Planet vào ngày 7 tháng Ba\nCác công ty TASKFORCE cần hỗ trợ và trang thiết bị thượng hạng.\nTuy nhiên, ban lãnh đạo của Daymine rất keo kiệt trong việc đầu tư, họ cắt giảm ngân sách ở nhiều chỗ, lấy \"tăng cường hiệu quả cao hơn\" làm lý lẽ biện hộ."
L20_1[1] = L21_1
L20_1[2] = L22_1
L21_1 = {}
L22_1 = "SI_EPISODE_EPISODE_DESC_NKM_WARFARE_FIELD_EP1_2_1"
L23_1 = "Trích dẫn từ bài viết nổi bật của tờ Task Planet vào ngày 7 tháng Ba\n... Sau Cuộc Chiến Đại Thanh Lọc, Daymine trở thành một trong những thế lực hàng đầu trong ngành TASKFORCE, tuy nhiên, hiện tại, họ tránh lặn vào Counterside và chỉ nhận các nhiệm vụ hạ gục ở Khu Vực Bị Ăn Mòn."
L21_1[1] = L22_1
L21_1[2] = L23_1
L22_1 = {}
L23_1 = "SI_ITEM_MISC_DESC_IMI_ITEM_MISC_RANDOMBOX_UNIT_SR_101"
L24_1 = "Một cơ hội dành cho các công ty TASKFORCE đang phát triển! Tuyển ngay một Counter Hạng SR."
L22_1[1] = L23_1
L22_1[2] = L24_1
L23_1 = {}
L24_1 = "SI_ITEM_MISC_DESC_IMI_ITEM_MISC_RANDOMBOX_UNIT_SSR_101_V2"
L25_1 = "Cơ hội đặc biệt được trao cho các công ty TASKFORCE đang phát triển!\nTuyển dụng ngay lập tức một Counter Cấp SSR."
L23_1[1] = L24_1
