L26_1 = "Một cơ hội dành cho các công ty TASKFORCE đang phát triển! Tuyển ngay một Counter Hạng SSR."
L24_1[1] = L25_1
L24_1[2] = L26_1
L25_1 = {}
L26_1 = "SI_ITEM_MISC_DESC_IMI_ITEM_MISC_RANDOMBOX_UNIT_SSR_101_FREE"
L27_1 = "Một cơ hội dành cho các công ty TASKFORCE đang phát triển! Tuyển ngay một Counter Hạng SSR."
L25_1[1] = L26_1
L25_1[2] = L27_1
L26_1 = {}
L27_1 = "SI_EPISODE_EPISODE_DESC_NKM_WARFARE_FIELD_EP1_3_2"
L28_1 = "Các công ty TASKFORCE, một loại hình công ty quân sự tư nhân,\nđược quyền nhận tất cả các yêu cầu mà các PMC khác không được.\nHọ chỉ đơn giản là đáp ứng nhu cầu cao hơn liên quan đến Counterside."
L26_1[1] = L27_1
L26_1[2] = L28_1
L27_1 = {}
L28_1 = "SI_EPISODE_EPISODE_DESC_NKM_WARFARE_FIELD_EP1_1_4"
L29_1 = "Một công ty TASKFORCE đã tiến vào trung tâm thành phố. Theo Sĩ Quan Tác Chiến, đây là công ty tai tiếng trong ngành.\nTôi không quan tâm miễn là họ diệt sạch được lũ quái vật trong thành phố của chúng ta."
L27_1[1] = L28_1
