L29_1 = "SI_SKIN_DESC_NKM_UNIT_C_DELTA_KYLE_SPRING"
L30_1 = "Thư viện trường lúc nào cũng chật kín, kể cả khi nghỉ hè.\nĐặc biệt là những cô gái tìm tiểu thuyết lãng mạn.\nTuy vậy, mọi người lại đang nhìn ra cửa sổ thay vì vào sách.\nDù cậu bé không có vẻ gì là thấy phiền.\n\n<color=#ffd34c>Trả sách trễ nhé. Cho một điểm trừ.</color>"
L28_1[1] = L29_1
L28_1[2] = L30_1
