L13_1 = "SI_EPISODE_EPISODE_DESC_NKM_WARFARE_EP1_3_1"
L14_1 = "Đây là câu chuyện ngụ ngôn được kể ở một quốc gia bé nhỏ nào đó.\n\n.Nếu thấy một cái bóng hình người ở bất kỳ nơi đâu mà xung quanh không có bóng người thì hãy bỏ chạy ngay lập tức.\nĐó là cái bóng của người đã chết không được siêu thoát.\nCái bóng sẽ lơ lửng xung quanh khi bị bỏ lại, tìm người khác để tiếp tục hành trình dài với người đó."
L12_1[1] = L13_1
L12_1[2] = L14_1
