L24_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_FOOLSDAY_1_1_HM"
L25_1 = "Nghĩa đen của nó là người làm việc vào ban đêm.\nKhi rắc rối này qua đi, họ sẽ có thể quay về nhà với gia đình mình chứ?"
L23_1[1] = L24_1
L23_1[2] = L25_1
L24_1 = {}
L25_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_FOOLSDAY_1_2"
L26_1 = "Hầu hết các loại đồ uống ở văn phòng đều được quảng cáo là có thành phần giúp tái tạo năng lượng.\nNhưng chúng thường không làm được điều đó."
L24_1[1] = L25_1
L24_1[2] = L26_1
L25_1 = {}
L26_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_FOOLSDAY_1_2_HM"
L27_1 = "Nó chân thật đến mức đáng sợ."
L25_1[1] = L26_1
L25_1[2] = L27_1
L26_1 = {}
L27_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_FOOLSDAY_1_3"
L28_1 = "Mỗi trò chơi đều có nhân vật được yêu thích nhất.\nVà những người hâm mộ bày tỏ sự yêu thích của họ theo nhiều cách khác nhau."
L26_1[1] = L27_1
L26_1[2] = L28_1
L27_1 = {}
L28_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_FOOLSDAY_1_4"
L29_1 = "Những vĩ nhân đều điên cuồng theo cách này hay cách khác."
L27_1[1] = L28_1
L27_1[2] = L29_1
L28_1 = {}
L29_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_FOOLSDAY_1_5"
L30_1 = "Nếu muốn có nhiều nhân viên hơn, bạn phải mở rộng văn phòng.\nHoặc bạn có thể thử trở thành một trong số các nhân viên, thật đấy."
L28_1[1] = L29_1
L28_1[2] = L30_1
L29_1 = {}
L30_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_FOOLSDAY_1_6"
L31_1 = "Sau trận chiến, một người đàn ông hỏi:\n\"Điều gì xảy ra khi kịch bản kết thúc?\""
L29_1[1] = L30_1
L29_1[2] = L31_1
