L2_1 = "SI_ITEM_DESC_IQI_EQUIP_COUNTER_WEAPON_681141"
L3_1 = "Kim đồng hồ mang tinh thần Counter cao quý.\nCho mượn sức mạnh để đánh bại kẻ thù một cách công bằng và chính trực. "
