L22_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_CHALLENGE_ACT2_3_1"
L23_1 = "Rất nhiều tiền của và thời gian đã được sử dụng để xây nhà máy năng lượng này, Lincoln MK2.\n\n<color=#ffd34c>※ [Lincoln MK2]: Bắn đạn đại bác xuyên qua tất cả mục tiêu Mặt Đất.</color>"
