L38_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_SHADE_1_1"
L39_1 = "Tăng tửu lượng là một trong những tác dụng phụ của việc trở thành Counter.\nRita đặc biệt không thích điều đó."
L37_1[1] = L38_1
L37_1[2] = L39_1
L38_1 = {}
L39_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_SHADE_1_1_CM"
L40_1 = "Họ đã bị đánh bại trong tích tắc.\n\n<color=#ff3636>※ Bỏ qua Spira, kẻ đã chặn bước tiến của bạn và tấn công Ministra.</color>"
L38_1[1] = L39_1
L38_1[2] = L40_1
L39_1 = {}
L40_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_SHADE_1_1_HM"
L41_1 = "Cán cân quyền lực trong thế giới ngầm có thể bị nghiêng về một bên bất cứ lúc nào.\nVà Hội Đồng luôn là bên giúp khôi phục cán cân quyền lực đó."
L39_1[1] = L40_1
L39_1[2] = L41_1
L40_1 = {}
L41_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_SHADE_1_2"
L42_1 = "Trong Chiến Tranh, V.T.B.A.M bay là những kẻ địch khó nhằn.\nCơ thể mảnh và dài của chúng khiến chúng bay rất nhanh giống như những viên đạn xuyên giáp, xuyên thủng cả những mô hình tàu chiến mới nhất như thể chúng được làm bằng giấy vậy."
L40_1[1] = L41_1
L40_1[2] = L42_1
L41_1 = {}
L42_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_SHADE_1_3"
L43_1 = "<Những thiết bị lặn thiết yếu của HRT Berry>\n1. Bộ công cụ sơ cứu\n2. Khiên Vàng Vĩnh Cửu được sạc đầy\n3. Nhiều đạn\n4. Phương thức di chuyển khoảng cách xa"
L41_1[1] = L42_1
L41_1[2] = L43_1
L42_1 = {}
L43_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_SHADE_1_4"
L44_1 = "Một số người theo đuổi ước mơ của mình một cách mù quáng và đầy quyết tâm.\nMột số người khác đang đấu tranh để tồn tại với thực tại nhìn họ từ phía sau với vẻ mặt lo lắng. "
L42_1[1] = L43_1
L42_1[2] = L44_1
L43_1 = {}
L44_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_SHADE_1_INTERLUDE_1"
L45_1 = "Horizon Finance.\nDịch vụ đáng tin. Các khoản vay siêu nhanh chóng với mức lãi suất không tưởng."
L43_1[1] = L44_1
L43_1[2] = L45_1
L44_1 = {}
L45_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_SHADE_1_INTERLUDE_2"
L46_1 = "Ground One nghiêm cấm việc đổ bộ bừa bãi trong thành phố.\nTất cả các công ty TASKFORCE đều phải tìm các tín hiệu hướng dẫn của các bến tàu trước khi trở lại thực tế."
L44_1[1] = L45_1
L44_1[2] = L46_1
L45_1 = {}
L46_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_SHADE_2_1"
L47_1 = "Các V.T.B.A.M loại Ác Quỷ, cũng được gọi là Cái Bóng, bị thu hút bởi những mùi hương ở Normalside.\nMột số nhà nghiên cứu khẳng định hành vi của chúng giống như của các loài quỷ dữ trong thần thoại và văn hóa dân gian của chúng ta."
L45_1[1] = L46_1
L45_1[2] = L47_1
L46_1 = {}
L47_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_SHADE_2_1_HM"
L48_1 = "Nền văn minh này có nhiều điểm tương đồng với chúng ta.\nChứng minh điều đó là nhiệm vụ đầu tiên được giao cho tôi."
L46_1[1] = L47_1
L46_1[2] = L48_1
L47_1 = {}
L48_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_SHADE_2_2"
L49_1 = "Cục Quản Lý đặc biệt thận trọng đối với những Cái Bóng, không chỉ vì sự nguy hiểm mà chúng mang lại. Vì dụ: hiện tại họ vẫn chưa rõ ràng quan điểm của mình về việc có nên đối xử bình đẳng với Cái Bóng như Counter ban đầu không."
L47_1[1] = L48_1
L47_1[2] = L49_1
L48_1 = {}
L49_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_SHADE_2_3"
L50_1 = "Rất nhiều thế giới đã sụp đổ.\nHọ đã hy sinh mọi thứ họ có, ngay cả những thứ họ không nên hy sinh, để nhận được câu trả lời mà họ muốn."
L48_1[1] = L49_1
L48_1[2] = L50_1
L49_1 = {}
L50_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_SHADE_2_4"
L51_1 = "Bạo Chúa là V.T.B.A.M Loại 3 có phần nhô ra hình người trên đỉnh đầu khổng lồ. Chuyển động của nó rất linh hoạt, tùy theo giáp cơ thể, và nỗ lực đáp trả các đòn tấn công đa dạng của nó đã giúp chiến lược TASKFORCE vươn đến tầm cao mới."
L49_1[1] = L50_1
L49_1[2] = L51_1
L50_1 = {}
