L2_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_SHADE_3_3"
L3_1 = "Các kỹ năng săn tìm xuất sắc là bản năng của các nhân viên, cho dù họ đến từ nền văn hóa nào."
