L3_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_SHADE_3_4"
L4_1 = "Các triệu chứng ban đầu của Hội Chứng Ăn Mòn gây khó khăn trong việc chẩn đoán mức độ bệnh.\nBệnh nhân bắt đầu nhầm lẫn giữa thực tế với ảo tưởng, nghi ngờ mọi tác nhân kích thích gây ra với họ."
