L2_1[2] = L4_1
L3_1 = {}
L4_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_SHADE_3_INTERLUDE_3"
L5_1 = "Không có gì khiến một câu chuyện trở nên hấp dẫn hơn ngoài rượu ngon, vì nó là một chất lỏng kỳ diệu khiến bạn cảm thấy như bạn đang thực sự trải qua những sự kiện trong câu chuyện đó."
L3_1[1] = L4_1
L3_1[2] = L5_1
L4_1 = {}
L5_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_SHADE_4_1"
L6_1 = "Không phải tất cả mọi người đều tin tưởng thông báo của Cục Quản Lý.\nMột vài người đã thử liều lĩnh, và dấu vết của họ đã bị phát hiện tức thì."
L4_1[1] = L5_1
L4_1[2] = L6_1
L5_1 = {}
L6_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_SHADE_4_1_HM"
L7_1 = "Không giống như loại Quái Vật thích phá hủy bừa bãi, loại Bạo Chúa có đủ trí khôn để chơi đùa với con mồi của mình.\nĐây không phải là một tin đáng mừng với hàng tiền tuyến."
L5_1[1] = L6_1
L5_1[2] = L7_1
L6_1 = {}
L7_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_SHADE_4_2_HM"
L8_1 = "Với Cái Bóng, một khoảnh khắc là vĩnh cửu và sự vĩnh cửu chỉ là một khoảnh khắc.\nĐó là vì chúng đều là những cái bóng lang thang trong nỗi ám ảnh không thể xóa bỏ."
