L14_1 = "SI_PF_TUTORIAL_TEXUTRE_RACE_INFORMATION_1_DESC_01"
L15_1 = "Chọn một trong hai đường để tiếp tục cuộc đua.\nBạn có thể bị cản trở hoặc được hỗ trợ bởi những chướng ngại vật mà bạn gặp phải trong cuộc đua.\nBạn nhận được 3 điểm đồng đội nếu thắng và 1 điểm nếu thua.\nHãy cổ vũ để đội của bạn giành chiến thắng! "
L13_1[1] = L14_1
L13_1[2] = L15_1
L14_1 = {}
L15_1 = "SI_PF_TUTORIAL_TEXUTRE_RACE_RUNNING_1_DESC_01"
L16_1 = "Chọn một trong hai đội để tham gia cuộc đua.\nBạn có thể tham gia cuộc đua bằng cách sử dụng các vật phẩm thu được khi hoàn thành nhiệm vụ.\nBạn có thể tham gia cuộc đua tối đa 3 lần mỗi ngày.\nSố lượt tham gia và đội được chọn được đặt lại mỗi ngày lúc 4:00 sáng\nBạn có thể nhận được phần thưởng và điểm đồng đội dựa trên kết quả cuộc đua.\nĐến 4:00 sáng hàng ngày, đội có nhiều điểm đồng đội hơn sẽ tham gia cuộc đua và nhận phần thưởng. "
