L17_1 = {}
L18_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_SCHOOL_C_PENCIL"
L19_1 = "Mika★Star là một Lính Hỗ Trợ sử dụng những trò ảo thuật kỳ diệu để quấy rối và làm suy yếu kẻ thù.\n\n   Với khát vọng trở thành pháp sư vĩ đại nhất thế kỷ, cô ấy đại diện cho những Counter của Học Viện ủng hộ chủ nghĩa phi chiến tranh. Cô khẳng định rằng ước mơ của mọi người phải được tôn trọng, và không phải tất cả các Counter đều cần tập trung vào kỹ năng chiến đấu thể chất. Đây hẳn là lý do tại sao Chủ Tịch Học Sinh, người tin tưởng vào sự hòa hợp, đã chọn cô ấy vào Hội Đồng Học Sinh.\n   Và chỉ vì cô ấy tin vào chủ nghĩa phi chiến tranh, điều đó không có nghĩa là cô ấy yếu đuối. Phép thuật của cô ấy, thứ mà cô ấy đã được luyện tập cẩn thận để thể hiện những màn ảo thuật táo bạo, thú vị, hoàn toàn có khả năng giết người khi ở ngoài sân khấu."
L17_1[1] = L18_1
L17_1[2] = L19_1
