L2_1 = {}
L3_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_GUILTY_S_MAY"
L4_1 = "May là Lính Hỗ Trợ có thể tối đa hóa tỷ lệ sống sót của các đồng minh xung quanh thông qua HP và khả năng hỗ trợ của cô ấy. Một đứa trẻ mồ côi trong chiến tranh và Cướp Biển Sứa. Vẻ ngoài nhỏ nhắn, xinh xắn khiến người khác không thể ngờ đến sức mạnh siêu phàm của cô ấy, thứ sức mạnh có thể khiến cô ấy ném cả một cái mỏ neo dễ dàng. Cô ấy cũng có thể triệu hồi các sinh vật biển. Tin tưởng vào nguyên tắc hành động trước và suy nghĩ sau, cô ấy thường lôi kéo những Cướp Biển Sứa khác tham gia các hành vi bốc đồng của mình. Trong Trang Bị Tội Ác -Strive-, sau khi phần mềm mô phỏng được thiết kế, cô ấy trở nên trưởng thành hơn so với những công việc trước đây. Điều đó khiến người hâm mộ của cô ấy ngạc nhiên. "
L2_1[1] = L3_1
L2_1[2] = L4_1
L3_1 = {}
L4_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_GUILTY_S_MILLIA"
L5_1 = "Millia Rage là một Lính Cơ Động có khả năng tấn công liên tục, đặc biệt hiệu quả khi chống lại các Lính Phòng Vệ với khả năng hạn chế sát thương. Cô cũng tạo ra sóng xung kích, đẩy lùi kẻ thù ở gần. Từng là thành viên của Hội Sát Thủ, cô ấy hiện đang lãnh đạo cơ quan tình báo lớn nhất thế giới. Tóc của cô ấy, nhờ thấm nhuần phép thuật bị cấm, 「Angra」, có thể tạo thành các hình dạng và độ rắn khác nhau. Cô ấy trầm lặng và lạnh lùng, nhưng không phải lúc nào cô ấy cũng đưa ra quyết định dựa trên chi phí và lợi ích. Những hành động tử tế ngẫu nhiên mà cô ấy đôi khi thể hiện là lý do tại sao cô ấy được giới thiệu là hướng dẫn huấn luyện trong phiên bản mô phỏng. "
L3_1[1] = L4_1
L3_1[2] = L5_1
L4_1 = {}
L5_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_GUILTY_C_SOL"
L6_1 = "Sol Badguy là Lính Phòng Vệ có thể cường hóa bản thân và tạm thời vô hiệu hóa kẻ địch xung quanh, tùy thuộc vào số lượng đòn tấn công mà anh ta tung ra. \n\nAnh ta tự xưng là một thợ săn tiền thưởng, nhưng mục tiêu chính của anh ta là Trang Bị, vũ khí sinh học nằm rải rác khắp nơi trên thế giới. Anh ta chiến đấu và tiêu diệt kẻ thù bằng vũ lực thay vì kỹ thuật do bản thân anh ta cũng chính là một Trang Bị. Phiên bản mô phỏng này của anh ấy có vẻ thô kệch và xa cách giống như bản gốc của anh ấy. Tuy nhiên, trong con người anh ấy vẫn có một khía cạnh nhân văn nào đó đã được hình thành sau khi anh ấy đã trải qua nhiều sóng gió.  "
L4_1[1] = L5_1
L4_1[2] = L6_1
