L38_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_GUILTY_C_RAMLETHAL"
L39_1 = "Ramlethal Valentine là một Lính Tấn Công chuyên tấn công combo tầm gần cực mạnh. Cô ấy là một trong những dạng sống giống con người được gọi là Valentines và được giao nhiệm vụ tiêu diệt loài người. Cô ấy đã từng thực hiện mệnh lệnh của mình một cách máy móc trước khi cô ấy gặp con người và biết được cảm giác có cảm xúc là như thế nào. Cô ấy đã đứng về phía nhân loại kể từ đó. Ramlethal, người có thế giới quan hồn nhiên như một đứa trẻ, sẽ hòa nhập ngay với những nhân viên vụng về trong xã hội. "
L37_1[1] = L38_1
L37_1[2] = L39_1
L38_1 = {}
L39_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_GUILTY_M_INO"
L40_1 = "I-NO là một Lính Bắn Tỉa tấn công AoE từ xa. Cô ấy có thể thổi bay kẻ thù đang tới để bảo vệ bản thân và có khả năng chống lại các đơn vị bay một cách mạnh mẽ.\nCó vẻ thân thiện, hướng ngoại và ham học hỏi, nhưng cô ấy thực sự là một người cô độc, coi thường những người khác và công khai thù địch với những người mà cô ấy cảm thấy bị đe dọa. Mặc dù cô ấy nằm trong danh sách mô phỏng, nhưng cô ấy không phải là một lựa chọn lý tưởng để chơi theo đội vì sở thích thao túng và hành hạ người khác. Danh tính thực sự của cô là Magical Foci, một dạng sống giả được tạo ra từ mong muốn của con người về một ngày mai tươi sáng hơn trong các cuộc Thập Tự Chinh. Mặt này của cô ấy đã được phản ánh trong Counter/Lính Thiết Giáp mô phỏng. "
L38_1[1] = L39_1
L38_1[2] = L40_1
