L9_1 = "SI_PF_TUTORIAL_TEXUTRE_PVP_LEAGUE_1_DESC"
L10_1 = "Cuộc Chiến Liên Đoàn được mở khóa với <COLOR=#FFBC00>3000 Điểm Cuộc Chiến Xếp Hạng</COLOR>.\nHạng và cấp của nó được chia từ các Cuộc Chiến Xếp Hạng và Chiến Lược."
