L17_1[2] = L19_1
L18_1 = {}
L19_1 = "SI_SKIN_DESC_NKM_UNIT_MAID_S_LEADER_WEDDING"
L20_1 = "Ai cũng có sự ghen tị.\nHãy sử dụng điều đó và tổ chức đám cưới hạnh phúc nhất thế giới, bạn thấy sao?\nTất nhiên là để dụ kẻ thù của chúng ta.\nTôi thề rằng tôi không có cảm tình đặc biệt nào với chủ nhân của mình.\n\n<color=#ffd34c>Hãy trợ giúp để tôi hành động như một cô dâu hạnh phúc nhất thế giới, thưa Chủ Nhân.</color> "
L18_1[1] = L19_1
L18_1[2] = L20_1
L19_1 = {}
L20_1 = "SI_SKIN_DESC_NKM_UNIT_C_FALLEN_ROSARIA_WEDDING"
L21_1 = "Fallen Hawk đang có động thái gây xôn xao.\nChủ nhân của tổ chức này đã quyết định kết hôn với ai đó...\nmà không hỏi ý kiến của người ta trước!\nNhưng đôi khi, tính đồng bóng thất thường là vỏ bọc để che giấu sự thật.\n\n<color=#ffd34c>Được rồi, hãy tổ chức đám cưới hoành tráng nhất trên thế giới nào.</color> "
L19_1[1] = L20_1
