L24_1 = "SI_SHOP_CASH_ITEM_POPUP_DESC_160365"
L25_1 = "Hình Nền Biển\nBãi Biển Cát\nQuầy Hàng Bãi Biển\nCây Cọ Tươi Tốtx2\nDù Và Bàn\nDù Và Ghế Dài\nĐội Trưởng Barbarossa\nMô Tô Nước\nMáy G.A.P. Nghỉ Mát\nGiỏ Đồ Ăn Nhẹ Và Chăn Dã Ngoại\nMặt Nước Dợn Sóng\nGiá Đỡ Ván Lướt Sóng\nLâu Đài Cát\nThuyền Chuối\nGhế Cứu Hộ\nHọa Tiết Trang Trí Hồng Hạc\nSân Bóng Chuyền Bãi Biển"
L23_1[1] = L24_1
L23_1[2] = L25_1
L24_1 = {}
L25_1 = "SI_SHOP_TAB_NAME_V3_PACKAGE_CONTRACT_VACANCE_21"
L26_1 = "Gói Tuyển Dụng Kỳ Nghỉ 2021"
L24_1[1] = L25_1
L24_1[2] = L26_1
L25_1 = {}
L26_1 = "SI_SHOP_TAB_NAME_V3_PACKAGE_OPERATOR_BASIC"
L27_1 = "Gói Chứng Thực Người Điều Hành"
L25_1[1] = L26_1
L25_1[2] = L27_1
L26_1 = {}
L27_1 = "SI_SKIN_DESC_NKM_UNIT_M_RAS_TOWER_SUMMER"
L28_1 = "Cô bé luôn nói rằng cô bé muốn ra biển. Nhưng mãi chả ai biết cô bé mong muốn ra biển đến thế nào.\nCô bé trông cứ như là động vật lưỡng cư vậy.\n... Cô bé đang nói chuyện với cá heo phải không?\n\n<color=#ffd34c>Bố ơi, những chú cá heo này biết căn cứ của bọn cướp biển đấy! Bố đi kiểm tra đi ạ?</color> "
L26_1[1] = L27_1
L26_1[2] = L28_1
L27_1 = {}
L28_1 = "SI_SKIN_DESC_NKM_UNIT_M_RAS_TOWER_SUMMON_SUMMER"
L29_1 = "Mô tả Mùa Hè Của Bố G.O.D. Máy"
L27_1[1] = L28_1
L27_1[2] = L29_1
L28_1 = {}
L29_1 = "SI_SKIN_DESC_NKM_UNIT_MAID_C_SPEAR_SUMMER"
L30_1 = "Có lẽ trông không giống, nhưng Lycoris sẵn sàng tiếp nhận bất cứ thứ gì, từ đồ ăn cay đến ánh nắng chói chang trên bãi biển!\nChắc là cô ấy thích bất cứ thứ gì kích thích như vậy. Hãy thử khẩu súng nước đá này... \n\n<color=#ffd34c>Ôi, lạnh quá! Làm tóc của tôi rối tung lên hết rồi! Tôi sẽ ném ngài xuống biển đấy! Giỏi thì tới đây!</color> "
L28_1[1] = L29_1
L28_1[2] = L30_1
L29_1 = {}
L30_1 = "SI_SKIN_DESC_NKM_UNIT_MAID_C_TONFA_SUMMER"
L31_1 = "Tôi thề, tôi thực sự mạnh, thưa sếp.\nCác cô  chú của tôi cũng thương tôi vì tôi siêng năng.\nNhưng hóa ra làm ngư dân không chỉ cần thể lực...\nBố nói rằng tôi nên thử thứ gì đó phù hợp với mình hơn... \n\n\n\n<color=#ffd34c>Bố ơi, vậy thì con muốn làm người giúp việc!</color> "
L29_1[1] = L30_1
L29_1[2] = L31_1
