L44_1 = "SI_DESC_UNIT_GET_152"
L45_1 = "Một chiếc cúp trang trí có hình \"Puming,\", linh vật của Laftel, các dịch vụ phát trực tuyến hoạt hình. Được phân phối với số lượng có hạn thông qua sự kiện hợp tác [CounterSide x Laftel]. "
L43_1[1] = L44_1
L43_1[2] = L45_1
L44_1 = {}
L45_1 = "SI_DESC_UNIT_GET_21039"
L46_1 = "Học Viện Prydwen đã chế tạo chiếc tàu tuần dương này với khả năng không chính thức để khám phá Counterside. Nó được trang bị một khiên chắn lực lượng bảo vệ và một vỏ bọc để bảo vệ lực lượng của nó trong quá trình đổ bộ."
L44_1[1] = L45_1
L44_1[2] = L46_1
L45_1 = {}
L46_1 = "SI_DESC_UNIT_GET_21040"
L47_1 = "Con tàu đột kích tiêu chuẩn này là phiên bản cải tiến của con tàu bị phá hủy trong Sự Cố Người Nhân Bản. Được trang bị các kén thả để giải phóng lính bộ binh an toàn và xây dựng những chiến tuyến mới."
L45_1[1] = L46_1
L45_1[2] = L47_1
L46_1 = {}
L47_1 = "SI_DESC_UNIT_GET_21041"
L48_1 = "The Scavengers đã làm việc trên con tàu này trong một thời gian dài, tối ưu hóa nó cho các mục đích trục vớt và cướp bóc tàu. Nó được trang bị một cơ sở tăng cường, nơi các chiến binh nhận được các thủ tục để loại bỏ điểm yếu và cường hóa các bộ phận cơ thể. "
L46_1[1] = L47_1
