L15_1 = "SI_ITEM_MISC_DESC_IMI_ITEM_MISC_RESOURCE_ALT_TOKEN"
L16_1 = "Token ký ức chứa nhiệm vụ bí mật từ Mạng Đen.\nChỉ Tiểu Đội ALT mới biết khóa giải mã để mở khóa nội dung của nó."
