L17_1 = "Token Yêu Cầu Mạng Đen"
L15_1[1] = L16_1
L15_1[2] = L17_1
L16_1 = {}
L17_1 = "SI_EPISODE_DUNGEON_DESC_NKM_DUNGEON_CHALLENGE_ALT_1_1"
L18_1 = "Tránh ra. Ngươi sẽ không muốn bị ta đánh đầu đâu.\nIm đi. Hãy tránh xa ra và nhìn đi. Ta có thể tự kết liễu chúng."
L16_1[1] = L17_1
L16_1[2] = L18_1
L17_1 = {}
L18_1 = "SI_EPISODE_DUNGEON_DESC_NKM_DUNGEON_CHALLENGE_ALT_1_2"
L19_1 = "Súng cối... tên lửa... thậm chí cả máy bay ném bom. Nơi này chứa đầy những thiết bị đáng kinh ngạc.\nCái gì? Tất cả chúng đều là cho tôi sử dụng ư? C-chắc chứ?\n\n<color=#ffd34c> ※ Nữ Thần Hủy Diệt tấn công càng nhanh khi cô ấy chiến đấu càng lâu. </color> "
L17_1[1] = L18_1
L17_1[2] = L19_1
L18_1 = {}
L19_1 = "SI_EPISODE_DUNGEON_DESC_NKM_DUNGEON_CHALLENGE_ALT_1_3"
L20_1 = "... Đây là Seo Yoon. Lin, hãy di chuyển đến điểm bắn tỉa tiếp theo theo kế hoạch.\nEujin, trong khi Lin dời chỗ, hãy dụ các mục tiêu đến các bãi mìn.\nVà Sobin... Hãy tiếp tục phát huy nhé.\n\n<color=#ffd34c> ※ Gỡ mìn của Tiểu Đội ALT đòi hỏi sự hy sinh đẫm máu.</color>"
L18_1[1] = L19_1
L18_1[2] = L20_1
L19_1 = {}
L20_1 = "SI_EPISODE_DUNGEON_DESC_NKM_DUNGEON_CHALLENGE_CREDIT_1_1"
L21_1 = "Linh hồn đã nói chúng ta sẽ tìm thấy vật liệu tốt ở đây.\nHy vọng là thế. Nó sẽ giúp tôi bán những quả cầu pha lê."
L19_1[1] = L20_1
L19_1[2] = L21_1
L20_1 = {}
L21_1 = "SI_EPISODE_DUNGEON_DESC_NKM_DUNGEON_CHALLENGE_CREDIT_1_2"
L22_1 = "Vẫn chưa tìm thấy thứ mình muốn sao?\nVậy hãy lắng nghe lời thì thầm của những ngôi sao. Chúng nói nhiều kho báu giá trị hơn được chôn ở đây."
L20_1[1] = L21_1
L20_1[2] = L22_1
L21_1 = {}
L22_1 = "SI_EPISODE_DUNGEON_DESC_NKM_DUNGEON_CHALLENGE_CREDIT_1_3"
L23_1 = "Một dịch vụ đặc biệt dành cho ông chủ tham lam của tôi.\nOoo, tôi hiểu rồi. Tôi biết nơi chôn cất những vật liệu quý giá nhất ở đây!\n... Tuy nhiên, nó trông hơi nguy hiểm. Chúng ta không thể về nhà được sao?"
L21_1[1] = L22_1
L21_1[2] = L23_1
