L6_1 = "SI_EPISODE_DUNGEON_DESC_NKM_DUNGEON_CHALLENGE_ENCHANT_MODULE_1_1"
L7_1 = "Gần đây chắc ngài đã thực hiện rất nhiều tác chiến. Trang bị chỗ nào cũng hỏng hóc.\nTuy nhiên, không giống như con người, máy móc chỉ cần một chút TLC là có thể sửa lại như mới. Đây, chỉ cần mang cho tôi những vật liệu trong danh sách này. Tôi sẽ lo mọi thứ còn lại."
L5_1[1] = L6_1
L5_1[2] = L7_1
L6_1 = {}
L7_1 = "SI_EPISODE_DUNGEON_DESC_NKM_DUNGEON_CHALLENGE_ENCHANT_MODULE_1_2"
L8_1 = "Nếu muốn, tôi có thể sửa chữa lại thiết bị cho ngài.\nĐể xem nào... Tại sao ngài không nhận công việc này và nhận mô-đun đang cần? Có một chút rủi ro, nhưng thiết bị mà tôi đã bảo dưỡng cho ngài lần trước có thể dùng thử đấy."
L6_1[1] = L7_1
L6_1[2] = L8_1
L7_1 = {}
L8_1 = "SI_EPISODE_DUNGEON_DESC_NKM_DUNGEON_CHALLENGE_ENCHANT_MODULE_1_3"
L9_1 = "Tôi có một số thông tin tốt từ trường mà tôi đã tốt nghiệp.\nHọ cung cấp một mô-đun miễn phí tương thích với máy móc chính xác cho các công ty TASKFORCE tham gia dự án nghiên cứu chiến lược của mình với tư cách là lực lượng đối lập. Chúng tôi có thể sử dụng nó để cải tiến thiết bị đặc biệt mà chúng tôi đã chất đống trong nhà kho. Hứng thú chứ?"
