L49_1 = "SI_SKIN_DESC_NKM_UNIT_C_ZODIAC_ARIUS_ALWAYS"
L50_1 = "Đối với những cô gái xinh xắn như tôi, gió đêm thì quá lạnh và nước suối thì quá nóng, nhưng chúng không thể ngăn tôi đỏ mặt vì phấn khích.\nTôi hứa là tôi sẽ không bao giờ quên kỳ nghỉ mà tôi đã trải qua với ngài ở đây hôm nay.\n\n<color=#ffd34c>\"Nhưng... bầu trời đêm rồi cả những bông hoa thật đẹp quá đi mất. Tôi rất muốn kể với người khác.\"</color>"
L48_1[1] = L49_1
L48_1[2] = L50_1
L49_1 = {}
L50_1 = "SI_SKIN_DESC_NKM_UNIT_C_ZODIAC_PIONE_ALWAYS"
L51_1 = "Đội phó nghiêm khắc với tất cả mọi người, kể cả với chính cô ấy.\nTôi thề rằng bạn sẽ không có nhiều cơ hội được trông thấy cô ấy thư thái như vậy.\nVì vậy, hãy hứa với tôi rằng hai người sẽ giữ bí mật về chuyến đi chơi nhỏ này.\n\n<color=#ffd34c>\"Chúng tôi không đến đây để chơi, Dame Arius. Chúng tôi đến đây chỉ để tỏ ra lịch sự.\"</color>"
