L35_1[2] = L37_1
L36_1 = {}
L37_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_BD_ELIZABETH_RA"
L38_1 = "Con gái của một gia đình quý tộc kiêu hãnh. Mọi thứ khác về Elizabeth đều không được công khai. Nhưng vì cô ấy cũng là Thủ Lĩnh của Prydwen, nên mọi người đã nhất trí rằng cô ấy không chỉ là một bông hoa trong phòng ấm. \n Những người nhìn thấy những thanh kiếm của cô ấy trút xuống từ trên trời đều nghĩ rằng đó là thiên thần  với đôi cánh thép vươn ra hai bên đã giáng xuống thịnh nộ. Đôi cánh trên lưng cô đơn giản được cho là dấu vết của CRF, chỉ xuất hiện khi cô sử dụng sức mạnh thực sự của mình, nhưng sự thật vẫn chưa được sáng tỏ."
L36_1[1] = L37_1
L36_1[2] = L38_1
L37_1 = {}
L38_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_STREGA_LAURA_RA"
L39_1 = "Đã đến lúc phù thủy thức dậy. Khi nắp quan tài của cô ấy mở ra, một đám ma trơi âm thầm gào thét bắt đầu tràn ra. Phù thủy kêu gọi người hầu cận của mình, với đôi tay đang dụi dụi đôi mắt. Hầu cận của cô ấy không làm đúng phận sự của một người hầu trung thành, thay vì chăn dắt những con ma ngỗ ngược và nghe theo yêu cầu của chủ nhân phù thủy của mình thì anh ta lại gia nhập với chúng để gây ra rắc rối. Nếu phù thủy biết những người hầu cận và đám ma quỷ của mình tinh quái như thế nào, cô đã không bao giờ để chúng ngủ với mình."
L37_1[1] = L38_1
L37_1[2] = L39_1
L38_1 = {}
L39_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_ZODIAC_CHARLOTTE_RA"
L40_1 = "Lịch sử của các Hiệp Sĩ Hoàng Đạo kể lại nhiều câu chuyện hào hiệp về các bậc thầy hiệp sĩ trước đây cùng với thanh kiếm Xử Nữ. Với sự phù hộ của các vì sao, tất cả họ đã chiến đấu dũng cảm và chiến thắng kẻ thù mạnh nhất trong thế hệ của mình, giống như một anh hùng thần thoại. \nEsterosa, chủ nhân hiện tại của Thanh Kiếm Xử Nữ, đã sẵn sàng sử dụng sức mạnh của nó bất cứ lúc nào. Và các thành viên của cô ấy đều không nghi ngờ gì rằng một ngày nào đó, chủ nhân của họ sẽ tỏa sáng trên chiến trường như chòm sao trên bầu trời."
L38_1[1] = L39_1
L38_1[2] = L40_1
