L36_1 = "SI_ITEM_DESC_IQI_EQUIP_COUNTER_ACC_101158"
L37_1 = "Một bộ đồ trợ lực cải tiến được tạo từ Đồng Hồ, được tối ưu hóa cho chiến đấu cận chiến. Nó thể hiện quyết tâm của chủ nhân."
