L35_1[2] = L37_1
L36_1 = {}
L37_1 = "SI_ITEM_DESC_IQI_EQUIP_COUNTER_WEAPON_101063"
L38_1 = "Một thanh kiếm phản ứng dành riêng cho một người thầy đáng ngưỡng mộ. Hilde Nguyên Tử ban đầu được coi là tên của thanh đại kiếm này, nhưng nó đã nhanh chóng được đổi thành tên này sau khi người sở hữu nhận hình phạt từ giáo viên của cô."
