L2_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_CHALLENGE_RELIC_1_4"
L3_1 = "Người khổng lồ tạo ra một chiếc cúp đáng giá.\n\n<color=#ffd34c> ※ Kỹ năng Đặc Biệt của Cyclop là loại bỏ tất cả hiệu ứng bất lợi tác động lên nó và tạo ra một buff đặc biệt. Nếu buff không được xóa trước khi hết hạn, sẽ được chuyển đổi thành buff Vĩnh Viễn có thể cộng dồn.</color>"
L1_1[1] = L2_1
L1_1[2] = L3_1
L2_1 = {}
L3_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_CHALLENGE_RELIC_2_1"
L4_1 = "Mỗi ngày, những người lính mới được gửi đến mặt trận.\n\n<color=#ffd34c> ※ Những kẻ thù này cực kỳ ghê gớm, nhưng bạn có thể sử dụng rào chắn để giảm đáng kể sát thương của chúng.</color>"
L2_1[1] = L3_1
L2_1[2] = L4_1
L3_1 = {}
L4_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_CHALLENGE_RELIC_2_2"
L5_1 = "Họ là những người lính, miễn là họ cầm vũ khí trong tay.\n\n<color=#ffd34c> ※ Sử dụng rào chắn để giảm đáng kể sát thương từ những kẻ thù đáng gờm này.</color>"
L3_1[1] = L4_1
L3_1[2] = L5_1
L4_1 = {}
L5_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_CHALLENGE_RELIC_2_3"
L6_1 = "Tuyến phòng thủ bị sụp đổ, khiến trụ sở của họ bị lộ trước kẻ thù.\n\n<color=#ffd34c> ※ Những kẻ thù này cực kỳ ghê gớm, nhưng bạn có thể sử dụng một rào chắn để giảm đáng kể sát thương từ chúng.</color>"
L4_1[1] = L5_1
L4_1[2] = L6_1
L5_1 = {}
L6_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_CHALLENGE_RELIC_2_4"
L7_1 = "Thủ lĩnh đã không bỏ chạy cho đến phút cuối.\n\n<color=#ffd34c> ※ Những kẻ thù này cực kỳ ghê gớm, nhưng bạn có thể sử dụng một rào chắn để giảm đáng kể sát thương từ chúng.</color>"
L5_1[1] = L6_1
L5_1[2] = L7_1
L6_1 = {}
L7_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_CHALLENGE_RELIC_3_1"
L8_1 = "Ngày xưa, họ thường những nhân vật nổi tiếng. \n\n<color=#ffd34c> ※ Đòn tấn công của những kẻ thù này rất mạnh, nhưng không chính xác.\n ※ Totem hỗ trợ kẻ thù bằng đặc tính chữa bệnh của chúng.</color>"
L6_1[1] = L7_1
L6_1[2] = L8_1
L7_1 = {}
L8_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_CHALLENGE_RELIC_3_2"
L9_1 = "Khu vực này sâu và rộng lớn. Vùng đồng bằng tăm tối tràn ngập những giọng nói giận dữ trong các cuộc tranh luận nảy lửa.\n\n<color=#ffd34c> ※ Đòn tấn công của những kẻ thù này rất mạnh, nhưng không chính xác.\n ※ Chúng đã phát triển khả năng chống lại sự sát thương của mặt đất. Totem hỗ trợ chúng với các đặc tính chữa bệnh.</color>"
L7_1[1] = L8_1
L7_1[2] = L9_1
L8_1 = {}
L9_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_CHALLENGE_RELIC_3_3"
L10_1 = "Những người không có nhận thức thông thường cũng xa lạ như những sinh vật ngoài Trái Đất.\n\n<color=#ffd34c> ※ Đòn tấn công của những kẻ thù này rất mạnh, nhưng không chính xác.\n ※ Chúng đã phát triển khả năng chống lại sự phá hủy sát thương của mặt đất. Totem hỗ trợ chúng bằng các đặc tính chữa bệnh. \n ※ Kỹ năng Tối Thượng của Rivet gây thêm sát thương lên Counter.</color>"
L8_1[1] = L9_1
L8_1[2] = L10_1
L9_1 = {}
L10_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_CHALLENGE_RELIC_3_4"
L11_1 = "Hiệp hội đảm bảo rằng những vị khách được mời của mình được ăn uống đầy đủ và ra về vui vẻ.\n\n<color=#ffd34c> ※ Đòn tấn công của những kẻ thù này rất mạnh, nhưng không chính xác.\n ※ Chúng đã phát triển khả năng chống lại sự sát thương của Mặt đất. Totem hỗ trợ chúng bằng đặc tính chữa bệnh. \n ※ Kỹ năng của Edel ngay lập tức tiêu diệt các đơn vị được triệu hồi khi trúng đòn.</color>"
