L24_1[2] = L26_1
L25_1 = {}
L26_1 = "SI_EPISODE_EPISODE_DESC_2_CHALLENGE_SOF"
L27_1 = "Bạn có thể bảo đảm vật tư chiến tranh thông qua mô phỏng tác chiến cấp cao."
L25_1[1] = L26_1
L25_1[2] = L27_1
L26_1 = {}
L27_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_CHALLENGE_SOF_1_1"
L28_1 = "Bạn nhận được loại công việc nào là nhiều nhất hả Tommy?\nHeh. Tôi không tự mình nhận được chúng. Những người ngưỡng mộ tôi tự đem tới cho tôi."
L26_1[1] = L27_1
L26_1[2] = L28_1
L27_1 = {}
L28_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_CHALLENGE_SOF_1_2"
L29_1 = "Một yêu cầu của khách hàng? Tốt, tôi cần thử thuốc thử mà tôi mới điều chế. \nVà tất nhiên, tôi sẽ chạy sau khi nó hết.\n<color=#ffd34c>※Nước Thánh theo công thức mới của Jane Doe tối đa hóa khả năng vật lý của cô ấy và dễ dàng thực hiện các đòn tấn công nhanh.</color>"
L27_1[1] = L28_1
L27_1[2] = L29_1
L28_1 = {}
L29_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_CHALLENGE_SOF_1_3"
L30_1 = "Bạn có thể tin tưởng tôi cho bất cứ công việc gì. Không gì là không thể với Lính Đánh Thuê Thông Minh. \nNhưng ơ, nghĩ rằng bạn có thể mang kẻ thù đến đây cho tôi sao? \n<color=#ffd34c>※ Máy tạo sóng siêu âm của John Mason khiến kẻ thù mất tập trung, hạn chế khả năng của chúng. Sử dụng các thành viên trong tiểu đội cơ bản."
L28_1[1] = L29_1
L28_1[2] = L30_1
L29_1 = {}
L30_1 = "SI_EPISODE_EPISODE_NAME_CHALLENGE_SOF"
L31_1 = "Một Ngày Của Vài Lính Đánh Thuê"
L29_1[1] = L30_1
L29_1[2] = L31_1
L30_1 = {}
L31_1 = "SI_ITEM_DESC_IQI_EQUIP_SOLDIER_ACC_101096"
L32_1 = "Anh luôn mang theo vật vô giá đã bị vỡ nát này, hy vọng một ngày nào đó nó sẽ chặn được một hoặc hai viên đạn."
L30_1[1] = L31_1
L30_1[2] = L32_1
L31_1 = {}
L32_1 = "SI_ITEM_DESC_IQI_EQUIP_SOLDIER_ACC_101145"
L33_1 = "Mũ bảo hiểm yêu thích của Tommy. Anh ta nói rằng nó đã cứu anh ta khỏi móng vuốt của V.T.A.M. cấp 4 đáng sợ, không chỉ một lần mà là đến bốn lần."
L31_1[1] = L32_1
L31_1[2] = L33_1
L32_1 = {}
L33_1 = "SI_ITEM_DESC_IQI_EQUIP_SOLDIER_WEAPON_101097"
L34_1 = "Một con dao diều hâu có hình dạng giống như móng của diều hâu. Nó có thể giật bất cứ thứ gì nó muốn: tiền bạc, đồ vật, ngay cả mạng sống."
L32_1[1] = L33_1
L32_1[2] = L34_1
L33_1 = {}
