L11_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_MILITIA_1_2"
L12_1 = "Không một kẻ xấu nào có thể chống lại những cú đấm của anh ấy. \nSức mạnh thân thể là cách nhanh nhất để khiến tội phạm khuất phục."
L10_1[1] = L11_1
L10_1[2] = L12_1
L11_1 = {}
L12_1 = "SI_SKIN_DESC_NKM_UNIT_JUNIOR_C_RULER_SPORTS"
L13_1 = "Không có hoạt náo viên nào lại không thích gây chú ý. Cô gái này đặc biệt thích có ánh đèn sân khấu.\nNếu sự cổ vũ của cô ấy có thể lay động được dù chỉ một người, cô ấy sẽ cổ vũ hết lần này đến lần khác.\n\n<color=#ffd34c> Cố gắng hết sức nhé! Chúng ta luôn đồng hành cùng nhau!</color> "
L11_1[1] = L12_1
L11_1[2] = L13_1
L12_1 = {}
L13_1 = "SI_SKIN_DESC_NKM_UNIT_C_ADMIN_GREATSWORD_SPORTS"
L14_1 = "Nấu ăn không phải là kỹ năng cần thiết đối với một phụ tá, nhưng giỏi việc này thì chẳng có hại gì. Cô ấy đã chuẩn bị một hộp cơm trưa cho bạn cũng như những người khác. Mặc dù không chắc bạn có thể chịu đựng được tình yêu nồng nhiệt trong đó. \n\n<color=#ffd34c>Tôi thử rồi. Không biết có hợp khẩu vị của bạn không?</color> "
L12_1[1] = L13_1
L12_1[2] = L14_1
L13_1 = {}
L14_1 = "SI_SKIN_DESC_NKM_UNIT_ACADEMY_C_TWINTAIL_SPORTS"
L15_1 = "Việc lựa chọn trang phục thể hiện tâm thế của cô ấy khi đối mặt với một trận đấu. Tuy giả vờ không quan tâm, nhưng trang phục cho thấy cô ấy đã chuẩn bị nghiêm túc như thế nào. Chắc hẳn cô ấy đã luyện tập rất chăm chỉ đúng không?\n\n<color=#ffd34c>Tôi là một người ưu tú. Tôi không cần phải luyện tập. ... Những chiếc băng này á? K-không cần biết!</color> "
L13_1[1] = L14_1
L13_1[2] = L15_1
L14_1 = {}
L15_1 = "SI_SKIN_DESC_NKM_UNIT_ALT_CA_SEO_YOON_SPORTS"
L16_1 = "Một cuộc thi đấu tốt đòi hỏi một đối thủ tốt. Đối thủ của bạn càng mạnh, bạn càng khao khát chiến thắng. Nhưng nếu cuối cùng bạn không thể đánh bại đối thủ của mình thì sao? Kể từ đó, đối thủ của bạn sẽ trở thành nhân vật chính mới.\n\n<color=#ffd34c>Điểm trận. Bạn tiếp tục được chứ?</color> "
L14_1[1] = L15_1
L14_1[2] = L16_1
