L2_1 = "SI_EPISODE_DUNGEON_NAME_NKM_DUNGEON_EVENT_HORIZON_6_2_3"
L3_1 = "Bộ Lưu Trữ Đối Tượng Thử Nghiệm"
L1_1[1] = L2_1
L1_1[2] = L3_1
L2_1 = {}
L3_1 = "SI_EPISODE_DUNGEON_NAME_NKM_DUNGEON_EVENT_HORIZON_6_3"
L4_1 = "Chiến Đấu"
L2_1[1] = L3_1
L2_1[2] = L4_1
L3_1 = {}
L4_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_HORIZON_1_1_HM"
L5_1 = "Ngay cả một tên trộm vặt đôi khi cũng có thể truyền cảm hứng cho mọi người."
L3_1[1] = L4_1
L3_1[2] = L5_1
L4_1 = {}
L5_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_HORIZON_1_INTERLUDE_3"
L6_1 = "Phương tiện truyền thông đều đồng ý là vị CEO khó hiểu của Jehuty Biotech đang cố tình tạo ra một hình ảnh bí ẩn. Được công nhận là Doanh Nhân Của Năm ở Charade, anh ấy đã nỗ lực đáng kể để cải thiện hình ảnh công ty bằng cách thúc đẩy chương trình cứu trợ y tế ở các khu vực bị thiệt thòi."
L4_1[1] = L5_1
L4_1[2] = L6_1
L5_1 = {}
L6_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_HORIZON_2_1_HM"
L7_1 = "Hỡi Thần Điểu, người kêu gọi ngọn lửa thanh trừng. Ngài đã tìm thấy thời gian nghỉ ngơi trên vùng đất mà ngài đã rơi xuống khi mất đôi cánh của mình chưa?"
L5_1[1] = L6_1
L5_1[2] = L7_1
L6_1 = {}
L7_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_HORIZON_2_2"
L8_1 = "Giám Mục Elcano là một trong những kẻ đào tẩu trong vụ án vượt ngục lớn. Mặc dù không ai biết chắc chắn hắn ta gây quỹ thế nào, nhưng rõ ràng là hắn ta đã tập hợp được một số người cuồng tín theo Hiệp Hội Tiên Tri Magellan. Hắn phải bị bắt ngay lập tức."
L6_1[1] = L7_1
L6_1[2] = L8_1
L7_1 = {}
L8_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_HORIZON_2_INTERLUDE_1"
L9_1 = "Yêu cầu khởi động lại. Có thể cần thời gian đáng kể để sửa chữa lỗi nghiêm trọng."
L7_1[1] = L8_1
L7_1[2] = L9_1
L8_1 = {}
L9_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_HORIZON_2_INTERLUDE_3"
L10_1 = "Có điều gì đó khó hiểu về viện trợ y tế của Jehuty Biotech. Thống kê cho thấy những khu vực mà đoàn cứu trợ đến có tỷ lệ người mất tích cao hơn so với mức trung bình của khu vực. Đó là một sự trùng hợp ngẫu nhiên hơi đáng ngờ, không phải sao?"
L8_1[1] = L9_1
L8_1[2] = L10_1
L9_1 = {}
L10_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_HORIZON_2_INTERLUDE_4"
L11_1 = "Charade giống như một khu rừng hung ác, nơi mỗi ngày đều là một cuộc chiến sinh tồn. Mặc dù mọi người đều giữ vẻ ngoài tinh tế, nhưng đằng sau vẻ ngoài đó là một cuộc chiến không bao giờ kết thúc. Không phải đao kiếm hay súng, tiền mới là vũ khí được lựa chọn ở đây."
L9_1[1] = L10_1
L9_1[2] = L11_1
L10_1 = {}
L11_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_HORIZON_3_1"
L12_1 = "Trẻ em chết đói vì không mua nổi thức ăn. Người già chết một mình vì họ không thể có tiền trả cho dịch vụ y tế. Những cô gái bán mình vì không thể kiếm sống bằng cách nào khác. Những điều đáng buồn nhất ở những nơi khác lại là cuộc sống hàng ngày ở đây."
L10_1[1] = L11_1
L10_1[2] = L12_1
L11_1 = {}
L12_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_HORIZON_3_1_HM"
L13_1 = "Công lý không bao giờ từ bỏ."
L11_1[1] = L12_1
L11_1[2] = L13_1
L12_1 = {}
L13_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_HORIZON_3_INTERLUDE_1"
L14_1 = "Giữa mối đe dọa hiện hữu đối với nhân loại, những bộ óc vĩ đại nhất của thế giới đã đoàn kết lại dưới câu thần chú \"Bảo Vệ Nhân Loại.\" Hy vọng đó tỏa sáng giống như một chiếc đèn hiệu trong cuộc khủng hoảng rồi sau đó mờ nhạt dần khi kỷ nguyên hòa bình tiến đến."
L12_1[1] = L13_1
L12_1[2] = L14_1
L13_1 = {}
L14_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_HORIZON_4_1"
L15_1 = "Kể từ khi thành lập Chiến Tranh Tương Lai, Lực Lượng Liên Minh Đa Quốc Gia và các cơ quan tình báo trên khắp thế giới đã yêu cầu phân tích các vật thể không xác định mà họ thu được mà sau này được gọi là \"Thần Khí.\" Các thần khí mà được chứng minh là quá trừu tượng để phân tích, được phân loại là \"Cold Case\" và được lưu trữ ở những nơi sâu nhất của cơ sở nghiên cứu. Một số lượng đáng kể các trường hợp trong danh sách đó vẫn chưa được thống kê."
L13_1[1] = L14_1
L13_1[2] = L15_1
L14_1 = {}
L15_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_HORIZON_4_1_HM"
L16_1 = "Luôn có một con quái vật rình rập trong trái tim con người."
L14_1[1] = L15_1
L14_1[2] = L16_1
L15_1 = {}
L16_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_HORIZON_4_2"
L17_1 = "Chiến Tranh Tương Lai đã là trung tâm của tranh chấp quốc tế về công nghệ quân sự tiên tiến trong chiến tranh. Ngày nay người ta đánh giá rằng dự án chỉ tồn tại được nhờ vào việc cung cấp công nghệ rời rạc nhờ có sự hỗ trợ nhịp nhàng của Giám Đốc Ember."
L15_1[1] = L16_1
L15_1[2] = L17_1
L16_1 = {}
L17_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_HORIZON_4_3"
L18_1 = "Trong hoàn cảnh ở thời điểm đó, không có gì phải bàn cãi nếu coi Giám Đốc Ember là một cá nhân nguy hiểm, vì cô ấy đóng một vai trò quan trọng trong việc tập hợp Chiến Tranh Tương Lai. Đến nay, đã có 127 vụ âm mưu ám sát được xác nhận. Nếu tính cả những nỗ lực bắt cóc hoặc tuyển dụng nhưng không thành công, không có gì ngạc nhiên khi cô ấy quyết định rời đi."
L16_1[1] = L17_1
L16_1[2] = L18_1
L17_1 = {}
L18_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_HORIZON_5_1_HM"
L19_1 = "Hiệp Sĩ Xử Nữ. Không ai khác trong Hoàng Đạo có thể trở thành một nhà lãnh đạo có năng lực hơn."
L17_1[1] = L18_1
L17_1[2] = L19_1
L18_1 = {}
L19_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_HORIZON_5_2"
L20_1 = "Bằng cách đảm bảo các kế hoạch kế thừa của sáng kiến Chiến Tranh Tương Lai mà đã bị tạm ngưng sau chiến tranh, Quỹ Chiến Tranh Tương Lai đã đảm bảo quyền bá chủ của mình đối với ngành công nghiệp quốc phòng. Mặc dù sản lượng tương đối thấp, việc bán các Titan được sản xuất hàng loạt với giá cả phải chăng hơn cho Ban Quản Lý Thành Phố đã giúp tăng thêm vị thế như vậy."
L18_1[1] = L19_1
L18_1[2] = L20_1
L19_1 = {}
L20_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_HORIZON_5_INTERLUDE_1"
L21_1 = "Người ta đã xác nhận rằng một lượng bất động sản đáng kể mà Jehuty Biotech mua gần đây từng thuộc về Nghiệp Đoàn Nhân Bản. Có những lo ngại rằng Jehuty có thể đang cố gắng thông đồng với các thành viên còn lại của Nghiệp Đoàn hoặc chiếm đoạt công nghệ của Nghiệp Đoàn."
L19_1[1] = L20_1
L19_1[2] = L21_1
L20_1 = {}
L21_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_HORIZON_6_1"
L22_1 = "Giữa những người chết, có những người sống sót. Giữa những người sống sót, có những người đau khổ. Và trong số đó, có những người khóc. Và đằng sau họ là những người đang co rúm lại. Và trước mặt họ, là những tiếng cười. Ha Ha. Hee Hee. Hô Hô. Họ cứ tiếp tục cười thế thôi."
L20_1[1] = L21_1
L20_1[2] = L22_1
L21_1 = {}
L22_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_HORIZON_6_1_HM"
L23_1 = "Cho đến ngày nhạc trưởng lên sân khấu, dàn nhạc sẽ không chấm dứt bản giao hưởng về ngày tận thế."
L21_1[1] = L22_1
L21_1[2] = L23_1
L22_1 = {}
L23_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_HORIZON_6_2"
L24_1 = "Các Tia Ăn Mòn mức độ cao đã được phát hiện ở trung tâm thành phố Charade. Vì thảm họa ăn mòn có thể xảy ra rải rác khắp thành phố, chúng tôi khuyên mọi công dân nên tránh xa các khu vực bị ảnh hưởng và duy trì lá chắn Vàng Vĩnh Cửu trên người cho đến khi cảnh báo này được gỡ bỏ.\n\n<color=#FF0000>*Tài nguyên có sẵn có ít hơn để triển khai do mức độ Tia Ăn Mòn cao.</color>"
L22_1[1] = L23_1
L22_1[2] = L24_1
L23_1 = {}
L24_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_HORIZON_6_INTERLUDE_1"
L25_1 = "Ngày nay, việc nghiên cứu để xác định các thuộc tính của thần khí vẫn tiếp tục diễn ra với sự quyết tâm cao nhất trên toàn cầu. Tuy nhiên, không có công nghệ nào có thể khai thác và khuếch đại các đặc tính đó."
L23_1[1] = L24_1
L23_1[2] = L25_1
L24_1 = {}
L25_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_HORIZON_6_INTERLUDE_3"
L26_1 = "Hỡi Thần Điểu, với cái đầu và đôi cánh gãy! Tầm nhìn từ mặt đất thế nào? Chắc chắn nó khác xa với việc ngắm từ trên cao như trước nhỉ. Khi đã quyết định rồi thì hãy lên tế đàn thôi. Vì cô ấy sẽ nín thở chờ đợi cho tới khi ngài đến."
L24_1[1] = L25_1
L24_1[2] = L26_1
L25_1 = {}
L26_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_HORIZON_6_INTERLUDE_4"
L27_1 = "Vì vậy, hãy kết thúc mối quan hệ xấu số, để nhường chỗ cho một mối thù lâu dài khác xuất hiện."
L25_1[1] = L26_1
L25_1[2] = L27_1
L26_1 = {}
L27_1 = "SI_EPISODE_EPISODE_DESC_NKM_PHASE_EVENT_HORIZON_1_CM"
L28_1 = "Jehuty Biotech đã đầu tư những nỗ lực đáng kể để cải thiện hình ảnh của mình.\nVí dụ: họ đã mở rộng các tầng dưới của trụ sở để tạo ra các cơ sở giáo dục, nơi du khách có thể tìm hiểu thêm về kỹ thuật sinh học."
L26_1[1] = L27_1
L26_1[2] = L28_1
L27_1 = {}
L28_1 = "SI_EPISODE_EPISODE_DESC_NKM_PHASE_EVENT_HORIZON_2_CM"
L29_1 = "Các tầng giữa của trụ sở đóng vai trò là xương sống của công ty, vì nhiều văn phòng của họ giám sát việc điều hành và quản lý các cơ sở nghiên cứu trên khắp thế giới.\nTuy nhiên, nhân viên ở tầng này thường phàn nàn rằng chiếc thang máy khổng lồ dẫn thẳng từ tầng hầm lên tầng cao nhất chiếm quá nhiều diện tích."
L27_1[1] = L28_1
L27_1[2] = L29_1
L28_1 = {}
L29_1 = "SI_EPISODE_EPISODE_DESC_NKM_PHASE_EVENT_HORIZON_3_CM"
L30_1 = "Các tầng trên của trụ sở là một khu vực bí mật mà chỉ CEO, giám đốc và trợ lý của họ mới có thể tiếp cận. Không có nhiều nhân viên đặc biệt quan tâm đến nơi này.\nCác tầng trên hoàn toàn không liên quan đến lộ trình thông thường của họ, sổ tay nhân viên và thậm chí cả các địa điểm họp điều hành."
