L33_1 = {}
L34_1 = "SI_EPISODE_PHASE_DESC_NKM_DUNGEON_EVENT_HORIZON_6_2"
L35_1 = "Các Tia Ăn Mòn mức độ cao đã được phát hiện ở trung tâm thành phố Charade. Vì thảm họa ăn mòn có thể xảy ra rải rác khắp thành phố, chúng tôi khuyên mọi công dân nên tránh xa các khu vực bị ảnh hưởng và duy trì lá chắn Vàng Vĩnh Cửu trên người cho đến khi cảnh báo này được gỡ bỏ.\n\n<color=#FF0000>*Tài nguyên có sẵn có ít hơn để triển khai do mức độ Tia Ăn Mòn cao.</color>"
L33_1[1] = L34_1
L33_1[2] = L35_1
L34_1 = {}
L35_1 = "SI_EPISODE_PHASE_DESC_NKM_PHASE_EVENT_HORIZON_1_CM"
L36_1 = "Jehuty Biotech đã đầu tư những nỗ lực đáng kể để cải thiện hình ảnh của mình.\nVí dụ: họ đã mở rộng các tầng dưới của trụ sở để tạo ra các cơ sở giáo dục, nơi du khách có thể tìm hiểu thêm về kỹ thuật sinh học."
L34_1[1] = L35_1
L34_1[2] = L36_1
L35_1 = {}
L36_1 = "SI_EPISODE_PHASE_DESC_NKM_PHASE_EVENT_HORIZON_2_CM"
L37_1 = "Các tầng giữa của trụ sở đóng vai trò là xương sống của công ty, vì nhiều văn phòng của họ giám sát việc điều hành và quản lý các cơ sở nghiên cứu trên khắp thế giới.\nTuy nhiên, nhân viên ở tầng này thường phàn nàn rằng chiếc thang máy khổng lồ dẫn thẳng từ tầng hầm lên tầng cao nhất chiếm quá nhiều diện tích."
L35_1[1] = L36_1
L35_1[2] = L37_1
