L19_1 = "BC_NANAHARA_DESC"
L20_1 = "Khi Minato ở trong bản đồ,\nASPD của tất cả  đơn vị +20%, Tốc Độ Nạp Lại Kỹ Năng +30%"
L18_1[1] = L19_1
