L23_1 = "Điểm Danh Đặc Biệt Của Mặt Nạ Cáo"
L21_1[1] = L22_1
L21_1[2] = L23_1
L22_1 = {}
L23_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_JAPAN_C_OROCHI"
L24_1 = "Orochi là một Lính Cơ Động tập trung các cuộc tấn công vào một mục tiêu duy nhất trong hình dáng giống con rắn của mình.\nCách đây đã lâu, một Nạn Đói đã hoành hành trên toàn thế giới. Sau đó, một người phụ nữ có thể nghe thấy mọi âm thanh đã nghe thấy rằng Nạn Đói cô đơn như thế nào và xoa dịu nó để khôi phục Sự Màu Mỡ. Người phụ nữ đã phục vụ Sự Màu Mỡ trong một thời gian dài và mọi người tôn thờ cô ấy như một nữ tư tế. Tuy nhiên, họ lại ngày càng trở nên tham lam và không biết hài lòng. Họ tìm kiếm sự sống vĩnh cửu và cuối cùng, đã giết chết nữ tư tế. Sự Màu Mỡ đã tự biến đổi thành một con rắn tám đầu hô mưa, gọi sấm, dời núi. Nó trừng phạt con người cho đến khi bị phong ấn với cái giá phải trả là vô số sự hy sinh. \nNhưng chừng nào con người còn ham muốn, Orochi sẽ trở lại, dụ dỗ họ bằng lời hứa về cuộc sống vĩnh hằng."
L22_1[1] = L23_1
L22_1[2] = L24_1
L23_1 = {}
L24_1 = "SI_EPISODE_DUNGEON_DESC_NKM_DUNGEON_EVENT_NANAHARA_1_1"
L25_1 = "Hồi đó, mọi người không quan tâm lắm đến những mạng sống bình thường bị những người trở thành Counter tước đoạt."
L23_1[1] = L24_1
L23_1[2] = L25_1
L24_1 = {}
L25_1 = "SI_EPISODE_DUNGEON_DESC_NKM_DUNGEON_EVENT_NANAHARA_1_1_HM"
L26_1 = "Con cháu của ta. Hãy chia sẻ gánh nặng của nữ tư tế."
L24_1[1] = L25_1
L24_1[2] = L26_1
L25_1 = {}
L26_1 = "SI_EPISODE_DUNGEON_DESC_NKM_DUNGEON_EVENT_NANAHARA_1_2"
L27_1 = "Theo hồ sơ, các trường hợp khẩn cấp về Hiệu Ứng Ăn Mòn xảy ra gần như đồng thời.\nNhưng không có trường hợp nào trong số chúng có tiêu chí cụ thể để phân loại ngoài một hệ thống cấp bậc đơn giản."
L25_1[1] = L26_1
L25_1[2] = L27_1
L26_1 = {}
L27_1 = "SI_EPISODE_DUNGEON_DESC_NKM_DUNGEON_EVENT_NANAHARA_1_3"
L28_1 = "Ở đâu đó trong khu dân cư, có một khu chưa phát triển mọc cây cỏ um tùm. Ngoài một số truyền thuyết đô thị, chỉ một số ít người biết được bản chất thực sự của nơi này."
L26_1[1] = L27_1
L26_1[2] = L28_1
L27_1 = {}
L28_1 = "SI_EPISODE_DUNGEON_DESC_NKM_DUNGEON_EVENT_NANAHARA_1_INTERLUDE_1"
L29_1 = "Chúng tôi gọi đó là bệnh Ăn Mòn. Một loại virus ăn mòn thực tại."
L27_1[1] = L28_1
L27_1[2] = L29_1
L28_1 = {}
L29_1 = "SI_EPISODE_DUNGEON_DESC_NKM_DUNGEON_EVENT_NANAHARA_1_INTERLUDE_2"
L30_1 = "Một tòa nhà nằm trên đỉnh của một tòa nhà.\nTháp Đồng Hồ Trung Tâm là tòa nhà lớn nhất trong Khu Quản Lý Trung Tâm và có một Tenshu được xây dựng ở trên đỉnh."
L28_1[1] = L29_1
L28_1[2] = L30_1
L29_1 = {}
L30_1 = "SI_EPISODE_DUNGEON_DESC_NKM_DUNGEON_EVENT_NANAHARA_1_INTERLUDE_3"
L31_1 = "Bảo trọng nhé. Lựa chọn là của cô."
L29_1[1] = L30_1
L29_1[2] = L31_1
L30_1 = {}
L31_1 = "SI_EPISODE_DUNGEON_DESC_NKM_DUNGEON_EVENT_NANAHARA_1_PROLOGUE"
L32_1 = "Tôi mơ một giấc mơ. Kỉ ức vụn vặt về một cuộc gặp gỡ bất ngờ trên con phố ngập tràn hoa anh đào."
L30_1[1] = L31_1
L30_1[2] = L32_1
L31_1 = {}
L32_1 = "SI_EPISODE_DUNGEON_DESC_NKM_DUNGEON_EVENT_NANAHARA_2_1"
L33_1 = "Minato, cây cung này sẽ bảo vệ cháu, và cả những điều cháu mong ước.\nHãy tiếp tục luyện tập nhé."
L31_1[1] = L32_1
L31_1[2] = L33_1
L32_1 = {}
L33_1 = "SI_EPISODE_DUNGEON_DESC_NKM_DUNGEON_EVENT_NANAHARA_2_1_HM"
L34_1 = "Một yêu cầu ám sát? Chà, đó là công việc của tôi nên tôi chả sao cả... \n Nhưng chẳng phải cậu còn quá trẻ để có thái độ thù địch như vậy với ai đó sao?"
L32_1[1] = L33_1
L32_1[2] = L34_1
L33_1 = {}
L34_1 = "SI_EPISODE_DUNGEON_DESC_NKM_DUNGEON_EVENT_NANAHARA_2_2"
L35_1 = "Khi Hayami giết cựu Thủ Lĩnh Liên Minh trước khi phong ấn xảy ra, điều đó đã vi phạm luật nhân quả.\nNếu không có sự cố, thì thất bại ba năm trước đã không xảy ra. Ít nhất đó là những gì Liên Minh tin."
L33_1[1] = L34_1
L33_1[2] = L35_1
L34_1 = {}
L35_1 = "SI_EPISODE_DUNGEON_DESC_NKM_DUNGEON_EVENT_NANAHARA_2_3"
L36_1 = "Con người liên tục lặp lại chính mình trong suốt cuộc đời ngắn ngủi của họ.\nĐiều tốt và điều xấu đều mới mẻ trừ khi cậu thực sự trải nghiệm chúng."
L34_1[1] = L35_1
L34_1[2] = L36_1
L35_1 = {}
L36_1 = "SI_EPISODE_DUNGEON_DESC_NKM_DUNGEON_EVENT_NANAHARA_2_INTERLUDE_1"
L37_1 = "Cuộc sống vĩnh cửu có cái giá của nó. Hãy nhanh lên."
L35_1[1] = L36_1
L35_1[2] = L37_1
L36_1 = {}
L37_1 = "SI_EPISODE_DUNGEON_DESC_NKM_DUNGEON_EVENT_NANAHARA_2_INTERLUDE_2"
L38_1 = "Nữ tư tế không bao giờ ghét con người, ngay cả khi bà ấy qua đời. Vì vậy, hậu duệ của bà cũng quyết định bảo vệ loài người.\nTruyền thống này đã khiến Liên Minh Gia Tộc coi trọng gia đình trực hệ hơn những gia đình phi trực hệ."
L36_1[1] = L37_1
L36_1[2] = L38_1
L37_1 = {}
L38_1 = "SI_EPISODE_DUNGEON_DESC_NKM_DUNGEON_EVENT_NANAHARA_2_INTERLUDE_3"
L39_1 = "Ngay cả nữ tư tế cũng không biết cơn gió bắt đầu từ đâu. Cô ấy chỉ biết nó hướng đến đâu."
L37_1[1] = L38_1
L37_1[2] = L39_1
L38_1 = {}
L39_1 = "SI_EPISODE_DUNGEON_DESC_NKM_DUNGEON_EVENT_NANAHARA_3_1"
L40_1 = "Gia đình Hayami có những tùy tùng giỏi nhất trong số các gia đình khác, và họ rất được tín nhiệm. Họ phải biết mọi bí mật để bảo vệ Liên Minh."
L38_1[1] = L39_1
L38_1[2] = L40_1
L39_1 = {}
L40_1 = "SI_EPISODE_DUNGEON_DESC_NKM_DUNGEON_EVENT_NANAHARA_3_1_HM"
L41_1 = "N-ngươi nản lòng và độc địa. Cầu mong ngươi yên nghỉ trong niềm tự hào."
L39_1[1] = L40_1
L39_1[2] = L41_1
L40_1 = {}
L41_1 = "SI_EPISODE_DUNGEON_DESC_NKM_DUNGEON_EVENT_NANAHARA_3_2"
L42_1 = "Gió chỉ đường cho cậu, nhưng nó không phải là câu trả lời."
L40_1[1] = L41_1
L40_1[2] = L42_1
L41_1 = {}
L42_1 = "SI_EPISODE_DUNGEON_DESC_NKM_DUNGEON_EVENT_NANAHARA_3_3"
L43_1 = "Có lẽ câu trả lời đã được quyết định ngay từ đầu."
L41_1[1] = L42_1
L41_1[2] = L43_1
L42_1 = {}
L43_1 = "SI_EPISODE_DUNGEON_DESC_NKM_DUNGEON_EVENT_NANAHARA_3_4"
L44_1 = "Và có lẽ, một người bình thường tuân theo câu trả lời đã được định sẵn là lựa chọn chính xác."
L42_1[1] = L43_1
L42_1[2] = L44_1
L43_1 = {}
L44_1 = "SI_EPISODE_DUNGEON_DESC_NKM_DUNGEON_EVENT_NANAHARA_3_INTERLUDE_1"
L45_1 = "Tôi biết phải đi đâu, nhưng tôi chưa bao giờ đi trên con đường đó."
L43_1[1] = L44_1
L43_1[2] = L45_1
L44_1 = {}
L45_1 = "SI_EPISODE_DUNGEON_DESC_NKM_DUNGEON_EVENT_NANAHARA_3_INTERLUDE_2"
L46_1 = "Nhưng nếu đó là câu trả lời mang lại cuộc sống bình thường cho tôi,\ntôi sẽ phủ nhận nó."
L44_1[1] = L45_1
L44_1[2] = L46_1
L45_1 = {}
L46_1 = "SI_EPISODE_DUNGEON_DESC_NKM_DUNGEON_EVENT_NANAHARA_4_1"
L47_1 = "Liên Minh cần hậu duệ của nữ tư tế, một vị cứu tinh để ngăn chặn Orochi.\nVà tôi đã cố gắng hết sức để đáp ứng kỳ vọng của họ — hoặc tôi nghĩ vậy."
L45_1[1] = L46_1
L45_1[2] = L47_1
L46_1 = {}
L47_1 = "SI_EPISODE_DUNGEON_DESC_NKM_DUNGEON_EVENT_NANAHARA_4_1_HM"
L48_1 = "Thần hộ mệnh đã nuốt chửng người phụ nữ bị con người đầu độc và trở thành thần bệnh dịch."
L46_1[1] = L47_1
L46_1[2] = L48_1
L47_1 = {}
L48_1 = "SI_EPISODE_DUNGEON_DESC_NKM_DUNGEON_EVENT_NANAHARA_4_2"
L49_1 = "Tôi đến đây không phải để cứu hậu duệ của nữ tư tế hay đấng cứu rỗi."
L47_1[1] = L48_1
L47_1[2] = L49_1
L48_1 = {}
L49_1 = "SI_EPISODE_DUNGEON_DESC_NKM_DUNGEON_EVENT_NANAHARA_4_3"
L50_1 = "Tôi ở đây để cứu cậu."
L48_1[1] = L49_1
L48_1[2] = L50_1
L49_1 = {}
L50_1 = "SI_EPISODE_DUNGEON_DESC_NKM_DUNGEON_EVENT_NANAHARA_4_EPILOGUE"
L51_1 = "Tôi sẽ luôn làm điều đó một lần nữa, để bảo vệ cuộc sống bình thường mà tôi hằng mong ước."
L49_1[1] = L50_1
L49_1[2] = L51_1
L50_1 = {}
L51_1 = "SI_EPISODE_DUNGEON_DESC_NKM_DUNGEON_EVENT_NANAHARA_4_EPILOGUE2"
L52_1 = "Người ta không thể xây dựng quan hệ nhân quả để có được kết quả mong muốn chỉ bằng chính bản thân mình."
L50_1[1] = L51_1
L50_1[2] = L52_1
