L19_1 = "SI_EPISODE_DUNGEON_NAME_NKM_DUNGEON_EVENT_NANAHARA_4_3"
L20_1 = "Mặt Trăng Kiên Quyết"
L18_1[1] = L19_1
L18_1[2] = L20_1
L19_1 = {}
L20_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_NANAHARA_1_1"
L21_1 = "Hồi đó, mọi người không quan tâm lắm đến những nhân mạng bình thường bị những người trở thành Counter tước đoạt."
L19_1[1] = L20_1
L19_1[2] = L21_1
L20_1 = {}
L21_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_NANAHARA_1_1_HM"
L22_1 = "Con cháu của ta. Xin chia sẻ gánh nặng của nữ tư tế."
L20_1[1] = L21_1
L20_1[2] = L22_1
L21_1 = {}
L22_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_NANAHARA_1_2"
L23_1 = "Theo hồ sơ, các trường hợp khẩn cấp về Hiệu Ứng Ăn Mòn xảy ra gần như đồng thời.\nNhưng không có trường hợp nào trong số chúng có tiêu chí cụ thể để phân loại ngoài một hệ thống cấp bậc đơn giản."
L21_1[1] = L22_1
L21_1[2] = L23_1
L22_1 = {}
L23_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_NANAHARA_1_3"
L24_1 = "Ở đâu đó trong khu dân cư, có một khu chưa phát triển với cây cỏ um tùm. Ngoài một số truyền thuyết thành thị, chỉ một số ít người biết được bản chất thực sự của nơi này."
L22_1[1] = L23_1
L22_1[2] = L24_1
L23_1 = {}
L24_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_NANAHARA_1_INTERLUDE_1"
L25_1 = "Chúng tôi gọi đó là bệnh Ăn Mòn. Một loại virus ăn mòn thực tại."
L23_1[1] = L24_1
L23_1[2] = L25_1
L24_1 = {}
L25_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_NANAHARA_1_INTERLUDE_2"
L26_1 = "Một tòa nhà nằm trên đỉnh của một tòa nhà.\nTháp Đồng Hồ Trung Tâm là tòa nhà lớn nhất trong Khu Quản Lý Trung Tâm và có một Tenshu được xây dựng ở trên đỉnh."
L24_1[1] = L25_1
L24_1[2] = L26_1
L25_1 = {}
L26_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_NANAHARA_1_INTERLUDE_3"
L27_1 = "Bảo trọng nhé. Lựa chọn là ở cậu."
L25_1[1] = L26_1
L25_1[2] = L27_1
L26_1 = {}
L27_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_NANAHARA_1_PROLOGUE"
L28_1 = "Tôi mơ một giấc mơ. Kỉ niệm vụn vặt về một cuộc gặp gỡ bất ngờ trên con phố ngập tràn hoa anh đào."
L26_1[1] = L27_1
L26_1[2] = L28_1
L27_1 = {}
L28_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_NANAHARA_2_1"
L29_1 = "Minato, cây cung này sẽ bảo vệ cháu, và cả những điều cháu mong ước.\nHãy tiếp tục luyện tập nhé."
L27_1[1] = L28_1
L27_1[2] = L29_1
L28_1 = {}
L29_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_NANAHARA_2_1_HM"
L30_1 = "Một yêu cầu ám sát? Chà, đó là công việc của tôi nên tôi không sao cả... \n Nhưng chẳng phải cậu còn quá trẻ để có thái độ thù địch như vậy với ai đó sao?"
L28_1[1] = L29_1
L28_1[2] = L30_1
L29_1 = {}
L30_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_NANAHARA_2_2"
L31_1 = "Hayami giết Thủ Lĩnh Liên Minh trước khi phong ấn xảy ra, điều đó đã vi phạm luật nhân quả.\nNếu không thì thất bại từ ba năm trước đã không xảy ra. Ít nhất đó là những gì Liên Minh tin tưởng."
L29_1[1] = L30_1
L29_1[2] = L31_1
L30_1 = {}
L31_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_NANAHARA_2_3"
L32_1 = "Con người liên tục lặp lại chính mình trong suốt cuộc đời ngắn ngủi của họ.\nĐiều tốt và điều xấu đều mới mẻ trừ khi cậu thực sự trải nghiệm chúng."
L30_1[1] = L31_1
L30_1[2] = L32_1
L31_1 = {}
L32_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_NANAHARA_2_INTERLUDE_1"
L33_1 = "Cuộc sống vĩnh cửu có cái giá của nó. Hãy nhanh lên."
L31_1[1] = L32_1
L31_1[2] = L33_1
L32_1 = {}
L33_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_NANAHARA_2_INTERLUDE_2"
L34_1 = "Nữ tư tế không bao giờ ghét con người, ngay cả khi bà ấy qua đời. Vì vậy, hậu duệ của bà cũng quyết định bảo vệ loài người.\nTruyền thống này đã khiến Liên Minh Gia Tộc coi trọng gia đình trực hệ hơn những gia đình phi trực hệ."
L32_1[1] = L33_1
L32_1[2] = L34_1
L33_1 = {}
L34_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_NANAHARA_2_INTERLUDE_3"
L35_1 = "Ngay cả nữ tư tế cũng không biết cơn gió bắt đầu từ đâu. Cô ấy chỉ biết nó hướng đến đâu."
L33_1[1] = L34_1
L33_1[2] = L35_1
L34_1 = {}
L35_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_NANAHARA_3_1"
L36_1 = "Gia đình Hayami có những tùy tùng giỏi nhất trong số các gia đình khác, và họ rất được tín nhiệm. Họ phải biết mọi bí mật để bảo vệ Liên Minh."
L34_1[1] = L35_1
L34_1[2] = L36_1
L35_1 = {}
L36_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_NANAHARA_3_1_HM"
L37_1 = "N-ngươi nản lòng và độc địa. Cầu mong ngươi yên nghỉ trong niềm tự hào."
L35_1[1] = L36_1
L35_1[2] = L37_1
L36_1 = {}
L37_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_NANAHARA_3_2"
L38_1 = "Gió chỉ đường cho cậu, nhưng nó không phải là câu trả lời."
L36_1[1] = L37_1
L36_1[2] = L38_1
L37_1 = {}
L38_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_NANAHARA_3_3"
L39_1 = "Có lẽ câu trả lời đã được quyết định ngay từ đầu."
L37_1[1] = L38_1
L37_1[2] = L39_1
L38_1 = {}
L39_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_NANAHARA_3_4"
L40_1 = "Và có lẽ, một người bình thường tuân theo câu trả lời đã được định sẵn là lựa chọn chính xác."
L38_1[1] = L39_1
L38_1[2] = L40_1
L39_1 = {}
L40_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_NANAHARA_3_INTERLUDE_1"
L41_1 = "Tôi biết phải đi đâu, nhưng tôi chưa bao giờ đi trên con đường đó."
L39_1[1] = L40_1
L39_1[2] = L41_1
L40_1 = {}
L41_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_NANAHARA_3_INTERLUDE_2"
L42_1 = "Nhưng nếu đó là câu trả lời mang lại cuộc sống bình thường cho tôi,\ntôi sẽ phủ nhận nó."
L40_1[1] = L41_1
L40_1[2] = L42_1
L41_1 = {}
L42_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_NANAHARA_4_1"
L43_1 = "Liên Minh cần hậu duệ của nữ tư tế, một vị cứu tinh để ngăn chặn Orochi.\nVà tôi đã cố gắng hết sức để đáp ứng kỳ vọng của họ — hoặc tôi nghĩ vậy."
L41_1[1] = L42_1
L41_1[2] = L43_1
L42_1 = {}
L43_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_NANAHARA_4_1_HM"
L44_1 = "Thần hộ mệnh đã nuốt chửng người phụ nữ bị con người đầu độc và trở thành thần bệnh dịch."
L42_1[1] = L43_1
L42_1[2] = L44_1
L43_1 = {}
L44_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_NANAHARA_4_2"
L45_1 = "Tôi đến đây không phải để cứu hậu duệ của nữ tư tế hay đấng cứu rỗi."
L43_1[1] = L44_1
L43_1[2] = L45_1
L44_1 = {}
L45_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_NANAHARA_4_3"
L46_1 = "Tôi ở đây để cứu cậu."
L44_1[1] = L45_1
L44_1[2] = L46_1
L45_1 = {}
L46_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_NANAHARA_4_EPILOGUE"
L47_1 = "Tôi sẽ luôn làm điều đó một lần nữa, để bảo vệ cuộc sống bình thường mà tôi hằng mong ước."
L45_1[1] = L46_1
L45_1[2] = L47_1
L46_1 = {}
L47_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_NANAHARA_4_EPILOGUE2"
L48_1 = "Người ta không thể xây dựng quan hệ nhân quả để có được kết quả mong muốn chỉ bằng chính bản thân mình."
L46_1[1] = L47_1
