L22_1 = {}
L23_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_KNIGHT_C_EMPEROR"
L24_1 = "Clareth El Arcadena là một Lính Tấn Công có chỉ số cơ bản cao, có khả năn vượt trội trong việc chiến đấu với nhiều kẻ thù cùng một lúc.\n\nAnh ấy là một người toàn diện, vừa là thái tử của Đế Chế Arcadena, người kế thừa Máu Rồng, và vừa thành viên của hội Hiệp Sĩ Chuộc Tội. Những lo lắng về tính cách kiêu ngạo của anh ấy trong khi giúp cho vị hoàng đế đau ốm giải quyết chính sự là hoàn toàn vô căn cứ. Mọi người cũng tin rằng đế chế sẽ thịnh vượng hơn bao giờ hết dưới sự lãnh đạo của hoàng tử.\n\nTuy nhiên, lịch sử của Đế Chế không cho phép Clareth mở ra một thời kỳ hòa bình."
L22_1[1] = L23_1
L22_1[2] = L24_1
