L4_1 = {}
L5_1 = "SI_PF_ASYNCMATCH_NEW_DESC"
L6_1 = "Chế độ chiến đấu không đồng bộ.\nCó thể điều khiển thủ công các đơn vị để chiến đấu.\n\nBạn sẽ nhận được phần thưởng dựa trên thành tích của mình vào cuối mỗi tuần và mùa giải.\n\nChỉ áp dụng <color=#ffdb6c>10% HP, ATK và DEF được tăng bởi trang bị và tăng trưởng.\nChi phí Tài Nguyên Triển Khai Cơ Bản cho tàu không tăng theo hạng của chúng.\nHiệu ứng Giới Hạn Nhận DMG Tối Đa 20% được thêm vào các tàu SSR.</color>"
L4_1[1] = L5_1
L4_1[2] = L6_1
L5_1 = {}
L6_1 = "SI_PF_GAUNTLET_ASYNC_NEW_DESC"
L7_1 = "Phần thưởng chiến thắng liên tiếp được áp dụng cho Điểm Chiến Thắng sau các chuỗi chiến thắng.\nĐiểm Chiến Thắng với thưởng chiến thắng liên tiếp không được vượt quá 45 điểm. "
L5_1[1] = L6_1
