L11_1 = "SI_PF_OPTION_GAME_GAUNTLET_NEW_AUTO_TEXT"
L12_1 = "Tự Động Chiến Đấu theo mặc định."
L10_1[1] = L11_1
L10_1[2] = L12_1
L11_1 = {}
L12_1 = "SI_PF_TUTORIAL_TEXUTRE_PVP_ASYNC_1_DESC_01"
L13_1 = "Trong Trận Chiến Chiến Lược, bạn có thể <COLOR=#FFBC00>tham gia trận chiến không đồng bộ</COLOR>.\nTại đây, bạn sẽ chiến đấu chống lại <COLOR=#FFBC00>tiểu đội Phòng Thủ của đối thủ</COLOR>.\nNếu bạn thắng, bạn nhận được Điểm Chiến Thắng; nếu thua, bạn sẽ mất chúng."
L11_1[1] = L12_1
L11_1[2] = L13_1
L12_1 = {}
L13_1 = "SI_PF_TUTORIAL_TEXUTRE_PVP_ASYNC_4_DESC_01"
L14_1 = "Để bắt đầu Trận Chiến Chiến Lược, trước hết phải <COLOR=#FFBC00>thành lập tiểu đội Phòng Thủ</COLOR>.\nTiểu đội Phòng Thủ của bạn sẽ chống lại các cuộc tấn công từ những công ty khác, và sẽ bị ảnh hưởng bởi các hiệu ứng buff và Cấm & Tăng Cường.\nBạn sẽ nhận <COLOR=#FFBC00>Điểm Gauntlet</COLOR> nếu phòng thủ thành công.\nĐiểm Chiến Thắng sẽ bị trừ khi thất bại trong Trận Chiến Phòng Thủ, nhưng sẽ không còn bị trừ sau khi còn một lượng điểm nhất định"
L12_1[1] = L13_1
L12_1[2] = L14_1
L13_1 = {}
L14_1 = "SI_PF_TUTORIAL_TEXUTRE_PVP_ASYNC_4_TEXT_01_1"
L15_1 = "Một số đơn vị của tiểu đội Phòng Thủ bị ẩn với những người dùng khác."
L13_1[1] = L14_1
L13_1[2] = L15_1
L14_1 = {}
L15_1 = "SI_PF_TUTORIAL_TEXUTRE_PVP_FRIENDLY_1_DESC"
L16_1 = "Bấm vào Yêu Cầu để yêu cầu Trận Đấu Giao Hữu."
L14_1[1] = L15_1
L14_1[2] = L16_1
L15_1 = {}
L16_1 = "SI_PF_TUTORIAL_TEXUTRE_PVP_FRIENDLY_2_DESC"
L17_1 = "Nếu người dùng chấp nhận yêu cầu Trận Đấu Giao Hữu, trận đấu sẽ được tiến hành trong thời gian thực.\nBạn sẽ không nhận hay mất Điểm Chiến Thắng trong các Trận Đấu Giao Hữu, cũng như không nhận thêm phần thưởng nào."
L15_1[1] = L16_1
L15_1[2] = L17_1
L16_1 = {}
L17_1 = "SI_PF_TUTORIAL_TEXUTRE_PVP_FRIENDLY_3_DESC"
L18_1 = "Tiểu Đội Tham Gia Cuộc Chiến Xếp Hạng sẽ được sử dụng cho Cuộc Chiến Xếp Hạng và chiến đấu thủ công.\nBạn cũng có thể thành lập Tiểu Đội trong thời gian thực."
L16_1[1] = L17_1
L16_1[2] = L18_1
L17_1 = {}
L18_1 = "SI_PF_TUTORIAL_TEXUTRE_PVP_FRIENDLY_4_DESC"
L19_1 = "Chỉ áp dụng 10% HP, ATK và DEF được tăng bởi trang bị và tăng trưởng.\nChi phí Tài Nguyên Triển Khai Cơ Bản không tăng theo hạng tàu.\nKhông bị ảnh hưởng bởi các quy tắc mùa giải và Cấm & Tăng Cường.\n<COLOR=#FFBC00>Thông số trang bị và Cấm & Tăng Cường có thể ảnh hưởng tùy theo cài đặt tùy chọn.</COLOR>"
L17_1[1] = L18_1
L17_1[2] = L19_1
L18_1 = {}
L19_1 = "SI_PF_TUTORIAL_TEXUTRE_PVP_FRIENDLY_5_DESC"
L20_1 = "Có thể BẬT hoặc TẮT các tùy chọn trong Trận Đấu Giao Hữu.\nĐiều này sẽ phụ thuộc vào cài đặt của người mời.\nCác tùy chọn sẽ được áp dụng sau khi tham gia Trận Đấu Giao Hữu."
