L40_1 = "SI_PF_TUTORIAL_TEXUTRE_BOSS_GUIDE_RAID_DESC_01_01"
L41_1 = "Các đòn tấn công cơ bản của Britra gây sát thương AoE.\nNên nâng cấp tàu của bạn vì Britra sử dụng kỹ năng nhắm đích trực tiếp vào tàu của bạn."
