L9_1 = "SI_PF_TUTORIAL_TEXUTRE_BOSS_GUIDE_RAID_DESC_03_02"
L10_1 = "Khi Bố Ráp bắt đầu, Bức Tường sẽ xuất hiện và duy trì trạng thái phòng ngự.\n<COLOR=#FFBC00>Bức Tường sẽ không nhận DMG khi ở trạng thái phòng ngự.</COLOR>\nTrước khi <COLOR=#FFBC00>thanh năng lượng màu xanh lam đầy, đánh trúng số lần nhất định sẽ phá hủy được phòng ngự của Bức Tường</COLOR>."
L8_1[1] = L9_1
L8_1[2] = L10_1
L9_1 = {}
L10_1 = "SI_PF_TUTORIAL_TEXUTRE_BOSS_GUIDE_RAID_DESC_03_04"
L11_1 = "Kẻ Áp Chế <COLOR=#FFBC00>bắn ra một tia laser gây sát thương cực lớn cho tất cả nhân viên, 35 giây trước khi trận chiến kết thúc</COLOR>.\n※ <COLOR=#FFBC00>Rào Chắn của Nhân Viên bị tia laser phá hủy sẽ bị loại bỏ</COLOR>."
L9_1[1] = L10_1
L9_1[2] = L11_1
