L19_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_S_YG_SORIM_RA"
L20_1 = "Hàng năm, Học Viện Counter Quản Lý tổ chức một lễ hội chào đón tất cả những người bên ngoài. Để nâng cao nhận thức của công chúng về Counter, các buổi biểu diễn hào nhoáng của học sinh với khả năng của họ được tổ chức trong lễ hội.\nMàn trình diễn đáng chú ý của năm nay là 「Đến Nào! Chuyên Gia Giải Cứu Động Vật! 」. Hãy chờ đợi màn trình diễn với thuốc súng của đặc vụ kỳ cựu 「Người Bắt Đầu Phán Xử」 và 「Trung Sĩ Smith」 cứng cỏi.\nMàn trình diễn chính của các thành viên thỏ đã được các học sinh có khả năng điều khiển từ xa tích cực ủng hộ. Họ dường như đã bị cảnh tượng Trung Sĩ Smith ngã gục trên chiến trường trong tư thế trồng cây chuối làm cảm động. "
L18_1[1] = L19_1
L18_1[2] = L20_1
L19_1 = {}
L20_1 = "SI_UNIT_DESC_S_YG_SORIM_RA"
L21_1 = "Sử dụng ASPD tăng liên tục và các đòn tấn công Nâng Cao của cô ấy, cũng như một kỹ năng Tối Thượng để có thể nhanh chóng tấn công tiền tuyến của kẻ thù"
L19_1[1] = L20_1
L19_1[2] = L21_1
L20_1 = {}
L21_1 = "SI_UNIT_SKILL_DESC_S_YG_SORIM_RA_ATTACK_LV1"
L22_1 = "Bắn súng trường và gây sát thương lên mục tiêu ở phía trước."
L20_1[1] = L21_1
L20_1[2] = L22_1
L21_1 = {}
L22_1 = "SI_UNIT_SKILL_DESC_S_YG_SORIM_RA_HYPER_LV1"
L23_1 = "Ném Trung Sĩ Smith lên cao để kêu gọi hỗ trợ vũ trang. Sử dụng súng máy được cung cấp kịp thời để gây sát thương AoE tới khoảng cách 800, 1000 và 1200 về phía trước 3 lần với mỗi khoảng cách, tổng cộng 9 lần."
L21_1[1] = L22_1
