L17_1 = {}
L18_1 = "SI_SKIN_DESC_NKM_UNIT_KNIGHT_C_FLAG_SCHOOL"
L19_1 = "Học Viện Counter có một truyền thuyết.\nĐó là về cô gái bí ẩn và xinh đẹp .\nNghe nói vô số cuốn sách không phù hợp bị cô ấy thu giữ, đã trở thành bộ sưu tập tuyệt vời của cô ấy.\nDù nhiều tin đồn nói rằng phần lớn những cuốn sách này nói về nhân vật chính là một vị hoàng tử, điều này lại chưa bao giờ được chứng minh.\n\n<color=#ffd34c>Tôi chỉ đang khám phá văn hóa của người ngoài hành tinh. Không có động cơ kín đáo nào. Không có. Không bao giờ. Hoàn toàn không.</color>"
L17_1[1] = L18_1
L17_1[2] = L19_1
L18_1 = {}
L19_1 = "SI_SKIN_TITLE_NKM_UNIT_KNIGHT_C_FLAG_SCHOOL"
L20_1 = "Ký Ức Ở Phòng Hướng Dẫn Học Sinh"
L18_1[1] = L19_1
L18_1[2] = L20_1
L19_1 = {}
L20_1 = "SI_SKIN_DESC_NKM_UNIT_C_ADMIN_LEE_SUYEON_SCHOOL"
L21_1 = "Cục Quản Lý Cũ là một tổ chức hoạt động bí mật.\nCác Counter của họ đã cố gắng hết sức với vai trò tương ứng của mình.\nNhưng tài năng của các Counter luôn tỏa sáng dù họ đi tới đâu.\nÁt chủ bài cũng không ngoại lệ.\n\n<color=#ffd34c>Ôi, xin lỗi, xin lỗi. Hôm nay tôi đã hứa sẽ hỗ trợ buổi tập của câu lạc bộ bóng chày. Câu lạc bộ bóng đá sẽ là tuần tới! Tôi hứa mà!</color>"
L19_1[1] = L20_1
