L48_1 = "SI_ITEM_MISC_DESC_IMI_ITEM_MISC_PACKAGE_GREMORY_BAR_ITEM_BOX"
L49_1 = "Một hộp đầy đủ các thành phần pha chế cocktail.\nTạo ra Bột Thánh, Nước Tham Lam và Trái Cây Vị Mạnh,\nCó thể nhận được 2 thứ mỗi loại.\nVật phẩm này sẽ bị xóa khi sự kiện kết thúc."
L47_1[1] = L48_1
L47_1[2] = L49_1
L48_1 = {}
L49_1 = "SI_ITEM_MISC_DESC_IMI_ITEM_MISC_RANDOM_GREMORY_BAR_2"
L50_1 = "Một loại cocktail tạo ra các lớp màu như cầu vồng nếu được để yên sau khi pha chế một lúc.\nHương vị bí ẩn của nó khiến bạn phải chắp tay cầu nguyện cho chính mình.\n(Bột Thánh + Nước Tham Lam + Khuấy Trộn)\nCó thể nhận được Đánh Giá với xác suất nhất định.\nVật phẩm này sẽ bị xóa khi sự kiện kết thúc."
L48_1[1] = L49_1
L48_1[2] = L50_1
L49_1 = {}
L50_1 = "SI_ITEM_MISC_DESC_IMI_ITEM_MISC_RANDOM_GREMORY_BAR_3"
L51_1 = "Một ly cocktail màu xanh lam ngọc sống động, có vị ngọt tê lưỡi.\nĐó là loại cocktail yêu thích của Momo.\n(Trái Cây Vị Mạnh + Bột Thánh + Khuấy Trộn)\nCó thể nhận được Lõi S-APT hoặc Lõi Binh Lính với xác suất nhất định.\nVật phẩm này sẽ bị xóa khi sự kiện kết thúc."
L49_1[1] = L50_1
L49_1[2] = L51_1
L50_1 = {}
L51_1 = "SI_ITEM_MISC_DESC_IMI_ITEM_MISC_RANDOM_GREMORY_BAR_4"
L52_1 = "Gremory đã phát triển loại cocktail này để tự làm mình say.\nNó đủ mạnh để khiến người bình thường gục sau vài ly.\n(Nước Tham Lam + Trái Cây Vị Mạnh + Khuấy Trộn)\nCó thể nhận được Lõi S-APT hoặc Lõi Lính Thiết Giáp với xác suất nhất định.\nVật phẩm này sẽ bị xóa khi sự kiện kết thúc."
