L2_1[2] = L4_1
L3_1 = {}
L4_1 = "SI_ITEM_MISC_DESC_IMI_ITEM_MISC_RANDOM_GREMORY_BAR_7"
L5_1 = "Một ly cocktail màu hồng xinh xắn.\nHương thơm đậm đà và vị ngọt dẻo không thể cưỡng lại được.\n(Trái Cây Vị Mạnh + Bột Thánh + Lắc)\nCó thể nhận được Phiếu [COMP Tàu] hoặc Sơ Đồ Thiết Kế Tàu Đặc Biệt với xác suất nhất định.\nVật phẩm này sẽ bị xóa khi sự kiện kết thúc."
