L2_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_GREMORY_1_INTERLUDE_1"
L3_1 = "Mọi người trong Hội Trừ Tà học cách xác định ác ma. Tuy nhiên, tôi chưa bao giờ thực sự ứng dụng kiến thức đó... Tôi có thể làm được không?"
L1_1[1] = L2_1
L1_1[2] = L3_1
L2_1 = {}
L3_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_GREMORY_1_INTERLUDE_2"
L4_1 = "Tất cả ác ma đều không có gì tốt đẹp. Tôi không thể để bị đánh lừa bởi vẻ ngoài của chúng. Con ác ma này trông rất yếu, nhưng... nó hẳn là một trò lừa!"
