L2_1[2] = L4_1
L3_1 = {}
L4_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_GREMORY_1_INTERLUDE_3"
L5_1 = "Thế giới trần tục chứa đầy những tạp chất có thể làm vấy bẩn tâm hồn chúng ta. Dù vậy, đúng là thế giới này rất thú vị."
