L10_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_GREMORY_2_INTERLUDE_1"
L11_1 = "Tôi đến đây chưa lâu, nhưng tôi cảm thấy như mình đã ở đây từ lâu lắm. Tất nhiên, tôi biết mình không thể ở lại đây nữa."
L9_1[1] = L10_1
L9_1[2] = L11_1
L10_1 = {}
L11_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_GREMORY_2_INTERLUDE_2"
L12_1 = "Tôi tự hứa rằng tôi sẽ không từ bỏ sứ mệnh thiêng liêng của mình. Nhưng tại sao tôi cứ không ngừng do dự? Có lẽ tôi đã bị con Ác Ma lừa gạt rồi."
