L13_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_OZ_1_INTERLUDE_1"
L14_1 = "Trả thù! Đó là bài hát của nàng tiên cá đã át đi tiếng thì thầm của lý trí."
