L14_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_OZ_1_1"
L15_1 = "Tôi đã xem tin tức và đọc các tờ báo nhiều lần trong ngày để xem chuyện gì đã xảy ra với cậu. Nhưng khi mỗi ngày lại càng có nhiều biến cố, tin tức về cậu lại càng ít dần đi. Tôi nghĩ về cậu hàng ngày để mình sẽ không quên."
L13_1[1] = L14_1
L13_1[2] = L15_1
