L15_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_OZ_1_INTERLUDE_2"
L16_1 = "Tôi đã mơ gặp lại cậu. Nhưng... Có lẽ tôi chưa sẵn sàng để thấy cậu thay đổi như vậy. Cuối cùng, tôi vẫn đối xử với cậu quá tệ."
L14_1[1] = L15_1
