L5_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_OZ_S_RUNNER@AB_UI_UNIT_VOICE_NKM_UNIT_OZ_S_RUNNER_LOBBY_TOUCH_NORMAL_2"
L6_1 = "Mấy ngày này tôi thích ra ngoài chạy bộ vào ban đêm. Chạy trên đỉnh các tòa nhà chọc trời khiến tôi cảm thấy thực sự phấn khích."
