L32_1 = "Để điều khiển cần đoàn kết các thành viên thành một khối, để đạt được sự hòa hợp hoàn hảo. Nếu vậy, chẳng phải sẽ dễ dàng hơn nếu mỗi thành viên không còn ý chí của chính mình sao?"
L30_1[1] = L31_1
L30_1[2] = L32_1
L31_1 = {}
L32_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_HARMONY_CA_CONDUCT@AB_UI_UNIT_VOICE_NKM_UNIT_HARMONY_CA_CONDUCT_LOBBY_TOUCH_NORMAL_2"
L33_1 = "Đối với tôi, thế giới tối đen như mực này là dàn giao hưởng các nhạc cụ, vạn vật đều ca lên một giai điệu độc đáo. Có thể diễn tấu chúng là một trải nghiệm cực kỳ thú vị ... và cũng vô cùng dễ dàng."
L31_1[1] = L32_1
L31_1[2] = L33_1
L32_1 = {}
L33_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_HARMONY_CA_CONDUCT@AB_UI_UNIT_VOICE_NKM_UNIT_HARMONY_CA_CONDUCT_LOBBY_TOUCH_NORMAL_3"
L34_1 = "Hơi thở, nhịp tim và tiếng bước chân của mọi người... Tôi có thể cảm nhận được sự thù địch từ những người ở xung quanh ngài. Mặc dù, trừ một số trường hợp ngoại lệ, đó đơn giản chỉ là tiếng ồn thôi."
L32_1[1] = L33_1
L32_1[2] = L34_1
L33_1 = {}
L34_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_HARMONY_CA_CONDUCT@AB_UI_UNIT_VOICE_NKM_UNIT_HARMONY_CA_CONDUCT_LOBBY_TOUCH_NORMAL_4"
L35_1 = "Lyudmila, phải không? Nếu có chuyện gì, cô ấy sẽ giống một con quái vật được huấn luyện hơn là một con chó săn... Phư phư, hãy giới thiệu cô ấy cho tôi nếu một ngày ngài đã quá mệt với cô ấy. Tôi chắc rằng cô ấy sẽ trở thành một thành viên xuất sắc."
L33_1[1] = L34_1
L33_1[2] = L35_1
L34_1 = {}
