L12_1 = "SI_SKIN_DESC_NKM_UNIT_REPLACER_CA_QUEEN_CHUSEOK"
L13_1 = "Lang thang trên con phố đêm, một quán rượu vắng luôn sẵn sàng phục vụ bạn.\nSau chiếc đèn lồng nhỏ và tối mờ, một tiếng vo ve yếu ớt vang lên trong quán rượu.\nNâng rèm và bước vào trong để tránh những cơn gió heo may.\nMột người phụ nữ cô độc không có vệ sĩ tiến tới, tự rót cho mình một ly đầy ánh trăng lấp lánh.\n\n<color=#ffd34c>Dù sẽ trở thành kẻ địch khi rạng đông, lúc này, hãy cùng uống với tôi trước khi trời đêm tan biến.</color>"
L11_1[1] = L12_1
L11_1[2] = L13_1
