L20_1[2] = L22_1
L21_1 = {}
L22_1 = "SI_ITEM_DESC_IQI_EQUIP_SOLDIER_WEAPON_2563141"
L23_1 = "Súng trường đột kích tràn ngập năng lượng của thiên nhiên và sự sống vô hạn.\nNhững dây leo của nó vẫn tái sinh cho dù bị cắt đứt bao nhiêu lần.\n\nBan sức mạnh tấn công đáng kinh ngạc cho Binh Lính."
L21_1[1] = L22_1
L21_1[2] = L23_1
L22_1 = {}
L23_1 = "SI_ITEM_DESC_IQI_EQUIP_SOLDIER_WEAPON_2663141"
L24_1 = "Chiếc súng trường đột kích tràn ngập năng lượng núi lửa phun trào bất tận.\nNhiệt lượng tỏa ra từ nó đủ để làm tan chảy kẻ thù.\n\nBan sức mạnh tấn công đáng kinh ngạc cho Binh Lính."
