L39_1 = {}
L40_1 = "SI_EPISODE_EPISODE_EVENT_FALLEN"
L41_1 = "Fallen Hawk"
L39_1[1] = L40_1
L39_1[2] = L41_1
L40_1 = {}
L41_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_FALLEN_1_PROLOGUE"
L42_1 = "Ngày nọ, một người phụ nữ đến gặp một tổ chuyên giải quyết rắc rối. Người phụ nữ yêu cầu họ thực hiện mong muốn của mình."
L40_1[1] = L41_1
L40_1[2] = L42_1
L41_1 = {}
L42_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_FALLEN_1_INTERLUDE_3"
L43_1 = "Người phụ nữ không thể đánh bại con sói. Tất cả những gì cô ấy làm là cố hết sức đấu với con sói mạnh mẽ ấy. Cô ấy đã không đủ sáng suốt."
L41_1[1] = L42_1
L41_1[2] = L43_1
L42_1 = {}
L43_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_FALLEN_1_INTERLUDE_2"
L44_1 = "Người chuyên giải quyết rắc rối đã không đổ lỗi cho người phụ nữ tham lam. Tất cả những gì cô ấy làm là đứng ngoài theo dõi."
L42_1[1] = L43_1
L42_1[2] = L44_1
L43_1 = {}
L44_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_FALLEN_1_INTERLUDE_1"
L45_1 = "Người chuyên giải quyết rắc rối đã nhìn thấy trái tim đen tối ở người phụ nữ, nhưng vẫn quyết định hoàn thành điều ước đó. Tất cả chỉ vì nó trông rất thú vị."
L43_1[1] = L44_1
L43_1[2] = L45_1
L44_1 = {}
L45_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_FALLEN_1_EPILOGUE"
L46_1 = "Nhưng Người chuyên giải quyết rắc rối đã tạo được tiếng vang lớn khi ghi lại cuộc đời bất hạnh của người phụ nữ.\nBạn đang hỏi tại sao câu chuyện lại kết thúc như vậy ư? Hừm, cuối cùng thì người thông minh nhất sẽ là người làm được tất cả."
L44_1[1] = L45_1
L44_1[2] = L46_1
L45_1 = {}
L46_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_FALLEN_1_3"
L47_1 = "... Người phụ nữ đối đầu với một con sói mạnh mẽ ngáng đường cô ấy.\nChà, liệu cô ấy có vượt qua được không?"
L45_1[1] = L46_1
L45_1[2] = L47_1
L46_1 = {}
L47_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_FALLEN_1_2"
L48_1 = "Người phụ nữ lúc đầu rất hài lòng, nhưng cô ấy muốn nhiều hơn khi nhận ra rằng lòng tham của cô ấy không được thỏa mãn."
L46_1[1] = L47_1
L46_1[2] = L48_1
L47_1 = {}
L48_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_FALLEN_1_1"
L49_1 = "Người chuyên giải quyết rắc rối đã phái đi con tốt giống dơi của mình để xử lý tất cả đối thủ của người phụ nữ đó."
L47_1[1] = L48_1
L47_1[2] = L49_1
