L5_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EP9_ACT2_INTERLUDE_2"
L6_1 = "Người bị bỏ lại phía sau, và một người chọn ở lại."
L4_1[1] = L5_1
L4_1[2] = L6_1
