L6_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EP9_ACT4_INTERLUDE_1"
L7_1 = "Nếu ngài liên hệ với chúng tôi trước, chúng tôi sẽ rất biết ơn, Giáo Sư."
L5_1[1] = L6_1
L5_1[2] = L7_1
L6_1 = {}
L7_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EP9_ACT4_INTERLUDE_2"
L8_1 = "Những pháp sư ma mãnh, ma cà rồng thô tục, cả những kẻ háu đói tham ăn. Đốt cháy, đốt cháy, tất cả sẽ bị đốt cháy. Dưới ngọn lửa của Bạo Chúa Phương Bắc."
L6_1[1] = L7_1
L6_1[2] = L8_1
L7_1 = {}
L8_1 = "SI_EPISODE_EPISODE_DESC_NKM_MAIN_BATTLE_EP9_1_1"
L9_1 = "Người thi sĩ đã để lại một lời khuyên đáng nhớ.\nKhi ở Cung Điện Trung Tâm, đừng có dính líu với những người lạ."
L7_1[1] = L8_1
L7_1[2] = L9_1
L8_1 = {}
L9_1 = "SI_EPISODE_EPISODE_DESC_NKM_MAIN_BATTLE_EP9_1_2"
L10_1 = "Làm tổn thương nô lệ cũng giống như làm hỏng tài sản của người khác."
L8_1[1] = L9_1
L8_1[2] = L10_1
L9_1 = {}
L10_1 = "SI_EPISODE_EPISODE_DESC_NKM_MAIN_BATTLE_EP9_1_3"
L11_1 = "Chiến thắng không đáng để ăn mừng nếu không có kẻ thù xứng đáng."
L9_1[1] = L10_1
L9_1[2] = L11_1
L10_1 = {}
L11_1 = "SI_EPISODE_EPISODE_DESC_NKM_MAIN_BATTLE_EP9_1_4"
L12_1 = "Người đội vương miện phải được ấn định. Mối đe dọa của Chúa Quỷ không còn là một câu chuyện kinh dị để dọa nạt trẻ con nữa."
L10_1[1] = L11_1
L10_1[2] = L12_1
L11_1 = {}
L12_1 = "SI_EPISODE_EPISODE_DESC_NKM_MAIN_BATTLE_EP9_2_1"
L13_1 = "Tìm ra những người tài năng vừa khéo léo vừa đáng tin cậy lúc nào cũng khó."
L11_1[1] = L12_1
L11_1[2] = L13_1
L12_1 = {}
L13_1 = "SI_EPISODE_EPISODE_DESC_NKM_MAIN_BATTLE_EP9_2_2"
L14_1 = "Một tổ chức mất đi cốt lõi của mình sẽ sụp đổ."
L12_1[1] = L13_1
L12_1[2] = L14_1
L13_1 = {}
L14_1 = "SI_EPISODE_EPISODE_DESC_NKM_MAIN_BATTLE_EP9_2_3"
L15_1 = "Bây giờ có lẽ đã quen với cái tên Hội rồi nhỉ. Tuy nhiên, nó có thể đã có một cái tên kỳ lạ hơn nhiều trong quá khứ. Còn Lemuria thì sao?"
L13_1[1] = L14_1
L13_1[2] = L15_1
L14_1 = {}
L15_1 = "SI_EPISODE_EPISODE_DESC_NKM_MAIN_BATTLE_EP9_2_4"
L16_1 = "Quần chúng vẫn đang tò mò về việc tại sao những người xuất hiện và biến mất trong Cuộc Chiến Đại Thanh Lọc lại có thể đạt được chiến thắng. Chà, tất cả chỉ trừ một người.\nĐối với họ, Maria Antonov là một nữ anh hùng sẽ đảm bảo chiến thắng."
L14_1[1] = L15_1
L14_1[2] = L16_1
L15_1 = {}
L16_1 = "SI_EPISODE_EPISODE_DESC_NKM_MAIN_BATTLE_EP9_3_1"
L17_1 = "Vũ khí là không thể thiếu để chiến đấu."
L15_1[1] = L16_1
