L2_1 = "SI_SKIN_DESC_NKM_UNIT_HARMONY_C_BASS_SUMMER"
L3_1 = "Bản tính của loài mèo là thích tắm nắng đúng không?\nThỉnh thoảng dành một ngày để lười biếng cũng không sao. Nhưng đừng mất cảnh giác. Tao luôn sẵn sàng vuốt ve nếu mày đến gần.\n\n<color=#ffd34c>Mày định nằm bên cạnh tao sao? Uhu huu♪. Oh, mày thật ngốc nghếch♪.</color>"
L1_1[1] = L2_1
L1_1[2] = L3_1
L2_1 = {}
L3_1 = "SI_SKIN_DESC_NKM_UNIT_HARMONY_C_VIOLIN_SUMMER"
L4_1 = "Một resort mang đậm phong cách mùa hè.\nỞ đó, một người hát rong lang thang sáng sủa đã xuất hiện. Các kỹ năng của cô ấy thật hoàn hảo, bài hát cũng đầy cảm xúc. Hãy đến ngay bây giờ để tận hưởng màn trình diễn khiến toàn bộ du khách phải sững sờ nhé.\n\n <color=#ffd34c> Đó có phải là anh không, ngài quản lý? Hãy đến sắp xếp thiết bị cho tôi đi.</color>"
L2_1[1] = L3_1
L2_1[2] = L4_1
