L25_1 = "SI_EPISODE_DUNGEON_NAME_NKM_DUNGEON_EVENT_NIGHTMARE_3_3"
L26_1 = "Đêm Nhiều Mây"
L24_1[1] = L25_1
L24_1[2] = L26_1
L25_1 = {}
L26_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_NIGHTMARE_1_1"
L27_1 = "Bạn đã bao giờ nhìn thấy đôi mắt phát sáng trong bóng tối chưa?\nHay bạn đã bao giờ tự hỏi sinh vật bay xung quanh với đôi mắt phát sáng là cái gì trong ác mộng của mọi người?"
L25_1[1] = L26_1
L25_1[2] = L27_1
L26_1 = {}
L27_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_NIGHTMARE_1_1_HM"
L28_1 = "Bạn có gặp ác mộng hàng đêm không? Tôi hy vọng đây sẽ là ác mộng cuối cùng của bạn."
L26_1[1] = L27_1
L26_1[2] = L28_1
L27_1 = {}
L28_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_NIGHTMARE_1_2"
L29_1 = "Tôi từng là người chăm sóc con bé, nhưng bây giờ con bé là người chăm sóc tôi.\nĐó không phải là một cảm giác tồi tệ, vì vậy tôi đã nhắm mắt và chấp nhận nó."
L27_1[1] = L28_1
L27_1[2] = L29_1
L28_1 = {}
L29_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_NIGHTMARE_1_INTERLUDE_1"
L30_1 = "Những giấc mơ có tiềm năng vô hạn. Trừ khi, dĩ nhiên, có ai đó xuất hiện và can thiệp ..."
L28_1[1] = L29_1
L28_1[2] = L30_1
L29_1 = {}
L30_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_NIGHTMARE_1_INTERLUDE_2"
L31_1 = "Ôi trời ... Những đứa trẻ ngỗ nghịch cần bị trừng phạt.Không phải như vậy sẽ làm cho thế giới trở nên tốt đẹp hơn sao?"
L29_1[1] = L30_1
L29_1[2] = L31_1
L30_1 = {}
L31_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_NIGHTMARE_1_INTERLUDE_3"
L32_1 = "Giấc mơ đã bay đi trở lại như ác mộng.\n Tôi không thể ngừng chìm vào giấc ngủ, cho dù tôi đã cố gắng sống với thực tế và chịu đựng nó ra sao."
L30_1[1] = L31_1
L30_1[2] = L32_1
L31_1 = {}
L32_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_NIGHTMARE_1_INTERLUDE_4"
L33_1 = "Tôi ngay lập tức bị câu chuyện như mơ đưa về thực tại.\nTôi không quá chán nản vì tôi đã dành nhiều thời gian tỉnh hơn là mơ."
L31_1[1] = L32_1
L31_1[2] = L33_1
L32_1 = {}
L33_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_NIGHTMARE_2_1"
L34_1 = "Thoát khỏi ác mộng? Tin đồn càng khó tin thì kỳ vọng càng cao. Tôi chỉ hy vọng ... tôi sẽ không thất vọng."
L32_1[1] = L33_1
L32_1[2] = L34_1
L33_1 = {}
L34_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_NIGHTMARE_2_1_HM"
L35_1 = "Tôi không thể làm ô uế danh tiếng của Sếp Haven! Hãy hoàn thành công việc và quay trở lại <color=#ffd34c>Havenland</color> thôi."
L33_1[1] = L34_1
L33_1[2] = L35_1
L34_1 = {}
L35_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_NIGHTMARE_2_2"
L36_1 = "Hãy thực tế đi. Nhóc còn ảo tưởng bao lâu nữa?"
L34_1[1] = L35_1
L34_1[2] = L36_1
L35_1 = {}
L36_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_NIGHTMARE_2_INTERLUDE_1"
L37_1 = "Tôi chưa bao giờ thấy bất cứ điều gì thế này. Ý cô là tôi không cần phải tìm họ và họ sẽ đến với tôi ...? \n Glinda là thiên tài."
L35_1[1] = L36_1
L35_1[2] = L37_1
L36_1 = {}
L37_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_NIGHTMARE_2_INTERLUDE_2"
L38_1 = "Tất cả đều siêu thực đến mức tôi nghĩ rằng mình đang mơ.\nThậm chí là chưa bao giờ trong những giấc mơ hoang đường nhất của tôi... tôi đã tưởng tượng rằng thực tế còn tồi tệ hơn ác mộng."
L36_1[1] = L37_1
L36_1[2] = L38_1
L37_1 = {}
L38_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_NIGHTMARE_2_INTERLUDE_3"
L39_1 = "Tôi nhớ tất cả những gì cô đã nói với tôi."
L37_1[1] = L38_1
L37_1[2] = L39_1
L38_1 = {}
L39_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_NIGHTMARE_2_INTERLUDE_4"
L40_1 = "Khi chiếc mặt nạ được gỡ bỏ, một khuôn mặt quen thuộc xuất hiện, khuôn mặt mà tôi đã nhìn thấy hàng đêm."
L38_1[1] = L39_1
L38_1[2] = L40_1
L39_1 = {}
L40_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_NIGHTMARE_3_1"
L41_1 = "Tôi hầu như không mở được đôi mắt đầy máu của mình. Thực tế trước mắt tôi giống như một giấc mơ hơn cả giấc mơ."
L39_1[1] = L40_1
L39_1[2] = L41_1
L40_1 = {}
L41_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_NIGHTMARE_3_1_HM"
L42_1 = "Một cơn ác mộng cũ in sâu vào tâm trí và đáng sợ như những đầm lầy. Nó liên tục bò lên và ăn tươi nuốt sống các cô, rồi cuối cùng sẽ tàn phá chính thực tại này."
L40_1[1] = L41_1
L40_1[2] = L42_1
L41_1 = {}
L42_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_NIGHTMARE_3_2"
L43_1 = "Ta sẽ không để các cô đánh cắp thành quả của ta. Không đời nào. \nÁc mộng? Đó chẳng là gì so với những điều ta đã phải trải qua để có được chúng."
L41_1[1] = L42_1
L41_1[2] = L43_1
L42_1 = {}
L43_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_NIGHTMARE_3_3"
L44_1 = "Không còn, ác mộng nữa rồi. Hãy quay trở lại cuộc sống đáng quý với bạn bè của mình thôi."
L42_1[1] = L43_1
L42_1[2] = L44_1
