L45_1 = {}
L46_1 = "SI_EPISODE_DESC_1_MAINSTREAM_EP_1"
L47_1 = "Counter tân binh ở Tiểu Đội Fenrir được trao một nhiệm vụ bất ngờ vào ngày đầu tiên đi làm ở công ty. Cùng với tổng tư lệnh vừa trở lại sau một thời gian dài vắng bóng, và một thành viên lâu năm."
L45_1[1] = L46_1
L45_1[2] = L47_1
L46_1 = {}
L47_1 = "SI_EPISODE_DESC_1_MAINSTREAM_EP_2"
L48_1 = "Yoo Mina nghỉ một buổi và tới bệnh viện khi Thảm Họa Ăn Mòn càn quét toàn bộ thành phố. Tuy nhiên, ẩn sau thảm họa đó là một cuộc xung đột mới."
L46_1[1] = L47_1
L46_1[2] = L48_1
L47_1 = {}
L48_1 = "SI_EPISODE_DESC_1_MAINSTREAM_EP_3"
L49_1 = "Công Ty Coffin nhận được một yêu cầu từ quân đội. Khi cuộc đối đầu với Replacer Syndicate ngày càng căng thẳng, Yoo Mina gặp lại một người bạn cũ."
L47_1[1] = L48_1
L47_1[2] = L49_1
L48_1 = {}
L49_1 = "SI_EPISODE_DESC_1_MAINSTREAM_EP_4"
L50_1 = "Tác Chiến Terraside, bắt đầu. Trong khi toàn thế giới chao đảo vì những mưu đồ của Replacer Syndicate, Yoo Mina đã bị một người bất ngờ chặn đường."
L48_1[1] = L49_1
L48_1[2] = L50_1
L49_1 = {}
L50_1 = "SI_EPISODE_DESC_1_MAINSTREAM_EP_5"
L51_1 = "Đã đến lúc phải kết thúc những gì được bắt đầu với câu hỏi nhức nhối trong tâm trí. Mọi người chung tay chống lại Replacer Syndicate vì những mục tiêu riêng của mình."
L49_1[1] = L50_1
L49_1[2] = L51_1
L50_1 = {}
L51_1 = "SI_EPISODE_DESC_1_MAINSTREAM_EP_6"
L52_1 = "Khi thảm họa mà vụ việc Replacer Syndicate gây ra bắt đầu lắng lại, thế giới có vẻ như sắp trở lại trạng thái bình thường. Trong lúc đó, Yoo Mina, một nhân viên của Công Ty Coffin, nhận được một lời đề nghị bất ngờ."
L50_1[1] = L51_1
L50_1[2] = L52_1
