L1_1[2] = L3_1
L2_1 = {}
L3_1 = "SI_EPISODE_DESC_1_MAINSTREAM_EP_8"
L4_1 = "Đại Tá Walker và đồng nghiệp mới của anh ấy đã tới thăm John Mason. Họ đã không thể không thể hòa hợp trong khi tìm kiếm Lò Phản Ứng Cấp Nova, rồi bị cuốn vào một âm mưu khổng lồ."
