L27_1 = "SI_EPISODE_DESC_1_SS_SPRING"
L28_1 = "Đội Hỗ Trợ Chính Thức tìm thấy ngân hàng dữ liệu trong một chiến hạm đa chiều bị bỏ hoang. Ở đó có hồ sơ cũ về một số sự kiện ở trường."
