L30_1 = "SI_PF_TUTORIAL_TEXUTRE_DIVE_SEARCH_2_DESC_V2"
L31_1 = "<COLOR=#FFBC00>Bằng cách chọn Càn Quét, bạn có thể ngay lập tức chiến đấu chống lại Lõi Mòn của tọa độ khám phá tương ứng.</color>\nNếu bạn Quét thành công, bạn có thể nhận được phần thưởng Lặn cùng với phần thưởng Càn Quét."
L29_1[1] = L30_1
L29_1[2] = L31_1
L30_1 = {}
L31_1 = "SI_PF_TUTORIAL_TEXUTRE_UNIT_LIMITBREAK_3_DESC_VER2"
L32_1 = "Nhân viên có thể được <COLOR=#FFBC00>Hợp Nhất Giới Hạn</COLOR> bằng Lõi Hợp Nhất hoặc Mảnh Lõi Hợp Nhất.\n<COLOR=#FFBC00>Hợp Nhất Giới Hạn</COLOR> mỗi khi được thực hiện gia tăng <COLOR=#FFBC00>Cấp Độ Tối Đa thêm 2 cấp </COLOR>và <COLOR=#FFBC00>tỉ lệ tăng trưởng thông số thêm 2%.</COLOR>\n<COLOR=#FFBC00>Hợp Nhất Giới Hạn</COLOR>có thể được thực hiện <COLOR=#FFBC00>tối đa 5 lần</COLOR>."
L30_1[1] = L31_1
L30_1[2] = L32_1
L31_1 = {}
L32_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_C_HB_GAEUN_RA"
L33_1 = "Gaeun có lẽ đã bắt đầu phát sóng vì mong muốn gặp được ai đó đặc biệt. Tuy nhiên, Gaeun của HRT Berry dần dần đã bộc lộ năng khiếu làm trưởng nhóm thông qua những buổi phát sóng của mình.\n\nCô ấy đã gây dựng được uy tín để khiến các thành viên có tính cách mạnh mẽ trong nhóm phải tin phục, ví dụ như sự tự tin thái quá của Lumi, cử chỉ bỗ bã của Bomi và kinh nghiệm live stream dày dạn của Miya.\n\nNgay cả khi cô ấy không phải là trung tâm của nhóm, khả năng làm thủ lĩnh của Gaeun vẫn giúp phát huy sở trường tốt nhất của từng thành viên, cả khi phát sóng và khi trên sân khấu.\nKết quả là, các công ty giải trí lớn đã công nhận HRT Berry là nhóm nhạc thần tượng mới nổi.\n\nGaeun hiện rất được chú ý và có thể tươi cười thoải mái với người hâm mộ, cho dù thực tế cô ấy vẫn không giỏi bằng các thành viên khác về khoản nhảy múa và ca hát.\n\nBởi bây giờ cô ấy hiểu rằng người Thầy, người hâm mộ lớn nhất của mình sẽ luôn ở đâu đó ủng hộ cô ấy."
L31_1[1] = L32_1
L31_1[2] = L33_1
L32_1 = {}
L33_1 = "SI_ITEM_MISC_DESC_IMI_ITEM_MISC_CHOICE_EQUIP_GLOBAL_FIRST_T7_SSR_RAID1_G_CN"
