L14_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_ESPR2_ACT1_INTERLUDE3"
L15_1 = "Đã có nhiều nỗ lực để khám phá Hồ. Cho dù đó là thơ ca, văn học, kiến trúc, tâm lý học hay thiên văn học, Hội đã tham gia vào vô số lĩnh vực học thuật. Các trường đã đạt được tiến bộ theo thời gian được tách thành các tổ chức nhỏ hơn có tên \"Khoa\"."
L13_1[1] = L14_1
L13_1[2] = L15_1
L14_1 = {}
L15_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_ESPR2_ACT2_INTERLUDE1"
L16_1 = "Du lịch là cách dễ nhất và thú vị nhất để thay đổi tư duy."
L14_1[1] = L15_1
L14_1[2] = L16_1
L15_1 = {}
L16_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_ESPR2_2_2"
L17_1 = "Hội đã sử dụng khảo cổ học để khám phá dấu vết lịch sử của Hồ. Sinh học phát sinh để điều tra các dạng sống kỳ lạ ẩn nấp ở đó, chấp nhận rủi ro và bước vào một thế giới ẩn giấu bí mật. Tương tự như vậy, tất cả các khoa khác phát sinh như là kết quả của sự cần thiết."
L15_1[1] = L16_1
L15_1[2] = L17_1
L16_1 = {}
L17_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_ESPR2_ACT2_INTERLUDE3"
L18_1 = "Gia đình MacCready sở hữu quyền lực tuyệt đối với Hội."
L16_1[1] = L17_1
L16_1[2] = L18_1
L17_1 = {}
L18_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_ESPR2_ACT3_INTERLUDE1"
L19_1 = "[Đến Thủ Lĩnh Pendragon]\nNhiều sự cố xảy ra trên toàn cầu. Bị nghi ngờ là có liên kết chặt chẽ với tai họa Loại Q. Yêu cầu hỗ trợ với sự hợp tác từ Cục Quản Lý.\nNữ hoàng muôn năm."
L17_1[1] = L18_1
L17_1[2] = L19_1
L18_1 = {}
L19_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_ESPR2_ACT3_INTERLUDE2"
L20_1 = "Sức nặng chôn vùi trái tim dưới lòng đất. Lực hút kéo chúng ta xuống hố sâu nhất.\nTất cả đều bắt nguồn từ lòng tự ái."
L18_1[1] = L19_1
L18_1[2] = L20_1
L19_1 = {}
L20_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_ESPR2_3_1"
L21_1 = "<color=#ffd34c>*Các đơn vị Counter bị hư hại bởi các đơn vị Prydwen sẽ bị dính kỹ năng Phong ấn trong một khoảng thời gian nhất định.</color>\n\nNgười ngoài hành tinh man rợ. Người ngoài hôi hám. Con khỉ bẩn thỉu.\nHãy coi chừng những người không đến từ lãnh địa. Họ ghê tởm truyền thống của chúng ta và coi thường thái độ của chúng ta."
L19_1[1] = L20_1
L19_1[2] = L21_1
L20_1 = {}
L21_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_ESPR2_3_2"
L22_1 = "Trách móc. Ăn năn. Hối hận. Tự trách bản thân cho đến khi không thể chịu đựng được sự tồn tại của chính mình, mới chấm dứt tất cả. Nhìn lại, đó là cách duy nhất tôi được nuôi dưỡng."
L20_1[1] = L21_1
L20_1[2] = L22_1
L21_1 = {}
L22_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_ESPR2_ACT4_INTERLUDE1"
L23_1 = "Hãy luôn biết ơn những quyền và nghĩa vụ mà bạn được trao. Trân trọng chúng."
L21_1[1] = L22_1
L21_1[2] = L23_1
L22_1 = {}
L23_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_ESPR2_4_1"
L24_1 = "Tất cả những điều này là dành cho Regina. Nhưng cô ấy sẽ không tin tôi ngay cả khi tôi nói với cô ấy. Ừ, cô ấy không tin ai cả, kể cả tôi! Hiện tại, tôi sẽ giữ im lặng về điều này. Mọi thứ sẽ thú vị hơn theo cách đó"
L22_1[1] = L23_1
L22_1[2] = L24_1
L23_1 = {}
L24_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_ESPR2_ACT4_INTERLUDE2"
L25_1 = "Vì chúng tôi không thể hiểu được phương tiện của đấng thiêng liêng, ôi chúa tể toàn năng. Xin hãy yên lặng. Chúng ta sẽ mang lại sự cứu rỗi cho chính mình."
L23_1[1] = L24_1
L23_1[2] = L25_1
L24_1 = {}
L25_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_ESPR2_ACT5_INTERLUDE2"
L26_1 = "Nếu thượng đế tồn tại, thì cái gì nằm ở phía bên kia? Lực lượng tối thượng, ghê tởm đẩy chúng ta đến chỗ diệt vong.\nÔi chúa nhân từ, xin hãy để nỗi kinh hoàng của chúng tôi tồn tại như những gì chúng tôi tưởng tượng."
L24_1[1] = L25_1
