L39_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ESPR_C_SNIPER@AB_UI_UNIT_VOICE_NKM_UNIT_ESPR_C_SNIPER_LOBBY_TOUCH_NORMAL_1"
L40_1 = "Con mắt này... Nó được xử lý bằng ma thuật, một loại thiết bị ghi hình đơn sơ. Bây giờ, tôi sử dụng nó để lưu trữ những ký ức quý giá thay vì mục đích ban đầu của nó."
L38_1[1] = L39_1
L38_1[2] = L40_1
L39_1 = {}
L40_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ESPR_C_SNIPER@AB_UI_UNIT_VOICE_NKM_UNIT_ESPR_C_SNIPER_LOBBY_TOUCH_NORMAL_2"
L41_1 = "Tu viện chẳng bao giờ là một nơi đông đúc cả. Với vài người, họ thậm chí còn tới đó để gặm nhấm sự cô đơn. Tôi ư? Mm... Tôi đã quen với nó rồi. Tôi nghĩ tôi thích nó bây giờ hơn, khi nó đã sống động hơn."
L39_1[1] = L40_1
L39_1[2] = L41_1
L40_1 = {}
L41_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ESPR_C_SNIPER@AB_UI_UNIT_VOICE_NKM_UNIT_ESPR_C_SNIPER_LOBBY_TOUCH_NORMAL_3"
L42_1 = "Fuu fuu, tôi yêu khuôn mặt của ngài khi tỏ ra tập trung. Oh, đừng để ý đến tôi. ngài hấp dẫn nhất khi là chính mình, bé cưng à."
L40_1[1] = L41_1
L40_1[2] = L42_1
L41_1 = {}
L42_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ESPR_C_SNIPER@AB_UI_UNIT_VOICE_NKM_UNIT_ESPR_C_SNIPER_LOBBY_TOUCH_NORMAL_4"
L43_1 = "Nelson á? Aha, cô tiểu thư ngây thơ trong dáng nữ tu. Cô ấy phù hợp với chúng ta hơn là Holy Curia ấy. Như họ nói đó, giấy trắng thì dễ vẽ hơn... Tôi hy vọng câu này không khiến cô ấy phật ý."
L41_1[1] = L42_1
L41_1[2] = L43_1
L42_1 = {}
L43_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ESPR_C_SNIPER@AB_UI_UNIT_VOICE_NKM_UNIT_ESPR_C_SNIPER_LOBBY_TOUCH_LIFETIME_1"
L44_1 = "Bất cứ khi nào ngài muốn vào phòng tôi, hãy ngoan ngoãn gõ cửa theo nhịp điệu mà chúng ta đã giao ước từ trước. Nếu không tôi sẽ cần chút thời gian để giấu tất cả bức ảnh của ngài trên tường."
L42_1[1] = L43_1
L42_1[2] = L44_1
L43_1 = {}
L44_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ESPR_C_SNIPER@AB_UI_UNIT_VOICE_NKM_UNIT_ESPR_C_SNIPER_LOBBY_TOUCH_LIFETIME_2"
L45_1 = "Phư phư, ngài không phải là người dễ lay động đâu nhỉ? Nhưng sự nóng nảy chỉ làm tăng thêm nét quyến rũ của ngài thôi. Tôi chỉ có thể tưởng tượng những điều ngài đã phải trải qua để trở thành như vậy…Ngài có thể chia sẻ với tôi khi nào rảnh rỗi không?"
L43_1[1] = L44_1
L43_1[2] = L45_1
L44_1 = {}
