L31_1 = "SI_SKIN_DESC_NKM_UNIT_ALPHA_C_SPEAR_BUNNY"
L32_1 = "Cô ấy có lẽ không thạo mấy trò ảo thuật được học khi còn ở trong đoàn kịch. Nhưng ảo thuật gia thỏ nhỏ này không bao giờ bỏ cuộc. Đó là bởi vì cô ấy hiểu rằng trò thực sự để thu hút sự chú ý của khán giả không phải là lừa dối, mà là mà là một nụ cười chân thật.\n\n<color=#ffd34c>Ta đa! Xin chào và chào mừng đến với buổi diễn của Ảo Thuật Gia Thỏ! Tôi chỉ nhận các thanh sô cô la để làm phí vào cửa thôi nhé!</color>"
L30_1[1] = L31_1
L30_1[2] = L32_1
L31_1 = {}
