L33_1 = "Spotlight là của tôi!"
L31_1[1] = L32_1
L31_1[2] = L33_1
L32_1 = {}
L33_1 = "SI_SKIN_DESC_NKM_UNIT_ESPR_C_SNIPER_BUNNY"
L34_1 = "Cái quan trọng nhất của một thợ săn chính là sự kiên nhẫn. Ngay cả khi săn một thứ yếu ớt như con thỏ, người ta cũng phải đợi đến đúng thời điểm. Ở một khía cạnh nào đó, những thợ săn cũng giống như những nhà sư đang tìm kiếm sự giác ngộ. Nhưng, tất nhiên, thợ săn thỏ này không có ý định kiên nhẫn trước con mồi ngon lành.\n\n<color=#ffd34c>Fu fu fu. Cảm thấy thế nào khi bị một con thỏ săn đuổi, đồ dễ thương này?</color>"
L32_1[1] = L33_1
L32_1[2] = L34_1
L33_1 = {}
