L33_1[1] = L34_1
L33_1[2] = L35_1
L34_1 = {}
L35_1 = "SI_SKIN_DESC_NKM_UNIT_BORDER_C_BOWGUN_BUNNY"
L36_1 = "Chúng tôi đã thuê một chuyên gia y tế cho sự kiện ngày hôm nay. Cô ấy cũng được tặng một vài bộ đồ phù hợp với chủ đề của sự kiện. Bất kỳ VIP nào cần hỗ trợ y tế, xin vui lòng tìm chú thỏ này nhé. Vâng, đó là một gợi ý đủ để xác định vị trí cô ấy, vì tìm cô ấy sẽ dễ hơn tìm trứng Phục sinh.\n\n<color=#ffd34c>Ngài có bị thương không? Cho tôi xem nào? Tôi sẽ không liếm đâu.</color>"
L34_1[1] = L35_1
