L40_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_HARMONY_CA_CONDUCT_WEDDING@AB_UI_UNIT_VOICE_NKM_UNIT_HARMONY_CA_CONDUCT_LOBBY_TOUCH_NORMAL_4"
L41_1 = "Nhạc trưởng là người quản lý sân khấu. Tuy nhiên, ngài đang cố gắng biến tôi trở thành ngôi sao của buổi biểu diễn. Nếu ý định của ngài là để phô trương sức mạnh của mình...Vậy thì, tôi có lời khen đấy, ngài đã làm rất tốt."
