L35_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_CA_ARTILLERY@AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_CA_ARTILLERY_LOBBY_TOUCH_NORMAL_1"
L36_1 = "Tôi không nhớ những gì đã xảy ra bên trong thiết bị khi tôi đang được chuyển đổi. Tuy nhiên... Có cảm giác như tôi đang chìm sâu hơn vào vực sâu trong một thời gian dài và tiến gần hơn đến bản chất của Ăn Mòn."
L34_1[1] = L35_1
L34_1[2] = L36_1
L35_1 = {}
L36_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_CA_ARTILLERY@AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_CA_ARTILLERY_LOBBY_TOUCH_NORMAL_2"
L37_1 = "Đang ghi nhật ký nhiệm vụ. Tuần tra các cơ sở công ty với Quản Trị Viên. ...Nó trở nên im lặng chết chóc sau nhiều giờ, như thể tiếng ồn lúc nãy chỉ là ảo giác. Tuy nhiên, có lúc tôi đã rất thoải mái với sự yên tĩnh này."
L35_1[1] = L36_1
L35_1[2] = L37_1
L36_1 = {}
L37_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_CA_ARTILLERY@AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_CA_ARTILLERY_LOBBY_TOUCH_NORMAL_3"
L38_1 = "Cặp song sinh thế nào? Những người đồng đội đã ngã xuống của chúng tôi... Họ đang chiến đấu vì một thế giới nơi mà những đứa trẻ như chúng không phải chịu đau khổ. Tính nghịch ngợm của chúng làm tôi lo, nhưng tôi hy vọng chúng an toàn và khỏe mạnh."
L36_1[1] = L37_1
L36_1[2] = L38_1
L37_1 = {}
L38_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_CA_ARTILLERY@AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_CA_ARTILLERY_LOBBY_TOUCH_NORMAL_4"
L39_1 = "Kể cả khi ngài nói tôi đã trở nên quá nghiêm túc, thì việc thay đổi chính sách cũng không nằm trong giới hạn của tôi. Ngài có thể thảo luận chi tiết với Sooyeon. Tuy nhiên, khó có thể phủ nhận rằng tôi cảm thấy thoải mái hơn khi giao tiếp với ngài như này."
L37_1[1] = L38_1
L37_1[2] = L39_1
L38_1 = {}
L39_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_CA_ARTILLERY@AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_CA_ARTILLERY_LOBBY_TOUCH_LIFETIME_1"
L40_1 = "V.T.A.M. gây hại cho người xung quanh nó chỉ với sự tồn tại của chúng. Tuy nhiên, tôi không cần phải căng thẳng như vậy khi ở bên ngài. Đối với tôi ... Ngài là nơi trú ẩn duy nhất."
L38_1[1] = L39_1
L38_1[2] = L40_1
L39_1 = {}
L40_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_CA_ARTILLERY@AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_CA_ARTILLERY_LOBBY_TOUCH_LIFETIME_2"
L41_1 = "Các thành viên của Sư Đoàn đã hy vọng ngài sẽ tham gia vào lễ kỷ niệm kết thúc tác chiến. Và, với tất cả sự tôn trọng, tôi cũng mong ngài sẽ tới. Dù vật chứa này có lẽ không uống say được, nhưng tôi sẽ không từ chối tạo nên kỷ niệm đáng nhớ với những người đồng đội thân yêu."
L39_1[1] = L40_1
L39_1[2] = L41_1
L40_1 = {}
L41_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_CA_ARTILLERY@AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_CA_ARTILLERY_LOBBY_TOUCH_LIFETIME_3"
L42_1 = "Ngài vừa... hỏi tôi có triệu hồi V.T.A.M. cấp cao không ư? Không. Nếu ngài chứng kiến thứ gì đó trong văn phòng của Sư Đoàn, đó có thể là mô hình mà tôi mới hoàn thành. Tôi đã bỏ rất nhiều công sức vào bức tranh vì nó là phiên bản giới hạn... Trông nó hung dữ thế sao?"
L40_1[1] = L41_1
L40_1[2] = L42_1
L41_1 = {}
