L9_1 = "SI_SKIN_DESC_NKM_UNIT_ESPR_CA_FROZEN_SPECIAL"
L10_1 = "\nMột bãi biển hẻo lánh nằm sâu trong khuôn viên của Hiệp hội.\nĐó là nơi mọi người quên đi những lo lắng và thành thật với chính mình, nơi thực tế và ảo mộng trở nên lẫn lộn.\nCó tin đồn về một cô gái, da trắng như tuyết đầu mùa, đi dọc bờ biển đầy duyên dáng.\nNhư thể cô ấy đang đợi ai đó tới làm tan chảy trái tim băng giá của mình.\n\n<color=#ffd34c>Cảm ơn vì đã nhận lời mời của tôi. Thế, chúng ta dành chút thời gian để tìm hiểu nhau hơn chứ nhỉ?</color>"
L8_1[1] = L9_1
L8_1[2] = L10_1
