L42_1 = "SI_UNIT_SKILL_DESC_CANARY_S_SHIELD_PASSIVE2_LV5"
L43_1 = "Nếu có một Laika đồng minh trên chiến trường, Giới hạn DMG nhận tối đa của Félicette sẽ thay đổi thành 10%"
