L13_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_CHALLENGE_CANARY_1_2"
L14_1 = "Con chó đã học cách giữ im lặng trong khi làm dịu cơn khát của nó bằng nước thải.\n\n<color=#ffd34c>* Félicette và Laika mất tất cả khả năng miễn nhiễm và bị dính hiệu ứng debuff DMG Nhận Khuếch Đại khi mất một lượng HP nhất định.</color>"
L12_1[1] = L13_1
L12_1[2] = L14_1
