L30_1[2] = L32_1
L31_1 = {}
L32_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_CANARY_S_SHIELD"
L33_1 = "Félicette là một Lính Phòng Vệ có thể vô hiệu hóa kẻ thù bằng các kỹ năng trên không và có sức mạnh tổng hợp tuyệt vời với Laika.\n\nCô ấy là chỉ huy nhỏ bé nhưng đáng tin cậy của Tiểu Đội Canary. Cô ấy có thể tận dụng chiếc khiên nặng mà không đổ mồ hôi, mà cũng có kỹ năng điêu luyện như mèo. Cô ấy nhận thức rõ những hạn chế về thể chất của mình, vì vậy, cô ấy tập luyện ngày đêm để cải thiện sức chịu đựng và sức mạnh của mình. Thiếu ngủ có lẽ có ảnh hưởng tiêu cực đến sự phát triển thể chất nên người giám hộ được khuyên nên chăm sóc cô ấy nhiều hơn."
L31_1[1] = L32_1
L31_1[2] = L33_1
L32_1 = {}
L33_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_CANARY_S_ASSAULT"
L34_1 = "Laika là một Lính Cơ Động có khả năng tự tăng sức mạnh cho các đòn tấn công của mình và có sức mạnh tổng hợp tuyệt vời với Félicette.\n\nChuột và gián không phải là những sinh vật duy nhất cư trú trong cống rãnh và ngõ hẻm của Charade. Laika cũng là một trong những kẻ bơ vơ trốn tránh xã hội. Nếu không gặp Félicette, cô ấy vẫn sẽ ẩn nấp trong bóng tối với độ sâu ẩm thấp. Cô ấy thường thể hiện mình là một người thô bạo và liều lĩnh, nhưng ý thức nhạy bén thỉnh thoảng bộc lộ đã chứng tỏ rằng cô ấy không từ bỏ cuộc sống, không giống như những người bị bỏ rơi khác."
L32_1[1] = L33_1
L32_1[2] = L34_1
L33_1 = {}
