L39_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_CANARY_S_SHIELD@AB_UI_UNIT_VOICE_NKM_UNIT_CANARY_S_SHIELD_GET_01"
L40_1 = "Tốt thôi. Tôi sẽ gọi ngài là Huấn Luyện Viên. Đổi lại, ngài phải hứa với tôi rằng ngài sẽ dẫn dắt để tôi có thể chiến thắng."
L38_1[1] = L39_1
L38_1[2] = L40_1
L39_1 = {}
L40_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_CANARY_S_SHIELD@AB_UI_UNIT_VOICE_NKM_UNIT_CANARY_S_SHIELD_LOBBY_CAPTAIN"
L41_1 = "Xem ra tôi rất đáng tin cậy, phải không? E hèm! Được rồi."
L39_1[1] = L40_1
L39_1[2] = L41_1
L40_1 = {}
L41_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_CANARY_S_SHIELD@AB_UI_UNIT_VOICE_NKM_UNIT_CANARY_S_SHIELD_LOBBY_CONNECT"
L42_1 = "Rất vui được gặp lại ngài... Huấn Luyện Viên."
L40_1[1] = L41_1
L40_1[2] = L42_1
L41_1 = {}
L42_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_CANARY_S_SHIELD@AB_UI_UNIT_VOICE_NKM_UNIT_CANARY_S_SHIELD_LOBBY_CONNECT_LIFETIME"
L43_1 = "Ngài khỏe chứ, Huấn Luyện Viên? Chúng ta sẽ đi tập ngay thôi nhỉ?"
L41_1[1] = L42_1
L41_1[2] = L43_1
L42_1 = {}
L43_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_CANARY_S_SHIELD@AB_UI_UNIT_VOICE_NKM_UNIT_CANARY_S_SHIELD_LOBBY_TOUCH_NORMAL_1"
L44_1 = "Các trận đấu mô phỏng có quy tắc và độ sâu riêng. Nếu lơ là sẽ bị trừng phạt đấy."
L42_1[1] = L43_1
L42_1[2] = L44_1
L43_1 = {}
L44_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_CANARY_S_SHIELD@AB_UI_UNIT_VOICE_NKM_UNIT_CANARY_S_SHIELD_LOBBY_TOUCH_NORMAL_2"
L45_1 = "Tốt nhất là đừng chạm vào khiên của tôi. Hồi trước tôi vô tình kích hoạt nó một lần, thế là làm bay mái nhà ký túc xá luôn."
L43_1[1] = L44_1
L43_1[2] = L45_1
L44_1 = {}
L45_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_CANARY_S_SHIELD@AB_UI_UNIT_VOICE_NKM_UNIT_CANARY_S_SHIELD_LOBBY_TOUCH_NORMAL_4"
L46_1 = "Tôi ghét phải ra khỏi giường mỗi sáng... nhưng tôi không thể bỏ tập luyện dù chỉ một ngày. Tôi là tiên phong của đội. Vì vậy, tôi cần chạy liên tục với chiếc khiên của mình, bất kể tình huống nào."
L44_1[1] = L45_1
L44_1[2] = L46_1
L45_1 = {}
L46_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_CANARY_S_SHIELD@AB_UI_UNIT_VOICE_NKM_UNIT_CANARY_S_SHIELD_LOBBY_TOUCH_LIFETIME_1"
L47_1 = "Đứng sau tôi nếu tình hình trở nên nguy hiểm. Sức chịu đựng của tôi tốt hơn nhiều so với người lớn đấy."
L45_1[1] = L46_1
L45_1[2] = L47_1
L46_1 = {}
L47_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_CANARY_S_SHIELD@AB_UI_UNIT_VOICE_NKM_UNIT_CANARY_S_SHIELD_LOBBY_TOUCH_LIFETIME_2"
L48_1 = "Vẫn còn thời gian trước khi chúng ta ăn, ngài có muốn chạy bộ với tôi không? Ngài sẽ bị yếu nếu bị trói vào ghế cả ngày đấy... Ugh. Nếu ngài coi thường việc tập thể dục như vậy, tôi có thể cõng ngài chạy thay cho tấm khiên."
L46_1[1] = L47_1
L46_1[2] = L48_1
L47_1 = {}
L48_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_CANARY_S_SHIELD@AB_UI_UNIT_VOICE_NKM_UNIT_CANARY_S_SHIELD_LOBBY_TOUCH_LIFETIME_3"
L49_1 = "Tôi có thể nhỏ người hơn lính đánh thuê khác, nhưng tôi không quan tâm. Trên chiến trường, to lớn hơn sẽ chỉ trở thành mục tiêu lớn hơn thôi."
L47_1[1] = L48_1
L47_1[2] = L49_1
L48_1 = {}
L49_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_CANARY_S_SHIELD@AB_UI_UNIT_VOICE_NKM_UNIT_CANARY_S_SHIELD_LOBBY_TOUCH_LIFETIME_4"
L50_1 = "Tôi đã nhận ra khi ở cạnh ngài, Huấn Luyện Viên. Ngủ không đủ giấc, luôn ăn đồ ăn nhanh, lối sống không điều độ... Có vẻ như ngài mới là người cần được huấn luyện! Là trợ lý của ngài, tôi sẽ chịu trách nhiệm và bắt ngài đi ngủ sớm. Và tôi không chấp nhận bất kỳ lời phàn nàn nào đâu."
L48_1[1] = L49_1
L48_1[2] = L50_1
