L16_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_EXILER_PROLOGUE1"
L17_1 = "Ngày hôm đó, có những người đã đưa chúng ta đến giao lộ.\nChúng ta phải bảo vệ thế giới quý giá mà họ đã để lại phía sau."
L15_1[1] = L16_1
L15_1[2] = L17_1
L16_1 = {}
L17_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_EXILER_1_1"
L18_1 = "Nhiều quốc gia không tránh khỏi sự diệt vong khi thảm họa Ăn Mòn lan rộng nhanh chóng.\nNgười dân đã tập trung lại để tồn tại, một chính phủ thống nhất dựa trên chính phủ liên bang đã ra đời."
L16_1[1] = L17_1
L16_1[2] = L18_1
L17_1 = {}
L18_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_EXILER_INTERLUDE1"
L19_1 = "Các khối không xác định bắt đầu bao trùm thế giới từng cái một. Chúng tôi không có cái tên nào cho chúng vào thời điểm đó.\nVài người ghê tởm chúng, trong khi vài người khác lại tôn thờ chúng.\nSau này chúng tôi mới biết rằng chúng là kén của vài sinh vật."
L17_1[1] = L18_1
L17_1[2] = L19_1
L18_1 = {}
L19_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_EXILER_1_2"
L20_1 = "Chính phủ thống nhất đã thành lập các đài quan sát kén để quản lý các kén ở mỗi quận.\nNhưng bất chấp tất cả nỗ lực này, không ai có thể ngăn chặn sự thức tỉnh của Nephil."
L18_1[1] = L19_1
L18_1[2] = L20_1
L19_1 = {}
L20_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_EXILER_INTERLUDE2"
L21_1 = "Mỗi người đều có một quê hương.\nNhưng liệu họ có thể quay lại đó hay không, lại là một câu hỏi khác hoàn toàn."
L19_1[1] = L20_1
L19_1[2] = L21_1
L20_1 = {}
L21_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_EXILER_1_3"
L22_1 = "Vì khi họ từ cõi chết trở lại,\nthì họ không cưới vợ lấy chồng, mà giống như các thiên thần trên thiên đường."
L20_1[1] = L21_1
L20_1[2] = L22_1
L21_1 = {}
L22_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_EXILER_1_4"
L23_1 = "Nói chung, V.T.A.M. không có trí thông minh.\nChúng di chuyển theo bản năng và tiêu diệt mọi thứ sống sót cản đường chúng.\nNói chung là như vậy."
L21_1[1] = L22_1
L21_1[2] = L23_1
L22_1 = {}
L23_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_EXILER_INTERLUDE3"
L24_1 = "Giá như... chúng ta cũng mạnh như họ...\nThì tôi sẽ có thể... thay đổi kết cục của tình huống này...?"
L22_1[1] = L23_1
L22_1[2] = L24_1
L23_1 = {}
L24_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_EXILER_INTERLUDE4"
L25_1 = "Con người buộc phải từ bỏ khi họ tuyệt vọng. Nhưng hy vọng thôi thúc họ trở nên liều lĩnh.\nĐó là lý do tại sao đôi khi hy vọng có thể tổn thương nhiều hơn tuyệt vọng."
L23_1[1] = L24_1
L23_1[2] = L25_1
L24_1 = {}
L25_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_EXILER_INTERLUDE5"
L26_1 = "Tại sao tôi chỉ nhớ đến bóng lưng\nkhi tôi cố nhớ tới ký ức thoáng qua về anh?"
L24_1[1] = L25_1
L24_1[2] = L26_1
L25_1 = {}
L26_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_EXILER_2_1"
L27_1 = "Dù ở cấp độ chính phủ hay cá nhân,\nđã có nhiều nỗ lực để huấn luyện Counters.\nTất nhiên, một Counter cao cấp không được hình thành thông qua các bài tập huấn luyện đơn giản."
L25_1[1] = L26_1
L25_1[2] = L27_1
L26_1 = {}
L27_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_EXILER_2_2"
L28_1 = "Như thể thời gian đã ngừng lại, như thể không khí ngừng rung chuyển.\nTôi không nghe được tiếng la hét của các thành viên, cũng không ngửi thấy mùi thuốc súng."
L26_1[1] = L27_1
L26_1[2] = L28_1
L27_1 = {}
L28_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_EXILER_INTERLUDE7"
L29_1 = "Càng do dự, nó càng chắc chắn...\nBạn càng quay đi, nó càng rõ ràng...\nBất kể ý chí của chúng ta là gì, cái kết vẫn tiến dần về phía chúng ta."
L27_1[1] = L28_1
L27_1[2] = L29_1
L28_1 = {}
L29_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_EXILER_2_3"
L30_1 = "Hết phép màu này đến phép màu khác,\nchúng tôi đã có thể thành công trong Chiến dịch Giao Lộ.\nMột lần nữa bị dồn vào chân tường, chúng tôi cầu nguyện cho một phép màu nữa sẽ xảy ra."
L28_1[1] = L29_1
L28_1[2] = L30_1
L29_1 = {}
L30_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_EXILER_2_4"
L31_1 = "Tôi nghĩ rằng vị trí này chỉ là một hình thức.\nAi mà tưởng tượng được việc thẩm vấn người khác khi thế giới sắp kết thúc chứ?"
L29_1[1] = L30_1
L29_1[2] = L31_1
L30_1 = {}
L31_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_EXILER_3_1"
L32_1 = "Nỗi tuyệt vọng trắng đang đến gần.\nĐể cuối cùng, đặt dấu chấm hết cho thế giới bị tổn thương của chúng ta."
L30_1[1] = L31_1
L30_1[2] = L32_1
L31_1 = {}
L32_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_EXILER_3_2"
L33_1 = "Ngay cả một thế giới cô đơn chỉ còn lại những tàn tích, cũng đã từng là một nơi con người thực sự sinh sống."
L31_1[1] = L32_1
L31_1[2] = L33_1
L32_1 = {}
L33_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_EXILER_INTERLUDE8"
L34_1 = "Một chuyến đi cô đơn, cô lập đi tới điểm đến cuối cùng."
L32_1[1] = L33_1
L32_1[2] = L34_1
L33_1 = {}
L34_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_EXILER_INTERLUDE9"
L35_1 = "Khi hoàng hôn kết thúc, con cú của Minerva dang rộng đôi cánh."
L33_1[1] = L34_1
L33_1[2] = L35_1
L34_1 = {}
L35_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_EXILER_3_3"
L36_1 = "Con đường tôi chạm tới sau một thời gian dài lang thang... Nó có thể là kết thúc cho tất cả những gì tôi biết."
L34_1[1] = L35_1
L34_1[2] = L36_1
L35_1 = {}
L36_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_EXILER_INTERLUDE10"
L37_1 = "Có lẽ, ngay từ đầu, không có cách nào để thay đổi sự diệt vong đang chờ đón chúng tôi...\nDù có cố gắng thế nào đi chăng nữa."
L35_1[1] = L36_1
L35_1[2] = L37_1
L36_1 = {}
L37_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_EXILER_3_4"
L38_1 = "Nhưng dù sao thì, tôi chỉ có thể tiếp tục tiến về phía trước."
L36_1[1] = L37_1
L36_1[2] = L38_1
L37_1 = {}
L38_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_EXILER_EPILOGUE"
L39_1 = "Tương lai mà những người lính đã ngã xuống của chúng ta không thể nhìn thấy...\nTôi, và chúng ta... có nhiệm vụ hiện thực hóa nó!"
L37_1[1] = L38_1
L37_1[2] = L39_1
L38_1 = {}
L39_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_DELTA_CA_KYLE_AP"
L40_1 = "Minerva Karin Wong là một Lính Cơ Động sử dụng tia laze để gây sát thương và xuyên thủng kẻ thù, cũng như tăng cường tường chắn để đẩy lùi các cuộc tấn công của kẻ thù.\n\nCô ấy là chỉ huy của 「Delta Seven: Người Tìm Đường」và là thành viên cuối cùng còn lại của Delta Seven trong này thế giới bị tổn thương. Karin có một trang bị riêng gọi là Glaukopis được cấy vào mắt phải của cô ấy, bắt nguồn từ một thế giới đã sụp đổ. Thiết bị này tối đa hóa khả năng phân tích và cấp cho cô ấy kết nối trực tiếp với Con Tàu Thất Lạc gọi là Aegis. Do đó, cô có thể tự do điều khiển con tàu mà không cần sự trợ giúp, triệu tập các trang bị tối tân từ kho vũ khí của Aegis để phù hợp với từng tình huống chiến đấu và tận dụng tối đa khả năng của nó.\n\nCô gái đã mất tất cả đồng đội và đã ở giao lộ, giờ đây đã có sức mạnh để đi theo ý chí của thế giới bị hủy diệt, tạo ra con đường của riêng mình."
