L23_1[2] = L25_1
L24_1 = {}
L25_1 = "SI_UNIT_SKILL_DESC_DELTA_CA_KYLE_AP_HYPER_LV1"
L26_1 = "Triệu hồi vũ khí Aegis và bắn một khẩu pháo hạt, gây sát thương cho tất cả kẻ thù. Nếu mục tiêu trên mặt đất xuất hiện sau khi sử dụng kỹ năng, Karin sẽ né tránh về hướng tàu của đồng minh và sử dụng Kỹ năng Bị Động của mình (Tàu không nằm trong mục tiêu)."
L24_1[1] = L25_1
L24_1[2] = L26_1
