L26_1 = "SI_UNIT_SKILL_DESC_DELTA_CA_KYLE_AP_HYPER_LV5"
L27_1 = "Sau khi sử dụng kỹ năng, tăng 25% ATK trong 12 giây (Không thể hủy bỏ)"
L25_1[1] = L26_1
L25_1[2] = L27_1
L26_1 = {}
L27_1 = "SI_UNIT_SKILL_DESC_DELTA_CA_KYLE_AP_PASSIVE_LV1"
L28_1 = "Khi kẻ thù ở trong khoảng cách 400, cô chuyển các phần súng trường để bắn tia laze cực mạnh vào tất cả kẻ thù trên đường đi, hơi đẩy lùi chúng và gây ra Đảo Ngược  Rào Chắn để đánh trúng kẻ thù (Không bao gồm Tàu, miễn nhiễm với các KN Đặc Biệt trở xuống khi dùng). Đòn tấn công này có thời gian hồi 12 giây. Sau 8 lần tấn công cơ bản và Bị Động (16 lần đối với PVE), hoặc nếu HP của Karin giảm xuống dưới 70% và 40%, cô ấy sẽ tránh về hướng tàu của đồng minh và sử dụng KN Bị Động nếu xuất hiện mục tiêu trên mặt đất (Tàu bị loại khỏi mục tiêu)."
L26_1[1] = L27_1
L26_1[2] = L28_1
L27_1 = {}
