L2_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_REAPER_C_ARMS"
L3_1 = "Lenore là giám đốc điều hành thuộc Đội Tác Chiến của Liên Minh Phía Bắc. Cô đã mạo hiểm tình nguyện làm đối tượng thử nghiệm trong dự án Oracle mà cha cô đang nghiên cứu và là đối tượng duy nhất có được kết quả thành công. \n\nCô ấy có thể nhìn thấy tương lai mình mong muốn thông qua thí nghiệm và có những đóng góp đáng kể cho Liên Minh Phía Bắc bằng cách loại bỏ kẻ phản bội bên trong. Đối với Lenore với khả năng nhìn trước tương lai mà nói, không có thứ gọi là thất bại, nên cái tôi của cô ấy ngày càng lớn hơn. Dần dần, cô không còn hứng thú với kết quả hiển nhiên của kế hoạch của mình. Cô bắt đầu tìm kiếm những điều mới mẻ, phấn khích và cảm thấy được sự vui sướng khi dẫm đạp lên những kẻ thù có niềm tin mãnh liệt. Nhiệm vụ được hoàn thành vốn dĩ để phục vụ đất nước, nhưng ở đâu đó, lại biến thành những tội ác buông thả tập trung mang lại sự hủy hoại cho người khác."
L1_1[1] = L2_1
L1_1[2] = L3_1
L2_1 = {}
L3_1 = "SI_ITEM_MISC_DESC_IMI_ITEM_MISC_SELFIE_FRAME_EVENT_PASS_29"
L4_1 = "Một khung mà đối với Lenore, tượng trưng cho thứ tương lai lạnh lùng hơn thép. Hãy trang bị nó trong Hồ Sơ để thể hiện sức mạnh của công ty bạn."
L2_1[1] = L3_1
L2_1[2] = L4_1
