L5_1 = "SI_UNIT_DESC_NKM_UNIT_REAPER_C_ARMS"
L6_1 = "Là kẻ tấn công cận chiến chuyên làm suy yếu kẻ địch và phản đòn."
L4_1[1] = L5_1
L4_1[2] = L6_1
