L5_1[2] = L7_1
L6_1 = {}
L7_1 = "SI_UNIT_SKILL_DESC_REAPER_C_ARMS_ATTACK_LV1"
L8_1 = "Chém một kẻ thù phía trước bằng cánh tay cơ khí của mình. Khi bị trúng một đòn tấn công cơ bản khi đang di chuyển hoặc thực hiện các đòn tấn công cơ bản, cô ấy tiêu tốn 1 điểm cộng dồn [Lừa Gạt] và thực hiện phản đòn loại bỏ rào cản và đẩy lùi kẻ địch."
L6_1[1] = L7_1
L6_1[2] = L8_1
L7_1 = {}
L8_1 = "SI_UNIT_SKILL_DESC_REAPER_C_ARMS_HYPER_LV1"
L9_1 = "Trở nên Bất Khả Chiến Bại, di chuyển về phía trước trong khi chém, và đẩy lùi kẻ địch bằng đòn hit cuối cùng. Loại bỏ rào cản của các mục tiêu bị ảnh hưởng. Lenore tiến vào chế độ Tất Trúng trong 15 giây sau khi thi triển kỹ năng."
L7_1[1] = L8_1
L7_1[2] = L9_1
L8_1 = {}
L9_1 = "SI_UNIT_SKILL_DESC_REAPER_C_ARMS_HYPER_LV5"
L10_1 = "Nhận được 4 cộng dồn [Lừa Gạt] sau kỹ năng"
L8_1[1] = L9_1
L8_1[2] = L10_1
L9_1 = {}
L10_1 = "SI_UNIT_SKILL_DESC_REAPER_C_ARMS_PASSIVE_LV1"
L11_1 = "Phát hiện Tàng Hình. Cứ mỗi khi bị đánh trúng 15 đòn, cô ấy nhận được 1 cộng dồn [Lừa Gạt] (Tối đa 4 cộng dồn, không thể hủy) giúp tăng EVA lên 50%. Tất cả đòn tấn công của Lenore đều gây ra [Phán Xét] lên mục tiêu. Khi được 4 cộng dồn [Phán Xét], kẻ địch ngoại trừ Boss sẽ phải chịu [Hành Quyết] thứ gây sát thương bằng 15% HP hiện tại của chúng. Kẻ địch ở trạng thái [Hành Quyết] không thể nhận thêm bất kỳ cộng dồn [Phán Xét] nào.\n\nPhán Xét: DEF -5% trong 6 giây\nHành Quyết: DEF -20% trong 12 giây"
L9_1[1] = L10_1
L9_1[2] = L11_1
