L42_1 = "Các Lính Tấn Công tầm xa đẩy lùi kẻ thù bằng các đòn tấn công Nâng cao"
L40_1[1] = L41_1
L40_1[2] = L42_1
L41_1 = {}
L42_1 = "SI_UNIT_SKILL_DESC_S_STATE_RIFLE_PASSIVE_LV1"
L43_1 = "Tăng hỏa lực của súng trường dịch vụ4 bằng cách gắn phụ kiện cá nhân. Sau mỗi đòn tấn công cơ bản thứ 4, chúng phóng ra một quả lựu đạn gây thêm 20% sát thương AoE."
L41_1[1] = L42_1
L41_1[2] = L43_1
