L43_1 = "SI_UNIT_SKILL_DESC_S_STATE_RIFLE_PASSIVE2_LV1"
L44_1 = "Cải thiện khả năng sử dụng vũ khí của họ ngay cả khi đang chiến đấu. Tăng 5% ATK mỗi khi chúng phóng lựu đan, tối đa 15%."
