L31_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_SCHOOL_C_STAFF"
L32_1 = "Ciel là một sát thủ và là lính tấn công, đánh tuyến sau bằng cách vung ngọn giáo Bakuya và làm chệch hướng đòn tấn công của kẻ thù.\n\nMặc dù có khát vọng trở thành một học sinh gương mẫu, nhưng cô lại là một cô gái sống về đêm hiếm khi tỉnh táo trong lớp. Cô không có kỹ năng xã hội khi mới vào Học viện; còn không biết từ \"bạn\" nghĩa là gì. Tuy nhiên, giờ đây với sự giúp đỡ của các bạn, cô đang dần dần học cuộc sống hàng ngày.\n\nCô là thủ lĩnh của một giáo phái sát thủ điều hành một thành phố, cũng không hề cố gắng che giấu sự thật này. Một vài học sinh lúc đầu có vẻ rất nghiêm trọng. Nhưng bởi cô ấy ngây thơ và không có khả năng từ chối giúp đỡ gì, nên chẳng ai tin cô là một sát thủ thực sự.\n\nNếu bạn nhận thấy Ciel có vẻ cáu kỉnh vào ban ngày thì đừng lo. Chỉ đơn giản là cô ấy đang cố nhìn rõ vật thể trước mặt mình hơn thôi."
L30_1[1] = L31_1
L30_1[2] = L32_1
L31_1 = {}
L32_1 = "SI_PVP_EVENTMATCH_DESC_2023_02"
L33_1 = "Bài thực hành Arcade của Ciel, thành viên Hội Học Sinh sắp bắt đầu!\nMọi người! Tập luyện thôi nào!"
L31_1[1] = L32_1
L31_1[2] = L33_1
L32_1 = {}
L33_1 = "SI_PVP_EVENTMATCH_TITLE_2023_02"
L34_1 = "Bài Thực Hành của Hội Học Sinh"
L32_1[1] = L33_1
L32_1[2] = L34_1
L33_1 = {}
L34_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_SCHOOL_C_STAFF@AB_UI_UNIT_VOICE_NKM_UNIT_SCHOOL_C_STAFF_GET_01"
L35_1 = "Tôi là Ciel, thủ lĩnh của Black East... và cũng là thành viên của Hội Học Sinh ở Học Viện Counter. Tôi ở đây để hỗ trợ ngài và hoàn thành chỉ tiêu giờ tình nguyện của tôi."
L33_1[1] = L34_1
L33_1[2] = L35_1
L34_1 = {}
L35_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_SCHOOL_C_STAFF@AB_UI_UNIT_VOICE_NKM_UNIT_SCHOOL_C_STAFF_LOBBY_CAPTAIN"
L36_1 = "Tôi sẽ chịu trách nhiệm đến cuối cùng."
L34_1[1] = L35_1
L34_1[2] = L36_1
L35_1 = {}
L36_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_SCHOOL_C_STAFF@AB_UI_UNIT_VOICE_NKM_UNIT_SCHOOL_C_STAFF_LOBBY_CONNECT"
L37_1 = "Chào mừng ngài trở lại."
L35_1[1] = L36_1
L35_1[2] = L37_1
L36_1 = {}
L37_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_SCHOOL_C_STAFF@AB_UI_UNIT_VOICE_NKM_UNIT_SCHOOL_C_STAFF_LOBBY_CONNECT_LIFETIME"
L38_1 = "Cứ yên tâm, vì tôi sẽ ở bên ngay cả khi ngài đang ngủ say."
L36_1[1] = L37_1
L36_1[2] = L38_1
L37_1 = {}
L38_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_SCHOOL_C_STAFF@AB_UI_UNIT_VOICE_NKM_UNIT_SCHOOL_C_STAFF_LOBBY_TOUCH_NORMAL_1"
L39_1 = "Sát thủ của Black East thường hoạt động về đêm. Vậy nên thức vào ban ngày có cảm giác khá kỳ lạ với tôi. Đó cũng là lý do ngày nào tôi cũng ngủ gật trong lớp."
L37_1[1] = L38_1
L37_1[2] = L39_1
L38_1 = {}
L39_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_SCHOOL_C_STAFF@AB_UI_UNIT_VOICE_NKM_UNIT_SCHOOL_C_STAFF_LOBBY_TOUCH_NORMAL_2"
L40_1 = "Black East dạy cách hạ độc và ám khí. Tôi cũng đã cố gắng học từ khi còn nhỏ, nhưng vì tôi không thể kiểm soát được sức mạnh nên đã khiến cả chủ nhân cũng phải từ bỏ tôi."
L38_1[1] = L39_1
L38_1[2] = L40_1
L39_1 = {}
L40_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_SCHOOL_C_STAFF@AB_UI_UNIT_VOICE_NKM_UNIT_SCHOOL_C_STAFF_LOBBY_TOUCH_NORMAL_3"
L41_1 = "Mỗi lần ngủ gật trong lớp, Chủ Tịch Hội Học Sinh sẽ bảo tôi làm tình nguyện 2 tiếng. Nên, để tôi có ích thì ngài phải luôn chuẩn bị trước một nhiệm vụ mà tôi có thể hỗ trợ được."
L39_1[1] = L40_1
L39_1[2] = L41_1
L40_1 = {}
L41_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_SCHOOL_C_STAFF@AB_UI_UNIT_VOICE_NKM_UNIT_SCHOOL_C_STAFF_LOBBY_TOUCH_NORMAL_4"
L42_1 = "Tôi không giỏi hạ độc, nhưng tôi đã có khả năng kháng được phần lớn chất độc. Rượu bia...? Tôi không chắc lắm. Nếu ngài đợi cho đến khi tôi đủ tuổi thì tôi sẽ thử."
L40_1[1] = L41_1
L40_1[2] = L42_1
L41_1 = {}
L42_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_SCHOOL_C_STAFF@AB_UI_UNIT_VOICE_NKM_UNIT_SCHOOL_C_STAFF_LOBBY_TOUCH_LIFETIME_2"
L43_1 = "Chủ Nhân xoa đầu tôi chứ không khen vì đã hoàn thành tốt công việc. Chắc là tôi thích sự ấm áp người ta hơn là lời nói."
L41_1[1] = L42_1
L41_1[2] = L43_1
L42_1 = {}
L43_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_SCHOOL_C_STAFF@AB_UI_UNIT_VOICE_NKM_UNIT_SCHOOL_C_STAFF_LOBBY_TOUCH_LIFETIME_3"
L44_1 = "Là người sống về đêm, tôi hoàn thành trách nhiệm của Hội Học Sinh với mặt trăng. Không ai đến thăm tôi vào ban đêm để thảo luận về sự quan tâm của họ cả, nên nếu được thì, ngài đến đây mỗi tối được chứ."
L42_1[1] = L43_1
L42_1[2] = L44_1
L43_1 = {}
L44_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_SCHOOL_C_STAFF@AB_UI_UNIT_VOICE_NKM_UNIT_SCHOOL_C_STAFF_LOBBY_TOUCH_LIFETIME_4"
L45_1 = "Tôi có lẽ là người sống về đêm, nhưng không có nghĩa là tôi ngủ treo mình trên trần nhà. À, ngài có vẻ khá thất vọng nhỉ. Ngài mong đợi được thấy vậy à?"
