L14_1 = "REACTOR_DESC_1072"
L15_1 = "Một thanh kiếm vô danh. Nó phản ứng với CRF độc nhất của người dùng và lưỡi kiếm màu đỏ thẫm thậm chí có thể cắt đứt cả những lời nguyền ẩn giấu. Lò phản ứng phản ánh lòng trung thành của người dùng đối với lãnh đạo của họ như một nguồn tăng sức mạnh."
L13_1[1] = L14_1
L13_1[2] = L15_1
L14_1 = {}
L15_1 = "REACTOR_DESC_1151"
L16_1 = "Hai thanh kiếm nhỏ được truyền lại qua nhiều thế hệ. Hai thanh kiếm bổ sung cho nhau trong sự kết hợp hoàn hảo giữa tấn công và phòng thủ. Lò phản ứng phản ánh sự hài hòa không thiên về âm hay dương, như một nguồn tăng sức mạnh."
L14_1[1] = L15_1
L14_1[2] = L16_1
