L22_1[2] = L24_1
L23_1 = {}
L24_1 = "SI_ITEM_MISC_DESC_IMI_ITEM_EMBLEM_BIRTHDAY"
L25_1 = "Các nhân viên đã bí mật chuẩn bị một chiếc bánh để chúc mừng sinh nhật Ông Chủ.\nTất cả họ đều chen chúc nhau đặt một chiếc bánh thủ công, nhưng chúng tôi sẽ để ngài đoán xem ai trả nhiều tiền nhất."
L23_1[1] = L24_1
L23_1[2] = L25_1
L24_1 = {}
L25_1 = "SI_ITEM_MISC_DESC_IMI_ITEM_MISC_PACKAGE_BIRTHDAY_BOX"
L26_1 = "Một chiếc hộp chứa đầy những lời chúc mừng sinh nhật.\nMở hộp để nhận nhiều quà tặng khác nhau."
