L27_1 = "SI_PF_PROFILE_BIRTHDAY_POPUP_DESC"
L28_1 = "Ngài có muốn đặt ngày sinh của mình là <color=#FFCF3B>{0} {1}</color>?\n<color=#FF0000>Sau khi đã xác nhận, sẽ không thể thay đổi.</color>"
