L28_1[2] = L30_1
L29_1 = {}
L30_1 = "SI_BIRTHDAY_MAIL_DESC_1"
L31_1 = "Chào Ông Chủ. Đây là Thư ký Kim Hana.\nTôi chắc chắn ngài rất ngạc nhiên khi đây không phải là thư liên quan đến công việc.\nĐây thực sự là tin nhắn chúc mừng sinh nhật ạ.\nMặc dù mọi người đều bận rộn nhưng tất cả họ đều dành thời gian để chúc mừng sinh nhật ngài,\nvà tôi rất vui khi thấy không khí của công ty cũng tươi vui hơn.\nDù sao thì, hôm nay là một ngày đặc biệt mà mỗi năm chỉ có một lần đúng không ạ?\nChúc ngài có thể tận hưởng một ngày tuyệt vời và hạnh phúc nhất ạ."
L29_1[1] = L30_1
L29_1[2] = L31_1
