L21_1 = {}
L22_1 = "SI_EPISODE_DESC_1_SS_CHARADE2"
L23_1 = "Vinh quang được tìm thấy ở những nơi cao nhất. Một chú chó và một con mèo nhe răng nanh trước nữ hoàng kiêu hãnh."
