L23_1 = "SI_CONTENTS_UNLOCK_BG_PURCHASE_SIDE_CHARADE2"
L24_1 = "Hoàn thành [Chuyện Bên Lề: Đêm Đầy Sao]\nđể mua"
L22_1[1] = L23_1
L22_1[2] = L24_1
L23_1 = {}
L24_1 = "SI_COLLECTION_UNIT_INTRO_NKM_UNIT_ALPHA_C_CHOWON_PR"
L25_1 = "Kim Chowon là một lính phòng vệ chuyên trấn áp nhiều kẻ thù, đặt chất nổ để cản trở bước tiến của chúng. \n\nChất nổ là đồng minh đáng tin cậy mà lính đánh thuê ngầm hoạt động ngoài vòng pháp luật mang theo bên mình mọi lúc mọi nơi. Chúng đặc biệt phù hợp với những tình huống mà khó loại bỏ V.T.A.M. bằng súng hoặc khi cho nổ tung bức tường dày. Đó là lý do tại sao không có gì đáng sợ hơn chất nổ trong tay kẻ thù. Còn hơn thế nữa nếu kẻ thù đó là một con nhện ẩn mình trong mạng nhện và treo cổ con mồi.\n\nChiến tranh khiến nhiều người bị tàn phế. Nhưng thật không may, đối với một số người, đó lại là nơi họ khám phá ra những ham muốn khát máu của mình."
L23_1[1] = L24_1
L23_1[2] = L25_1
