L11_1 = "SI_ITEM_MISC_DESC_IMI_ITEM_MISC_RANDOM_CAFE_STREGA_1"
L12_1 = "Thực đơn yêu thích của Yuna.\nYuna tin chắc rằng mọi người trên thế giới sẽ yêu thích nó.\nCó thể nhận được Đánh Giá với xác suất nhất định.\nVật phẩm này sẽ bị xóa khi sự kiện kết thúc."
