L12_1 = "SI_ITEM_MISC_DESC_IMI_ITEM_MISC_RANDOM_CAFE_STREGA_2"
L13_1 = "Thực đơn yêu thích của Ingrid.\nMột ly là đủ để khiến bạn cảm thấy tràn đầy sinh lực.\nCó thể nhận được Lõi APT Binh Lính hoặc Lõi APT Đặc biệt với xác suất nhất định.\nVật phẩm này sẽ bị xóa khi sự kiện kết thúc."
L11_1[1] = L12_1
L11_1[2] = L13_1
L12_1 = {}
L13_1 = "SI_ITEM_MISC_DESC_IMI_ITEM_MISC_RANDOM_CAFE_STREGA_3"
L14_1 = "Thực đơn yêu thích của khách hàng ma cà rồng.\nChất lỏng màu đỏ kỳ lạ này tỏa ra hương vị quả mọng tươi.\nCó thể nhận được Lõi APT Lính Thiết Giáp hoặc Lõi APT Đặc Biệt với xác suất nhất định.\nVật phẩm này sẽ bị xóa khi sự kiện kết thúc."
L12_1[1] = L13_1
L12_1[2] = L14_1
L13_1 = {}
L14_1 = "SI_ITEM_MISC_DESC_IMI_ITEM_MISC_RANDOM_CAFE_STREGA_4"
L15_1 = "Một loại cà phê latte đặc biệt được làm theo công thức bí mật của Evelyn.\nMàu cam làm tăng thêm hương vị của cà phê.\nCó thể nhận được Lõi APT hoặc Lõi APT Đặc Biệt với xác suất nhất định.\nVật phẩm này sẽ bị xóa khi sự kiện kết thúc."
