L7_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_REAPER_C_ARMS@AB_UI_UNIT_VOICE_NKM_UNIT_REAPER_C_ARMS_LOBBY_TOUCH_NORMAL_3"
L8_1 = "Cha tôi đã ban cho tôi những sức mạnh đặc biệt và dành cả cuộc đời để cố hoàn thiện chúng. Và trong Liên Minh Phía Bắc, những kẻ phá hoại ông ấy... sẽ tận mắt nhìn thấy sức mạnh của tôi."
