L41_1 = "SI_UNIT_SKILL_DESC_SECURITY_CA_SERGEANT_HYPER_LV1"
L42_1 = "Phát động một cuộc tấn công phía trước bằng cách giải phóng hiệu suất của đơn vị bay. Cô ấy miễn nhiễm với sát thương khi di chuyển và rơi vào trạng thái [Đột Phá Quan Trọng] không thể bị hủy trong 20 giây sau khi sử dụng Kỹ năng Tối Thượng  của mình.\n[Đột Phá Quan Trọng]: Miễn nhiễm với tất cả các đòn Hitstun, ASPD +50%, Miễn nhiễm phong ấn kỹ năng"
L40_1[1] = L41_1
L40_1[2] = L42_1
L41_1 = {}
