L7_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_SECURITY_CA_SERGEANT@AB_UI_UNIT_VOICE_NKM_UNIT_SECURITY_CA_SERGEANT_GET_01"
L8_1 = "Chắc chắn là không có nhiệm vụ nào mà chỉ tôi mới làm được. Nên... tôi sẽ làm bất cứ điều gì mà tôi nghĩ mình phải làm."
L6_1[1] = L7_1
L6_1[2] = L8_1
L7_1 = {}
L8_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_SECURITY_CA_SERGEANT@AB_UI_UNIT_VOICE_NKM_UNIT_SECURITY_CA_SERGEANT_LOBBY_CAPTAIN"
L9_1 = "Tôi cho là không có giới hạn độ cao, phải không?"
L7_1[1] = L8_1
L7_1[2] = L9_1
L8_1 = {}
L9_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_SECURITY_CA_SERGEANT@AB_UI_UNIT_VOICE_NKM_UNIT_SECURITY_CA_SERGEANT_LOBBY_CONNECT"
L10_1 = "Tôi đã sẵn sàng triển khai. Ngay bây giờ."
L8_1[1] = L9_1
L8_1[2] = L10_1
L9_1 = {}
L10_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_SECURITY_CA_SERGEANT@AB_UI_UNIT_VOICE_NKM_UNIT_SECURITY_CA_SERGEANT_LOBBY_CONNECT_LIFETIME"
L11_1 = "Thời tiết thật đẹp để lười biếng nhỉ Ông Chủ."
L9_1[1] = L10_1
L9_1[2] = L11_1
L10_1 = {}
L11_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_SECURITY_CA_SERGEANT@AB_UI_UNIT_VOICE_NKM_UNIT_SECURITY_CA_SERGEANT_LOBBY_TOUCH_NORMAL_1"
L12_1 = "Những câu chuyện vĩ đại về hy vọng hay gì gì đó không phải gu của tôi... nhưng, tôi làm gì được đây? Tôi không thể rút lại lời nói bây giờ. Tôi sẽ phải hòa nhập bằng cách nào đó."
L10_1[1] = L11_1
L10_1[2] = L12_1
L11_1 = {}
L12_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_SECURITY_CA_SERGEANT@AB_UI_UNIT_VOICE_NKM_UNIT_SECURITY_CA_SERGEANT_LOBBY_TOUCH_NORMAL_2"
L13_1 = "Xã hội này có đúng đắn không khi ca ngợi một một nhóc lùn theo chủ nghĩa thất bại như tôi, là một anh hùng? Sau khi đi du lịch khắp nơi, tôi có thể nói rằng đất nước của tôi trông rất đặc biệt trong mắt người nước ngoài."
L11_1[1] = L12_1
L11_1[2] = L13_1
L12_1 = {}
L13_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_SECURITY_CA_SERGEANT@AB_UI_UNIT_VOICE_NKM_UNIT_SECURITY_CA_SERGEANT_LOBBY_TOUCH_NORMAL_3"
L14_1 = "Bằng cách nào đó tôi đã nhận trách nhiệm và đã thành công trong ca phẫu thuật... Khi những điều này xảy ra liên tục, thỉnh thoảng, nó khiến tôi nghĩ về bản thân... \"Tôi có thực sự mạnh mẽ không?\" ."
L12_1[1] = L13_1
L12_1[2] = L14_1
L13_1 = {}
L14_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_SECURITY_CA_SERGEANT@AB_UI_UNIT_VOICE_NKM_UNIT_SECURITY_CA_SERGEANT_LOBBY_TOUCH_NORMAL_4"
L15_1 = "Vậy, về thiết bị này. Vì đang giải quyết vấn đề khẩn cấp, có lẽ chúng ta nên bán nó. Tôi nghĩ chúng ta có thể có được một cái giá tốt cho nó. ...Ngh, tôi đùa thôi. Đùa thôi!"
L13_1[1] = L14_1
L13_1[2] = L15_1
L14_1 = {}
L15_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_SECURITY_CA_SERGEANT@AB_UI_UNIT_VOICE_NKM_UNIT_SECURITY_CA_SERGEANT_LOBBY_TOUCH_LIFETIME_1"
L16_1 = "Có một chút choáng ngợp khi nghe ngài đặt niềm tin vào tôi. Ý tôi là, tôi không phản đối việc dựa dẫm vào ai đó. Vì vậy, tôi cũng sẽ đặt niềm tin vào Ông Chủ."
L14_1[1] = L15_1
L14_1[2] = L16_1
L15_1 = {}
L16_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_SECURITY_CA_SERGEANT@AB_UI_UNIT_VOICE_NKM_UNIT_SECURITY_CA_SERGEANT_LOBBY_TOUCH_LIFETIME_2"
L17_1 = "Tạm thời tôi sẽ sống ngoài công ty. Có điều đáng sợ hơn nhiều so với việc bị buộc phải ra mắt với tư cách là một thần tượng được gắn với lòng yêu nước nếu tôi quay trở lại Gronia. Haiz..."
L15_1[1] = L16_1
L15_1[2] = L17_1
L16_1 = {}
L17_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_SECURITY_CA_SERGEANT@AB_UI_UNIT_VOICE_NKM_UNIT_SECURITY_CA_SERGEANT_LOBBY_TOUCH_LIFETIME_3"
L18_1 = "Tôi đã rất ngưỡng mộ Horizon, nhưng... tôi không nghĩ chiến đấu có phong cách là sở thích của mình. ...Nó khiến tôi cảm thấy như đang cằn nhằn để được hỗ trợ khi ngài vỗ nhẹ vào tôi như vậy."
L16_1[1] = L17_1
L16_1[2] = L18_1
L17_1 = {}
L18_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_SECURITY_CA_SERGEANT@AB_UI_UNIT_VOICE_NKM_UNIT_SECURITY_CA_SERGEANT_LOBBY_TOUCH_LIFETIME_4"
L19_1 = "Chỉ cần một huy chương thôi cũng khiến vai tôi nặng thêm. Nhưng với những lời tâng bốc đó, áp lực sẽ ngăn tôi bay. …Ơ?! Tôi không tăng chút cân nào cả!"
L17_1[1] = L18_1
L17_1[2] = L19_1
