L39_1 = {}
L40_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_FALLEN_CA_ROSARIA_SPECIAL@AB_UI_UNIT_VOICE_NKM_UNIT_FALLEN_CA_ROSARIA_GET_01"
L41_1 = "Ôi không, một cậu bé đã nhìn thấy ta biến hình! Ta cần ngài ký một hợp đồng ngay bây giờ vì ngài đã tìm ra danh tính thực sự của cô gái phép thuật, Rosaria. Hãy nhớ rằng cô gái phép thuật này có thể trừng phạt ngài vì đã phá vỡ thỏa thuận!"
L39_1[1] = L40_1
L39_1[2] = L41_1
L40_1 = {}
L41_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_FALLEN_CA_ROSARIA_SPECIAL@AB_UI_UNIT_VOICE_NKM_UNIT_FALLEN_CA_ROSARIA_LOBBY_CAPTAIN"
L42_1 = "Ra☆mắt!"
L40_1[1] = L41_1
L40_1[2] = L42_1
L41_1 = {}
L42_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_FALLEN_CA_ROSARIA_SPECIAL@AB_UI_UNIT_VOICE_NKM_UNIT_FALLEN_CA_ROSARIA_LOBBY_CONNECT"
L43_1 = "Ngài có cần cô gái phép thuật giúp đỡ không?"
L41_1[1] = L42_1
L41_1[2] = L43_1
L42_1 = {}
L43_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_FALLEN_CA_ROSARIA_SPECIAL@AB_UI_UNIT_VOICE_NKM_UNIT_FALLEN_CA_ROSARIA_LOBBY_CONNECT_LIFETIME"
L44_1 = "Hôm nay ta nên thanh trừng loại nhân vật phản diện nào đây?"
L42_1[1] = L43_1
L42_1[2] = L44_1
L43_1 = {}
L44_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_FALLEN_CA_ROSARIA_SPECIAL@AB_UI_UNIT_VOICE_NKM_UNIT_FALLEN_CA_ROSARIA_LOBBY_TOUCH_NORMAL_1"
L45_1 = "Ta có thể khiến bất kỳ con quái vật nào biến mất chỉ bằng một lần vung cây đũa phép này. Thật tuyệt phải không? Có lẽ ngài đã biết, cây đũa thần chỉ dành cho cô gái phép thuật. Sẽ rất khó để một chàng trai bình thường như ngài có thể nhấc nó lên được☆."
L43_1[1] = L44_1
L43_1[2] = L45_1
L44_1 = {}
L45_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_FALLEN_CA_ROSARIA_SPECIAL@AB_UI_UNIT_VOICE_NKM_UNIT_FALLEN_CA_ROSARIA_LOBBY_TOUCH_NORMAL_2"
L46_1 = "Chúng ta gặp nhau lần đầu trên đường đến trường. Ta đang ngậm miếng bánh mì nướng trong miệng và chạy va vào ngài ở một góc đường. Ồ, ta đoán là ngài sẽ không nhớ đâu. Ngài bị đẩy lùi lại 20 mét và bất tỉnh sau khi chúng ta va chạm☆."
L44_1[1] = L45_1
L44_1[2] = L46_1
L45_1 = {}
L46_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_FALLEN_CA_ROSARIA_SPECIAL@AB_UI_UNIT_VOICE_NKM_UNIT_FALLEN_CA_ROSARIA_LOBBY_TOUCH_NORMAL_3"
L47_1 = "Khi ngài gặp một nhân vật phản diện, hãy gọi ta, cô gái phép thuật Rosaria. Ta sẽ chăm sóc tất cả bọn họ bằng phép thuật tình yêu của mình. Ngài hỏi phép thuật của ta có liên quan gì đến tình yêu? Hmm... Cả hai đều nóng tới mức tan chảy mọi thứ☆?"
L45_1[1] = L46_1
L45_1[2] = L47_1
L46_1 = {}
L47_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_FALLEN_CA_ROSARIA_SPECIAL@AB_UI_UNIT_VOICE_NKM_UNIT_FALLEN_CA_ROSARIA_LOBBY_TOUCH_NORMAL_4"
L48_1 = "Ta là cô gái kỳ diệu của tình yêu. Tất cả tình yêu trên thế giới này là nguồn sức mạnh của ta. Tình yêu trong sáng, ngây thơ cũng được, nhưng ta có thể hút thêm sức mạnh từ nỗi ám ảnh hoặc drama. Ồ, hãy giữ bí mật chuyện đó nhé, được chứ☆?"
L46_1[1] = L47_1
L46_1[2] = L48_1
L47_1 = {}
L48_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_FALLEN_CA_ROSARIA_SPECIAL@AB_UI_UNIT_VOICE_NKM_UNIT_FALLEN_CA_ROSARIA_LOBBY_TOUCH_LIFETIME_3"
L49_1 = "Cuộc sống học đường của một cô gái phép thuật nên kín đáo. Nếu ai đó gây sự với ta, ngài phải bảo vệ ta. Ngài không cần phải giỏi chiến đấu. Ta sẽ đốn ngã họ và ngài chỉ cần leo lên trên thôi☆."
L47_1[1] = L48_1
L47_1[2] = L49_1
L48_1 = {}
L49_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_FALLEN_CA_ROSARIA_SPECIAL@AB_UI_UNIT_VOICE_NKM_UNIT_FALLEN_CA_ROSARIA_LOBBY_TOUCH_LIFETIME_4"
L50_1 = "*Thở dài* ta đã có một ngày mệt mỏi khi lại phải cứu thế giới. Sẽ thật tuyệt nếu ai đó lấy cho ta bắp rang và xoa bóp vai cho ta... Ngồi xuống đi, Doma; Ta không có nói với ngài."
L48_1[1] = L49_1
L48_1[2] = L50_1
L49_1 = {}
L50_1 = "AB_UI_SKIN_VOICE_NKM_UNIT_FALLEN_CA_ROSARIA_SPECIAL@AB_UI_UNIT_VOICE_NKM_UNIT_FALLEN_CA_ROSARIA_WORLDMAP_CHECK"
L51_1 = "Căn cứ biến hình của riêng một cô gái phép thuật... Nó không có gì bắt mắt, nhưng nó còn tốt hơn một phòng thay đồ."
L49_1[1] = L50_1
L49_1[2] = L51_1
