L5_1 = "SI_UNIT_SKILL_DESC_C_JAPAN_SETSUNA_RA_HYPER_LV1_ver2"
L6_1 = "Tạo ra một cơn lốc mạnh mẽ chữa lành +30% HP của tất cả đơn vị đồng minh ngoại trừ bản thân và 15% HP cho bản thân, trong khi gây sát thương AoE cho các đơn vị kẻ thù (Không Tự hồi phục trong Gauntlet). Tạo [Hoa Nở Dưới Trăng] ở mỗi vị trí của cô ấy và ở phía trước khi ra đòn Kỹ Năng Tối Thượng. Tất cả hoa của [Hoa Nở Dưới Trăng], đặt lại thời gian và liên tục chữa trị đồng minh ở gần tương ứng 2,5% HP trong 15 giây. (Tối đa 1 Hoa Nở Dưới Trăng được tạo ra thông qua phương pháp này)"
L4_1[1] = L5_1
L4_1[2] = L6_1
