L6_1 = "SI_UNIT_SKILL_DESC_C_JAPAN_SETSUNA_RA_SKILL_LV1_ver2"
L7_1 = "Triệu hồi một cơn gió giúp chữa lành 15% HP của tất cả đồng minh và 7,5% HP cho bản thân(Không Tự hồi phục trong Gauntlet). Gây sát thương AoE cho các kẻ thù."
L5_1[1] = L6_1
L5_1[2] = L7_1
L6_1 = {}
L7_1 = "SI_UNIT_SKILL_DESC_HARMONY_C_BASS_HYPER_LV1_ver2"
L8_1 = "Chơi đại vĩ cầm độc tấu hồi máu cho tất cả đồng minh (không bao gồm Tàu) 40% HP tối đa của họ trong 5 giây. Sau đó, cô ấy sẽ gây sát thương lên tất cả kẻ địch 3 lần, vô hiệu hóa 1 hiệu ứng không Vĩnh viễn khỏi mục tiêu với đòn đánh cuối cùng. V.T.A.M đồng minh nhận thêm 10% HP tối đa sau khi màn biểu diễn kết thúc.(Không Tự hồi phục trong Gauntlet)."
