L8_1 = "SI_UNIT_SKILL_DESC_HARMONY_C_BASS_PASSIVE_LV1_ver2"
L9_1 = "Chơi một nhịp ăn mòn sau khi cô ấy đánh ra một đòn chí mạng, đòn tấn công cơ bản tiếp theo của cô ấy sẽ hồi cho tất cả các đồng minh 2% HP tối đa của họ. (4% cho V.T.A.M đồng minh, không Tự hồi phục trong Gauntlet)."
L7_1[1] = L8_1
L7_1[2] = L9_1
L8_1 = {}
L9_1 = "SI_UNIT_SKILL_DESC_HARMONY_C_BASS_SKILL_LV1_ver2"
L10_1 = "Thực hiện một cú đánh mạnh mẽ với cung của cô ấy để tạo ra một nốt nhạc. Khi nốt nhạc va chạm với kẻ thù, nó sẽ phát nổ, gây sát thương AoE cho kẻ địch. Đồng minh (loại trừ Tàu) trong vụ nổ của nốt nhạc sẽ được buff phục hồi 20% HP tối đa của họ trong 1 giây. (Tối đa 2 cộng dồn, Không Tự hồi phục trong Gauntlet)."
