L39_1 = {}
L40_1 = "SI_SKIN_DESC_NKM_UNIT_JAPAN_CA_SENHIME_MEMORIAL"
L41_1 = "Cô cảm thấy rất ngại ngùng và bối rối trong bữa tiệc xa lạ, sao bạn không giúp cô ấy một chút nhỉ? \nCô không quen mặc váy đến mức bước đi thật lúng túng, nhưng...\nĐôi mắt cô vẫn ánh lên cái nhìn mạnh mẽ. \nKhát khao bảo vệ những người cô yêu thương không bao giờ phai nhạt. \n\n<color=#ffd34c>Ông Chủ tới rồi ạ. Tôi sẽ hộ tống ngài. </color>"
L39_1[1] = L40_1
L39_1[2] = L41_1
L40_1 = {}
L41_1 = "SI_SKIN_TITLE_NKM_UNIT_KNIGHT_C_HOLY_MEMORIAL"
L42_1 = "Ký Ức Khao Khát"
L40_1[1] = L41_1
L40_1[2] = L42_1
L41_1 = {}
L42_1 = "SI_SKIN_DESC_NKM_UNIT_KNIGHT_C_HOLY_MEMORIAL"
L43_1 = "Vũ hội Arcadena ban đầu được tổ chức để thờ một vị thần.\nTrang phục thiêng liêng dành cho thánh nữ, thứ phụ kiện được tặng bởi người yêu của mình.\nÁnh sáng không bị làm mờ bởi thời gian sẽ làm cô ấy trở thành ngôi sao của vũ hội.\n\n<color=#ffd34c>Tối nay, tôi mong ngài có thể nhảy với tôi, vì đây là điệu nhảy tôi đã tập tới mức hoàn hảo vì ngài đấy.</color>"
L41_1[1] = L42_1
L41_1[2] = L43_1
