L30_1 = "SI_EPISODE_EPISODE_DESC_NKM_MAIN_BATTLE_EP11_1_2"
L31_1 = "Các phòng giam ở rìa Acheron được dùng để giam giữ những tù nhân nguy hiểm nhất. Nó nằm ở rìa nên nếu có chuyện gì xảy ra, phần này sẽ bị tách ra và đưa vào không gian xa xăm."
L29_1[1] = L30_1
