L3_1 = {}
L4_1 = "REACTOR_DESC_1201"
L5_1 = "Một quả cầu được làm từ linh hồn. Thi hành sự trừng phạt thần thánh bằng cách trút cơn bão xuống con người mờ mắt bởi lòng tham. Lò Phản Ứng phản ánh sự giận dữ khi mất đi một người thân yêu như một nguồn gia tăng sức mạnh."
L3_1[1] = L4_1
L3_1[2] = L5_1
L4_1 = {}
L5_1 = "REACTOR_DESC_1223"
L6_1 = "Cẩm nang của Hội Đồng Điều Tra có chứa nhiều câu trả lời khác nhau. Cuốn sách rất dày do có rất nhiều đáp án chi tiết cho mọi tình huống. Lò Phản Ứng phản ánh sự tận tâm như một nguồn gia tăng sức mạnh."
L4_1[1] = L5_1
L4_1[2] = L6_1
L5_1 = {}
L6_1 = "REACTOR_DESC_1256"
L7_1 = "Một vũ khí được mài giũa bởi vô số điều ước và sở hữu sức mạnh thần thánh. Khi người chủ ban đầu của nó đã qua đời, người tạo ra thanh kiếm đã thay thế vị trí và sử dụng nó. Lò Phản Ứng phản ánh ý chí đáp lại những lời cầu nguyện như một nguồn gia tăng sức mạnh."
