L16_1 = "SI_UNIT_SKILL_DESC_JAPAN_C_CRAFTER_ATTACK_LV1"
L17_1 = "Dùng búa gây sát thương AoE cho kẻ địch phía trước. Đánh ra một đòn tấn công nâng cao khi cô ấy vào trạng thái [Đã Chuẩn Bị]. Một đòn tấn công nâng cao sẽ đặt lại thời gian buff Kỹ năng Đặc Biệt."
L15_1[1] = L16_1
L15_1[2] = L17_1
L16_1 = {}
L17_1 = "SI_UNIT_SKILL_DESC_JAPAN_C_CRAFTER_HYPER_LV1"
L18_1 = "Tập hợp năng lượng của ngọn lửa vào chiếc búa và cấp cho DMG RES cận chiến +60% và DMG RES Tầm Xa +60% cho các đơn vị Counter đồng minh trên chiến trường (Không bao gồm bản thân và quái triệu hồi). Hiệu ứng này giảm dần 10% sau mỗi 3 giây cho đến khi hết tác dụng. Sau đó, cô đập cây búa xuống và gây sát thương diện rộng cho kẻ địch. Kẻ địch trúng đòn sẽ bị Choáng◇ trong 4 giây."
L16_1[1] = L17_1
