L24_1 = "REACTOR_DESC_1243"
L25_1 = "Một vũ khí tự động hoạt động dựa trên mệnh lệnh của người dùng. Khi được đưa ra một mệnh lệnh bất ngờ, nó sẽ áp dụng phán đoán riêng của mình tùy vào hoàn cảnh. Lò Phản Ứng phản ánh niềm đam mê thất thường như một nguồn tăng sức mạnh."
