L31_1 = "SI_BOSS_DESC_S2_03"
L32_1 = "Lãnh đạo của một giáo phái tôn giáo mới được cho là một phe của Hiệp hội Nghiên Cứu Siêu Nhiên Eckhart.\nHắn ta bị truy nã trên toàn thế giới vì lãnh đạo một nhóm kẻ phản bội tự xưng đã ngẫu nhiên tấn công các cơ sở cách ly bí mật ở các khu vực khác nhau để lấy lại Mảnh Vỡ của Hồ.\nHắn ta sử dụng một loại năng lượng không xác định, và những sợi xích do hắn ta sử dụng phải được xử lý một cách thận trọng."
L30_1[1] = L31_1
L30_1[2] = L32_1
L31_1 = {}
L32_1 = "REACTOR_DESC_1170"
L33_1 = "Một tấm bịt mắt được thiết kế để chặn tầm nhìn và trói buộc số phận. Cô đã chôn vùi sức mạnh và ký ức của mình trong sự khoái lạc. Lò Phản Ứng phản ánh nỗi đau vui sướng như một nguồn tăng sức mạnh."
